(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,327030,(e,o,a)=>{o.exports=JSON.parse('{"nameplate.???":"???","nameplate.Dark Figure":"Figura Sombria","nameplate.Eerie Voice":"Voz Sinistra","nameplate.Elder Grah":"Elder Grah","nameplate.Eriole":"Eriole","nameplate.Grahdens":"Grahdens","nameplate.Kar & Seria":"Kar & Seria","nameplate.Karl":"Karl","nameplate.Lin":"Lin","nameplate.Lugina":"Lugina","nameplate.Man\'s Voice":"Voz de Homem","nameplate.Mare":"Mare","nameplate.Mysterious Man":"Homem Misterioso","nameplate.Mysterious Woman":"Mulher Misteriosa","nameplate.Paris":"Paris","nameplate.Seria":"Seria","nameplate.Seria & Karl":"Seria & Karl","nameplate.Seria & Lugina":"Seria & Lugina","nameplate.Seria・Lugina":"Seria・Lugina","nameplate.Tilith":"Tilith","nameplate.Tilith & Seria":"Tilith & Seria","nameplate.Woman\'s Voice":"Voz de Mulher","nameplate.Zebra":"Zebra","nameplate.静かな男の声":"Voz de Homem Calmo","story.map1-dungeon0-1end.001":"Agora você pode obter materiais na <color=00FF00>Fazenda</color> em Village of the Venturer!","story.map1-dungeon0-2end.001":"Agora você pode obter materiais na <color=00FF00>Montanha</color> em Village of the Venturer!","story.map1-dungeon0-3end.001":"Agora você pode acessar a <color=00FF00>Casa das Esferas</color> em Village of the Venturer!","story.map1-dungeon0-3end.002":"Na Casa das Esferas, você pode usar Materiais para forjar <color=00FFFF>Esferas</color> e equipá-las nas suas Unidades.","story.map1-dungeon0-3end.003":"Forje Esferas poderosas para aumentar a força das suas Unidades!","story.map1-dungeon1.001":"<size=13>Que calor! <wait=40>Quero ir pra casa! <wait=40>Isso é insuportável...","story.map1-dungeon1.002":"<size=20>Ah! <wait=20><rep_handlename>!","story.map1-dungeon1.003":"Ei, você está atrasado! <wait=40>Onde você se meteu?!","story.map1-dungeon1.004":"Como você me deixa esperando nesta caverna fervendo!","story.map1-dungeon1.005":"Já estou começando a me preocupar com a nossa jornada...","story.map1-dungeon1.006":"Bom, <wait=40>eu prometi que explicaria direitinho o que está acontecendo...","story.map1-dungeon1.007":"É sério, então preste atenção, tá?","story.map1-dungeon1.008":"Grand Gaia está no meio de uma grande crise...","story.map1-dungeon1.009":"Isso porque, entre os deuses poderosos que olham por nós, alguns foram consumidos pelo mal.","story.map1-dungeon1.010":"Desafiando o Sagrado Imperador Karna Masta, <wait=19>eles agora espalham o caos.","story.map1-dungeon1.011":"Entre essas forças malignas, <wait=40>os poucos com os poderes mais excepcionais são conhecidos como...","story.map1-dungeon1.012":".<wait=10>.<wait=10>.<wait=10>os Quatro Deuses Caídos.","story.map1-dungeon1.013":"Eles já foram deuses de alto escalão...","story.map1-dungeon1.014":"...<wait=20>Mas agora querem tomar Grand Gaia para si.","story.map1-dungeon1.015":"Os Quatro Deuses Caídos não só fizeram dos monstros e espíritos seus subordinados,","story.map1-dungeon1.016":"...como também usaram seus poderes para invocar e manipular os heróis lendários de Grand Gaia.","story.map1-dungeon1.017":"Se não os detivermos, <wait=40>Grand Gaia será destruída...","story.map1-dungeon1.018":"Até o Sagrado Imperador Karna Masta e os outros deuses...","story.map1-dungeon1.019":"...<wait=20>só conseguem contê-los por um tempo.","story.map1-dungeon1.020":"Foi por isso que o Lord Lucius abriu o Portal que leva a este mundo.","story.map1-dungeon1.021":"Ele quer contar com os seus poderes.","story.map1-dungeon1.022":"É por isso que só os escolhidos conseguem ver o portal.","story.map1-dungeon1.023":"O Lord Lucius tem grandes esperanças em você.","story.map1-dungeon1.024":"Então espero que você não nos decepcione, <wait=20><rep_handlename>!","story.map1-dungeon1.025":"Dito isso, <wait=40>seu primeiro alvo será um dos Quatro Deuses Caídos...","story.map1-dungeon1.026":"A Deusa da Criação, <wait=20>Maxwell!","story.map1-dungeon1.027":"Maxwell <wait=20>tomou St. Lamia. Antes uma terra sagrada, agora é a fortaleza dela.","story.map1-dungeon1.028":"Daqui de Mistral, <wait=40>você precisa ir além de Morgan para chegar lá.","story.map1-dungeon1.029":"É um caminho bem longo, <wait=40>mas tenho certeza de que você vai ficar bem!","story.map1-dungeon1.030":"Vamos passo a passo até você pegar o jeito de ser um Invocador!","story.map1-dungeon1.031":"Primeiro, para chegar a Morgan, precisamos seguir para a Torre de Mistral.","story.map1-dungeon1.032":"Para isso, <wait=20>vamos ter que atravessar a Caverna das Chamas.","story.map1-dungeon1.033":"Dizem por aí <wait=20>que esta caverna está infestada de feras ferozes.","story.map1-dungeon1.034":"Mesmo assim, <wait=20>você vai ficar bem!","story.map1-dungeon1.035":"<size=20>Argh! <wait=40>Não aguento mais esse calor!","story.map1-dungeon1.036":"Vou voltar pra tomar um banho. Se cuida e vai na frente!","story.map1-dungeon2.001":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.002":"<size=36>Atchim!!","story.map1-dungeon2.003":"...Nossa,<wait=30> que frio!","story.map1-dungeon2.004":"Ei! <wait=40>Como você ousa deixar uma garota esperando num lugar tão gelado!","story.map1-dungeon2.005":"Brr... <wait=30>frio demais!!","story.map1-dungeon2.006":"Então, <wait=20>para chegar à Torre de Mistral <wait=40>você vai ter que cruzar o Campo Nevado de Egor e atravessar a floresta...","story.map1-dungeon2.007":"Depois passar pelo pântano, <wait=30>e então pelas ruínas...","story.map1-dungeon2.008":"Só de imaginar já parece longe, <wait=40>e isso sem contar como o clima pode ser extremo!","story.map1-dungeon2.009":"Enfim, <wait=20>você ainda tem um longo caminho até a torre.","story.map1-dungeon2.010":"Mas tome cuidado. <wait=20>Os inimigos ficam mais fortes conforme você se aproxima dela.","story.map1-dungeon2.011":"Se encontrar um inimigo que não consegue derrotar, <wait=20>talvez seja uma boa ideia voltar à masmorra anterior e treinar um pouco.","story.map1-dungeon2.012":"Ah, é, <wait=20>já está na hora de você montar seu esquadrão pensando nos elementos.","story.map1-dungeon2.013":"A maioria dos inimigos da caverna era do elemento fogo, então um esquadrão de Unidades de água teria dado uma baita vantagem!","story.map1-dungeon2.014":"Desta vez estamos num campo nevado. <wait=40>Acho que vamos ver muitos inimigos do elemento água por aqui.","story.map1-dungeon2.015":"Então... <wait=20>perguntinha surpresa! <wait=40>Qual elemento é forte contra água?","story.map1-dungeon2.016":"Isso, <wait=40>acertou!","story.map1-dungeon2.017":"Parece que você andou estudando. <wait=40>Isso aí, trovão vence água.","story.map1-dungeon2.018":"Por outro lado, Unidades de fogo ficam em desvantagem contra os inimigos do campo nevado, então cuidado.","story.map1-dungeon2.019":"...Brr <wait=60><size=24>...Brr!","story.map1-dungeon2.020":"<size=36>Atchim!!","story.map1-dungeon2.021":"Aff, <wait=20>não aguento mais. <wait=40>Vou pra casa!","story.map1-dungeon2.022":"...Ah, <wait=20>quase esqueci.","story.map1-dungeon2.023":"Parece que um cavaleiro invocado por Maxwell anda causando o caos em algum lugar perto do fim deste campo nevado.","story.map1-dungeon2.024":"Dizem que ele é bem forte. Tome cuidado!","story.map1-dungeon3.001":"Ah, <wait=20><rep_handlename>! <wait=40>Mandou bem atravessando aquele campo nevado.","story.map1-dungeon3.002":"Hmm, <wait=40>tenho que admitir que você parece mais imponente agora do que quando nos conhecemos.","story.map1-dungeon3.003":"Muito bem, <wait=20>hora de atravessar a Floresta das Feras!","story.map1-dungeon3.004":"Como o nome sugere, esta floresta está infestada de feras selvagens...","story.map1-dungeon3.005":"Mas o seu verdadeiro inimigo <wait=20>é quem anda caçando elas.","story.map1-dungeon3.006":"Ah, <wait=40>e você já equipou uma Esfera?","story.map1-dungeon3.007":"Você pode melhorar as habilidades das suas Unidades equipando Esferas nelas.","story.map1-dungeon3.008":"Como Invocador, você precisa saber disso se pretende sobreviver por muito tempo.","story.map1-dungeon3.009":"As Esferas podem ser forjadas na Casa das Esferas do seu mundo.","story.map1-dungeon3.010":"Equipe Esferas nas suas Unidades para montar um Esquadrão mais forte!","story.map1-dungeon3.011":"Fazer Esferas exige certos materiais que você precisa coletar primeiro.","story.map1-dungeon3.012":"Bom, enfim, <wait=20>boa sorte e lute com tudo!<br>","story.map1-dungeon4.001":"<size=18>Argh, <wait=20>que horror!! Que umidade absurda é essa?!","story.map1-dungeon4.002":"Meu cabelo e minha roupa estão todos grudentos e nojentos!!","story.map1-dungeon4.003":"Ah... <wait=20><rep_handlename>.","story.map1-dungeon4.004":"Você conseguiu atravessar a floresta. Pelo menos não perdi meu tempo te ensinando.","story.map1-dungeon4.005":"Ah, <wait=20>é verdade. <wait=40>Você está aproveitando bem o Spark?","story.map1-dungeon4.006":"Quando suas Unidades atacam ao mesmo tempo e você consegue um Spark, o dano causado aumenta muito.","story.map1-dungeon4.007":"É uma técnica muito importante. Ajuda principalmente contra inimigos difíceis.","story.map1-dungeon4.008":"Continue praticando até acertar o tempo e conseguir muitos Sparks!","story.map1-dungeon4.009":"<wait=20>Bom, vamos atravessar logo os Pântanos de Magutagal! Que nojo esse lugar...","story.map1-dungeon4.010":"Argh, <wait=20>os insetos estão me picando. Minhas pernas lisinhas vão ficar cheias de picadas se eu ficar mais aqui.","story.map1-dungeon4.011":"Chega! <wait=40>Vou te esperar nas ruínas!","story.map1-dungeon5.001":"Ah, <wait=20><rep_handlename>! <wait=40>Você finalmente chegou às ruínas!","story.map1-dungeon5.002":"Para ser sincera, <wait=20>quando nos conhecemos você parecia pouco confiável, <wait=20>perdido <wait=20>e totalmente alheio ao que acontecia ao seu redor...","story.map1-dungeon5.003":"Eu me perguntava mesmo... <wait=40>essa pessoa é mesmo um Invocador?","story.map1-dungeon5.004":"Mas parece que o Lord Lucius tinha razão. <wait=20>Você tem potencial, sim!","story.map1-dungeon5.005":"Aliás, <wait=20>imagino que você já conheça as Habilidades de Líder, né?","story.map1-dungeon5.006":"Para ganhar vantagem sobre o oponente ou compensar as fraquezas do seu Esquadrão...","story.map1-dungeon5.007":"é importante trocar de Líder para testar diferentes Habilidades de Líder.","story.map1-dungeon5.008":"Além disso, <wait=40>quando outro Invocador estiver ajudando você...","story.map1-dungeon5.009":"...a Habilidade de Líder dele também é ativada.","story.map1-dungeon5.010":"Isso é importante, então não esqueça!","story.map1-dungeon5.011":"Vamos, <wait=20>estamos a um passo da Torre de Mistral!","story.map1-dungeon5.012":"Estes, os Restos de Mirza, <wait=40>são o que sobrou de uma construção erguida há milhares de anos...","story.map1-dungeon5.013":"Mas ultimamente não ouvi falar de nenhuma criatura rondando por aqui.","story.map1-dungeon5.014":"Talvez, <wait=20>só talvez, <wait=20>você consiga passar sem nenhum problema!","story.map1-dungeon5.015":"Bom... <wait=20>só vamos saber quando você tentar.","story.map1-dungeon5.016":"Mas, considerando tudo o que você conquistou até agora, <wait=20>duvido que algo consiga barrar seu caminho!","story.map1-dungeon5.017":"Confie em si! Boa sorte!","story.map1-dungeon6.001":"Ah, <wait=20><rep_handlename>.<br><wait=40>Você saiu vivo das ruínas...","story.map1-dungeon6.002":"Brr... <wait=20>Este lugar é frio e assustador. <wait=40>Olha só aquela construção suspeita ali.","story.map1-dungeon6.003":"Ouvi dizer que é conhecida como Ninho de Monstros...","story.map1-dungeon6.004":"Aquele lugar me dá arrepios!","story.map1-dungeon6.005":"E ultimamente há relatos de um espadachim misterioso rondando a área.","story.map1-dungeon6.006":"<size=20>N-<wait=10>Não <size=19>que <size=18>e-<size=17>eu <size=16>esteja <size=15>com <size=14>m-<size=13>me-<size=12>medo, <size=11>tá<size=9>?!","story.map1-dungeon6.007":"E-Enfim, <wait=20>parece que ele usa uma roupa esquisita e empunha uma espada estranha. <wait=20>Mesmo assim, não subestime o poder dele.","story.map1-dungeon6.008":"Fique sempre alerta...","story.map1-dungeon6.009":"<size=20>Iiih!!<br><wait=20><size=18>A-<size=20>Alguma <size=16>coisa <size=19>caiu <size=17>no <size=18>m-<size=15>meu <size=17>braço<size=19>...","story.map1-dungeon6.010":"Ah, <wait=20>uma folha?<br><wait=60>Que... <wait=20>que cara é essa?","story.map1-dungeon6.011":"E-Enfim, <wait=20>tome cuidado!","story.map1-dungeon6.012":"Depois de passar por aqui, <wait=20>estaremos ao pé da Torre de Mistral!","story.map1-dungeon6.013":"Boa sorte, <wait=20><rep_handlename>!","story.map1-dungeon7.001":"Finalmente chegamos à Torre de Mistral.","story.map1-dungeon7.002":"Mesmo a torre ficando dentro de Mistral, Maxwell já assumiu o controle dela.","story.map1-dungeon7.003":"Para ser sincera, <wait=20>os inimigos que enfrentamos até agora não são nada perto dos subordinados de Maxwell.","story.map1-dungeon7.004":"Precisamos estar totalmente preparados para vencer esta batalha e libertar a torre do controle de Maxwell.","story.map1-dungeon7.005":"No último andar <wait=20>aguarda um monstro que dizem ter sido criado pela própria Maxwell.","story.map1-dungeon7.006":"Mas não podemos nos dar ao luxo de ver você ser esmagado aqui.","story.map1-dungeon7.007":"Ainda estamos longe de St. Lamia, onde Maxwell está à espreita.","story.map1-dungeon7.008":"Tenho certeza de que você vai ficar bem. <wait=40>Agora você tem até o meu respeito. <wait=20>Confie mais em si!","story.map1-dungeon7.009":"Vamos, <wait=40><rep_handlename>!","story.map1-dungeon7.010":"Liberte seu poder <wait=20>e livre Mistral das garras do mal!","story.map1-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_clear.002":"<size=21>Aí está você!</size>","story.map1-dungeon_ex_clear.003":"<rep_handlename>! <wait=40>Você conseguiu!","story.map1-dungeon_ex_clear.004":"Detectamos o fim de um poder tremendo.","story.map1-dungeon_ex_clear.005":"Parece que você derrotou Skramya.","story.map1-dungeon_ex_clear.006":"Eu sabia que, se alguém conseguiria, era você!","story.map1-dungeon_ex_clear.007":"Ah, <wait=20>você não se feriu nem nada, né?","story.map1-dungeon_ex_clear.008":"Eu cuido de você quando voltarmos!","story.map1-dungeon_ex_clear.009":"Hehe, brincadeirinha.","story.map1-dungeon_ex_clear.010":"Hum, <wait=20>graças a você ter resolvido isso, obtivemos várias informações novas.","story.map1-dungeon_ex_clear.011":"Parece que há muito tempo uma pequena nação da Região de Mystral tentou usar o poder de Skramya.","story.map1-dungeon_ex_clear.012":"O plano saiu pela culatra e, em sua fúria, Skramya a destruiu.","story.map1-dungeon_ex_clear.013":"A ira de Skramya continuou, e ele seguiu rumo a outras nações.","story.map1-dungeon_ex_clear.014":"Porém, um único herói apareceu e, com bravura, selou Skramya.","story.map1-dungeon_ex_clear.015":"Depois disso, parece que Skramya continuou adormecido nas Montanhas de Egor sem nunca ser perturbado.","story.map1-dungeon_ex_clear.016":"Eu adoraria saber que tipo de herói era esse, mas não temos mais informações.","story.map1-dungeon_ex_clear.017":"Espero que um dia a gente descubra mais sobre essa pessoa.","story.map1-dungeon_ex_clear.018":"Bom, então, <wait=40>aviso você se tivermos mais informações!","story.map1-dungeon_ex_clear.019":"Boa sorte na sua investigação de Grand Gaia!","story.map1-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_open.002":"O-<wait=20>Olá...","story.map1-dungeon_ex_open.003":"Alguém está me ouvindo?","story.map1-dungeon_ex_open.004":"Está me ouvindo, <wait=40>senhor?","story.map1-dungeon_ex_open.005":"Ah! <wait=40>Consegui falar com você!","story.map1-dungeon_ex_open.006":"<rep_handlename>!","story.map1-dungeon_ex_open.007":"Você já chegou às Montanhas de Egor!","story.map1-dungeon_ex_open.008":"Eu sabia que você conseguiria!","story.map1-dungeon_ex_open.009":"Ah, <wait=20>deixe-me me apresentar mais uma vez.","story.map1-dungeon_ex_open.010":"Sou Lin Merylham, do Suporte Logístico...","story.map1-dungeon_ex_open.011":"...do Departamento de Investigação do Escritório de Pesquisa de Grand Gaia, ao seu dispor.","story.map1-dungeon_ex_open.012":"Hoje...","story.map1-dungeon_ex_open.013":"...<rep_handlename>, como membro do Exército de Invocadores do Salão dos Invocadores de Akras...","story.map1-dungeon_ex_open.014":"...pedimos que você investigue as Montanhas de Egor!","story.map1-dungeon_ex_open.015":"Elas ficam na Região de Mystral, e a investigação atrasou porque estavam sob o controle de Maxwell...","story.map1-dungeon_ex_open.016":"...mas, como ela foi derrotada, agora podemos entrar e investigar com mais cuidado!","story.map1-dungeon_ex_open.017":"Existem mesmo Invocadores impressionantes por aí, não é?","story.map1-dungeon_ex_open.018":"Dê o seu melhor também!","story.map1-dungeon_ex_open.019":"Ah, <wait=20>voltando ao assunto.","story.map1-dungeon_ex_open.020":"Sobre as Montanhas de Egor...","story.map1-dungeon_ex_open.021":"Segundo nossa investigação, há um demônio extremamente poderoso adormecido lá.","story.map1-dungeon_ex_open.022":"Ainda não temos certeza absoluta, mas...","story.map1-dungeon_ex_open.023":"...é muito provável que seja o demônio de gelo que dizem existir na Região de Mystral.","story.map1-dungeon_ex_open.024":"Hã?","story.map1-dungeon_ex_open.025":"Você não conhece Skramya, o demônio de gelo?","story.map1-dungeon_ex_open.026":"Fico muito surpresa em ouvir isso...","story.map1-dungeon_ex_open.027":"Entendido! <wait=40>Então deixe-me explicar!","story.map1-dungeon_ex_open.028":"Há muito tempo, na Região de Mystral...","story.map1-dungeon_ex_open.029":"...parece que existiam várias outras nações menores além do antigo reino de St. Lamia.","story.map1-dungeon_ex_open.030":"Dizem que todas foram destruídas pelos deuses depois que eles invadiram.","story.map1-dungeon_ex_open.031":"Porém, dizem que uma delas não foi destruída por um deus, mas por Skramya.","story.map1-dungeon_ex_open.032":"Por menor que fosse, um reino inteiro ser derrubado por um único demônio...","story.map1-dungeon_ex_open.033":"......","story.map1-dungeon_ex_open.034":".........","story.map1-dungeon_ex_open.035":"Hum, <wait=20>essas são todas as informações que tenho.","story.map1-dungeon_ex_open.036":"É tudo o que você precisa saber!","story.map1-dungeon_ex_open.037":"Ele tem o poder de destruir reinos!","story.map1-dungeon_ex_open.038":"É extremamente perigoso!","story.map1-dungeon_ex_open.039":"Como Invocador, você não pode deixá-lo à solta!","story.map1-dungeon_ex_open.040":"Nossa, você nem parece preocupado com o quanto ele é perigoso.","story.map1-dungeon_ex_open.041":"Mas esse demônio é brutal de verdade, <wait=20>então não se esforce demais!","story.map1-dungeon_ex_open.042":"Bom, então, aguardo um bom relatório seu!","story.map1-ending.001":"<size=24><rep_handlename>!!<br>Você conseguiu!!</size>","story.map1-ending.002":"Sua batalha contra o Juggernaut foi simplesmente <wait=40>incrível!","story.map1-ending.003":"Agora você pode se orgulhar de ser um Invocador habilidoso.","story.map1-ending.004":"Talvez... <wait=40>você seja o arqui-inimigo nato de Maxwell...","story.map1-ending.005":"Não, <wait=40>não tem talvez nenhum!","story.map1-ending.006":"Você deve ser o Invocador destinado a salvar Grand Gaia!","story.map1-ending.007":"...<wait=20>Ei! <wait=40>Você podia mostrar um pouco mais de gratidão a quem está te elogiando, né!","story.map1-ending.008":"Não dá pra mostrar um pouco de empolgação? <wait=40>Que vergonha ser a única animada com isso.","story.map1-ending.009":"Ah! <wait=40>O Lord Lucius está nos chamando!","story.map1-ending.010":"<speed=12>Finalmente podemos seguir para Morgan<wait=10>.<wait=20>.<wait=30>.","story.map1-ending.011":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Eu sou Lucius...<br><wait=40>Deus deste Portal...","story.map1-ending.012":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Salvador de St. Lamia...","story.map1-ending.013":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use meu poder <wait=40>e desbrave novas terras...","story.map1-ending.014":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Siga em frente <wait=20>e use seu poder para trazer paz a este mundo...","story.map1-ending.015":"<anchor=center><color=000000><speed=5><size=12>...Acorde!","story.map1-ending.016":"<anchor=center><color=000000><speed=7><size=18>...Está me ouvindo?","story.map1-ending.017":"<anchor=center><color=000000><speed=15><size=40><rep_handlename>, acorde!!","story.map1-ending.018":"Aff, <wait=40>você dorme demais!!","story.map1-ending.019":"O quê? <wait=40>Onde estamos? Isto é Morgan... <wait=20>Morgan!","story.map1-ending.020":"Não é maravilhoso? <wait=20>Os portões de Morgan finalmente se abriram.","story.map1-ending.021":"Finalmente, hein... <wait=20>Morgan...","story.map1-ending.022":"Este lugar já foi famoso por suas paisagens deslumbrantes...","story.map1-ending.023":"Mas muitos anos se passaram, <wait=20> e desde então ele caiu nas mãos de Maxwell.","story.map1-ending.024":"Os monstros daqui são muito mais fortes que os de Mistral...","story.map1-ending.025":"Não sabemos o que nos espera, <wait=40>então é melhor você voltar à sua vila e se preparar.","story.map1-ending.026":"Vou esperar aqui.","story.map1-ending.027":"Quando você voltar, vamos rumo à Torre de Morgan, <wait=19>e lá poderemos libertar esta terra!","story.map1-ending.028":"Bom, então, <wait=20>até mais!","story.map10-dungeon1.001":"<size=20>Você está atrasado! <wait=40>Onde você estava, <rep_handlename>!</size>","story.map10-dungeon1.002":"Estou me esforçando para salvar seu amigo, e você ainda tem a ousadia de me fazer esperar!","story.map10-dungeon1.003":"Seu idiota <size=20>lerdo</size>!","story.map10-dungeon1.004":"Sei que é um pedido dos Invocadores Anciãos, mas mesmo assim, por que eu tenho que ir atrás dele?","story.map10-dungeon1.005":"Ei, que cara é essa?","story.map10-dungeon1.006":"Você não acha que eu vou abandonar esta missão, acha?","story.map10-dungeon1.007":"<size=20>Não brinque comigo!</size>","story.map10-dungeon1.008":"Depois que eu cumprir perfeitamente minhas responsabilidades, quem vai parecer um tolo é aquele farsante do Karl.","story.map10-dungeon1.009":"Não vou ter muitas outras chances como esta.","story.map10-dungeon1.010":"Por isso é melhor você tomar jeito e me ajudar!","story.map10-dungeon1.011":"Se fizer isso, talvez a gente consiga terminar logo a investigação aqui.","story.map10-dungeon1.012":"Não sei se isto era a capital do Império de Agni ou não, essas velhas ruínas empoeiradas são todas iguais.","story.map10-dungeon1.013":"<size=20>Ei!</size>","story.map10-dungeon1.014":"Pare de enrolar e comece a procurar aquele preguiçoso do Karl!","story.map10-dungeon1.015":"Hmm?","story.map10-dungeon1.016":"Por onde você deveria começar?","story.map10-dungeon1.017":"Você é mesmo um idiota!","story.map10-dungeon1.018":"Fico me perguntando se essa cabeça sobre seus ombros é só enfeite.","story.map10-dungeon1.019":"Mas aquela discípula, a Mare, ainda está atrás de você, não está?","story.map10-dungeon1.020":"Se você causasse um tumulto aqui, sem dúvida ela viria usando o Karl como moeda de troca.","story.map10-dungeon1.021":"Essa seria nossa chance de resgatar aquele imbecil do Karl.","story.map10-dungeon1.022":"Se entendeu, continue fingindo que investiga como o tolo que você é e faça o máximo de barulho que puder!","story.map10-dungeon2.001":"<size=20>Droga! </size><wait=40><size=22>Que irritante!","story.map10-dungeon2.002":"O que aquela mulher de cara pálida pensa que está fazendo, se escondendo da gente!","story.map10-dungeon2.003":"Ei! <wait=40><rep_handlename>!","story.map10-dungeon2.004":"Você podia fazer um pouco mais de barulho, não acha?","story.map10-dungeon2.005":"Vá correr por aí a céu aberto como você sempre faz, onde é mais fácil te ver!","story.map10-dungeon2.006":"Que patético, você não consegue nem servir de isca!","story.map10-dungeon2.007":"Nngh! <wait=40>Por mais tolerante que eu seja, você está me levando ao limite.","story.map10-dungeon2.008":"Não posso mais esperar por aquela discípula.","story.map10-dungeon2.009":"Vou atrás do Karl sozinho!","story.map10-dungeon2.010":"Você também procura por ele por conta própria!","story.map10-dungeon2.011":"Não sou bonzinho o bastante para proteger alguém que não me serve para nada.","story.map10-dungeon2.012":"Então não venha atrás de mim, entendeu?","story.map10-dungeon2.013":"<size=20>Ei! <rep_handlename>!</size>","story.map10-dungeon2.014":"Quase esqueci de te dizer.","story.map10-dungeon2.015":"Você não pode de jeito nenhum se deixar capturar por aquela discípula.","story.map10-dungeon2.016":"Tenho certeza de que, se você fosse capturado, de algum jeito eu acabaria encarregado de salvar você também.","story.map10-dungeon2.017":"Não aguento mais pedidos problemáticos.","story.map10-dungeon2.018":"Quer dizer, se você fosse capturado, seria melhor ela simplesmente te esmagar em pedacinhos.","story.map10-dungeon2.019":"<size=20>Entendeu, né!?</size>","story.map10-dungeon3.001":"Parece que finalmente me livrei daquelas pestes.","story.map10-dungeon3.002":"Hmm. <wait=40>Por que essa cara de surpresa?","story.map10-dungeon3.003":"Parece que você finalmente está sozinho.","story.map10-dungeon3.004":"Até um humano tolo poderia prever que eu apareceria diante de você, minha presa.","story.map10-dungeon3.005":"Ou será que você é tão burro que nem percebeu?","story.map10-dungeon3.006":"......","story.map10-dungeon3.007":"Está procurando aquela desculpa verde e mirrada de criatura viva?","story.map10-dungeon3.008":"Com certeza ele foi enganado pela informação falsa que deixei sobre o paradeiro de Karl.","story.map10-dungeon3.009":"Ele deve estar correndo desesperado por Agni neste exato momento.","story.map10-dungeon3.010":"Mesmo com aquela boca grande, ele ainda é só um humano.","story.map10-dungeon3.011":"Seus amiguinhos me deram bastante trabalho antes, já que eu não sabia da existência deles.","story.map10-dungeon3.012":"Porém, parece que agora não sobrou ninguém para te ajudar.","story.map10-dungeon3.013":"Eu gostaria de tentar mais uma vez tirar a sua vida.","story.map10-dungeon3.014":"......","story.map10-dungeon3.015":"Porém, você é o Invocador que já derrotou muitos deuses.","story.map10-dungeon3.016":"Devo deixar você se desgastar só mais um pouco.","story.map10-dungeon3.017":"Se quer salvar o Karl, venha atrás de mim.","story.map10-dungeon3.018":"Se não vier, a vida dele acaba.","story.map10-dungeon3.019":"Mesmo sabendo que o caminho está cheio de armadilhas, será que você ainda virá atrás de mim?","story.map10-dungeon3.020":"Hunf. <wait=40>Vocês, humanos, são mesmo seres tolos.","story.map10-dungeon3.021":"Avance com dificuldade para que seja mais fácil eu cuidar de você depois.","story.map10-dungeon3.022":"Mal posso esperar para ver você enfraquecido.","story.map10-dungeon4.001":"Então você atravessou o Planalto de Granasta.","story.map10-dungeon4.002":"Acho que eu deveria esperar isso de quem derrotou tanto Maxwell quanto Cardes.","story.map10-dungeon4.003":"......","story.map10-dungeon4.004":"Olhando para você, eu me lembro da guerra em que os humanos foram destruídos.","story.map10-dungeon4.005":"Aqueles humanos que foram tolos o bastante para achar que podiam se opor aos deuses.","story.map10-dungeon4.006":"Por falar nisso, naquela época havia outro humano tão persistente quanto você.","story.map10-dungeon4.007":"Parece que os outros humanos chamavam essa pessoa de herói.","story.map10-dungeon4.008":"Porém, ele ainda era tão indefeso e desesperadamente assustado quanto você está agora.","story.map10-dungeon4.009":"Por mais poderoso que ele fosse para um humano...","story.map10-dungeon4.010":"...isso não compensava o fato de ele ser pouco mais que um humano ignorante.","story.map10-dungeon4.011":"Você também vai acabar com uma expressão parecida.","story.map10-dungeon4.012":"Mal posso esperar para apreciar isso.","story.map10-dungeon4.013":"......","story.map10-dungeon4.014":"Hunf. <wait=40>Não tenho interesse nesse seu olhar.","story.map10-dungeon4.015":"Acho que só preciso fazer você sofrer mais um pouco.","story.map10-dungeon4.016":"O que acha disso?","story.map10-dungeon4.017":"Deixe-me ver até onde você consegue chegar sozinho.","story.map10-dungeon5.001":"<rep_handlename>. Então você ainda escolhe resistir.","story.map10-dungeon5.002":"Eu detesto esses seus olhos <wait=40>e a falta de desespero neles.","story.map10-dungeon5.003":"Como você ainda consegue ter esperança numa situação dessas?","story.map10-dungeon5.004":"Nenhum dos aliados que te apoiavam está mais por perto.","story.map10-dungeon5.005":"Nem mesmo seu amigo de infância.","story.map10-dungeon5.006":"Nem a garota Invocadora que vivia te ofendendo.","story.map10-dungeon5.007":"Nem o velho com as expectativas ridículas que tinha de você.","story.map10-dungeon5.008":"Nem aquela criatura incrivelmente vulgar.","story.map10-dungeon5.009":"Nem mesmo o deus de baixo escalão que esteve te usando esse tempo todo.","story.map10-dungeon5.010":"......","story.map10-dungeon5.011":"Ou será que você quer me dizer que, desde o início, nunca contou com mais ninguém?","story.map10-dungeon5.012":"E mesmo assim escolhe tentar desesperadamente salvar seus amigos?","story.map10-dungeon5.013":"Que ideia incompreensível.","story.map10-dungeon5.014":"......","story.map10-dungeon5.015":"Entendo, agora eu me lembro.","story.map10-dungeon5.016":"Por falar nisso, <wait=20>daquela vez, quando aquele homem estava afundado em problemas...","story.map10-dungeon5.017":"...ele despertou um novo poder dentro de si.","story.map10-dungeon5.018":"Ele carregava grandes asas de chamas nas costas.","story.map10-dungeon5.019":"Há muito tempo desejo esquecer a desonra daquele poder que ele empunhava.","story.map10-dungeon5.020":"Se eu devo supor que você tem o mesmo poder dentro de si, então não tenho mais tempo para brincadeiras.","story.map10-dungeon5.021":"Hunf...","story.map10-dungeon5.022":"Mas não posso continuar deixando você aí parado desperdiçando meu tempo.","story.map10-dungeon5.023":"A batalha entre Lord Zefalhua e Afla Dilith está próxima.","story.map10-dungeon5.024":"Preciso acabar com você antes que consiga interferir nas minhas previsões.","story.map10-dungeon5.025":"Está pronto?","story.map10-dungeon5.026":"Vou te mostrar um mundo de desespero como você nunca viu.","story.map10-dungeon5.027":"Não vou me conter, então agora contemple meu verdadeiro poder!","story.map10-dungeon5.028":"Receba-o com tudo o que você tem!","story.map10-dungeon6.001":"Já basta, <wait=40><rep_handlename>.","story.map10-dungeon6.002":"Você lutou bem contra os deuses até agora.","story.map10-dungeon6.003":"Porém, pelos ferimentos que cobrem seu corpo, vejo que você não consegue mais lutar.","story.map10-dungeon6.004":"Não vou permitir que Lucius e suas previsões avancem mais!","story.map10-dungeon6.005":"Morra!","story.map10-dungeon6.006":"<size=18>*Kliiiing*","story.map10-dungeon6.007":"Nngh!","story.map10-dungeon6.008":"Como você deixou uma mulher dessas te dar tanto trabalho?","story.map10-dungeon6.009":"Sério, <wait=20>você é mesmo um idiota.","story.map10-dungeon6.010":"Ei, controle-se!","story.map10-dungeon6.011":"Não se deixe derrotar antes de termos a chance de salvar o Karl!","story.map10-dungeon6.012":"Tolo! <wait=20>Ainda pretende se mexer mesmo ferido?","story.map10-dungeon6.013":"Não brinque comigo.","story.map10-dungeon6.014":"Achou mesmo que um ataque desses acabaria comigo?","story.map10-dungeon6.015":"Para uma discípula, você é bem estúpida.","story.map10-dungeon6.016":"Que coisa mais humana da sua parte.","story.map10-dungeon6.017":"<size=18>*Klaaaang*","story.map10-dungeon6.018":"Nngh!","story.map10-dungeon6.019":"Por que você está aí parado?","story.map10-dungeon6.020":"Será que a batalha com <rep_handlename> te deixou sem conseguir se mover?","story.map10-dungeon6.021":"Isso mesmo, <wait=20>quanto ao Karl, <wait=20>Lugina já está a caminho para resgatá-lo do Santuário Oceânico.","story.map10-dungeon6.022":"E você achou que o tinha enganado com tanta esperteza. <wait=20>Que pena.","story.map10-dungeon6.023":"Impossível.","story.map10-dungeon6.024":"Nngh, <rep_handlename>. <wait=20>Parece que você escapou da morte por pouco desta vez.","story.map10-dungeon6.025":"Mesmo que tudo o que voltou para você seja um Invocador coberto de ferimentos.","story.map10-dungeon6.026":"Vou destruir vocês dois assim que eu cuidar daquela criatura vulgar.","story.map10-dungeon6.027":"......","story.map10-dungeon6.028":"......<wait=40>Não a sinto mais.","story.map10-dungeon6.029":"Nngh.","story.map10-dungeon6.030":"*Arf* <wait=20>*arf* <wait=20>*Arf* ","story.map10-dungeon6.031":"E-<wait=20>Estou bem.","story.map10-dungeon6.032":"Só um pouco da dor voltou depois que ela foi embora.","story.map10-dungeon6.033":"Ainda assim, que bom que conseguimos enganá-la.","story.map10-dungeon6.034":"Olha...<wait=40>Não podemos ficar parados, precisamos ir para o Santuário Oceânico.","story.map10-dungeon6.035":"Tenho certeza de que é lá que o Karl está preso.","story.map10-dungeon6.036":"Que cara é essa?","story.map10-dungeon6.037":"Não tenho tempo para ficar sentado conversando com você.","story.map10-dungeon6.038":"Prometo que conversamos depois, então por enquanto vamos atrás do Karl.","story.map10-dungeon7.001":"*Arf* *arf* *arf*","story.map10-dungeon7.002":"Finalmente chegamos ao Santuário Oceânico.","story.map10-dungeon7.003":"Pelo visto, vocês estão quase no limite.","story.map10-dungeon7.004":"É ela de novo.","story.map10-dungeon7.005":"Reconheço a coragem necessária para ficar diante de mim tão machucados e arrasados como vocês estão.","story.map10-dungeon7.006":"Hunf. <wait=40>Quanta presunção sua.","story.map10-dungeon7.007":"Mesmo depois que eu te enganei para você me contar onde estava prendendo o Karl.","story.map10-dungeon7.008":"...Seus tolos.","story.map10-dungeon7.009":"Vejo que vocês abriram caminho até mim pela Enseada de Lognea.","story.map10-dungeon7.010":"Acham que conseguem escapar de mim com ferimentos assim?","story.map10-dungeon7.011":"Nngh...","story.map10-dungeon7.012":"Meus lacaios!","story.map10-dungeon7.013":"Reúnam-se aqui e livrem o mundo destes insetos!","story.map10-dungeon7.014":"O-O que é isso? <wait=20>De onde todos eles vieram!?","story.map10-dungeon7.015":"Não é vergonhoso para uma deusa como você convocar tantos só para lutar contra nós, humanos?","story.map10-dungeon7.016":"Pare com esse falatório tolo.","story.map10-dungeon7.017":"É aqui que finalmente vou me livrar de vocês.","story.map10-dungeon7.018":"Isso é tudo.","story.map10-dungeon7.019":"<rep_handlename>!","story.map10-dungeon7.020":"Arrependam-se da tola rebeldia contra os deuses e morram!","story.map10-dungeon7.021":"Nngh... <wait=40>Isso é ruim, <wait=40>são inimigos demais.","story.map10-dungeon7.022":"Não é do seu feitio ser tão tímido numa situação como esta.","story.map10-dungeon7.023":"Essa voz!","story.map10-dungeon7.024":"C-Como você...","story.map10-dungeon7.025":"E aí. <wait=40>Desculpe a demora.","story.map10-dungeon7.026":"Karl!","story.map10-dungeon7.027":"Como você...","story.map10-dungeon7.028":"Da última vez que verifiquei, você ainda estava trancado naquela sala...","story.map10-dungeon7.029":"Foi quando você veio verificar que eu percebi onde estava.","story.map10-dungeon7.030":"Ó deusa de tão pouca inteligência.","story.map10-dungeon7.031":"Como ousa...","story.map10-dungeon7.032":"Lugina! <wait=20>Por que demorou tanto!","story.map10-dungeon7.033":"Quieta!","story.map10-dungeon7.034":"Demorei um tempão para resgatá-lo graças à preguiça dele!","story.map10-dungeon7.035":"Eu já pedi desculpas.","story.map10-dungeon7.036":"Ah, é, e Seria...","story.map10-dungeon7.037":"Como você se deixou ficar nesse estado?","story.map10-dungeon7.038":"Não é culpa minha, um certo alguém estava me atrapalhando!","story.map10-dungeon7.039":"Tudo bem, vamos esquecer isso!","story.map10-dungeon7.040":"Temos algo para resolver aqui.","story.map10-dungeon7.041":"Não é, Mare?","story.map10-dungeon7.042":"Seu plano já desmoronou.","story.map10-dungeon7.043":"O que pretende fazer agora?","story.map10-dungeon7.044":"Humano, você ousa se achar acima dos deuses?","story.map10-dungeon7.045":"Eu te elogio por ter superado minhas expectativas.","story.map10-dungeon7.046":"Mas, apesar do meu respeito por você, agora vou abandonar meus planos e simplesmente mandar destruí-lo.","story.map10-dungeon7.047":"Eu, Mare, discípula do Lord Zevalhua, ordeno a vocês!","story.map10-dungeon7.048":"Meus lacaios!","story.map10-dungeon7.049":"Reúnam-se ao meu redor e destruam meus inimigos!","story.map10-dungeon7.050":"Matem todos os humanos diante de mim!","story.map10-dungeon7.051":"Parece que muitos deles já se reuniram aqui.","story.map10-dungeon7.052":"Tem muito mais deles do que antes.","story.map10-dungeon7.053":"Humanos. <wait=40>Vocês lutaram bem.","story.map10-dungeon7.054":"Vou me lembrar de vocês...","story.map10-dungeon7.055":"...e do fim trágico que vocês vão encontrar em breve.","story.map10-dungeon7.056":"Aonde você pensa que vai!","story.map10-dungeon7.057":"Saiam todos do meu caminho!","story.map10-dungeon7.058":"São tantos.","story.map10-dungeon7.059":"Karl, <wait=40>você está ferido...","story.map10-dungeon7.060":"Haha, <wait=20>aquela discípula só me deu uns sopapos, só isso...","story.map10-dungeon7.061":"Não tente disfarçar!","story.map10-dungeon7.062":"Mas, Seria, você também está ferida...","story.map10-dungeon7.063":"I-Isso é só...","story.map10-dungeon7.064":"Olhem só para todas essas criaturas patéticas!","story.map10-dungeon7.065":"Ei! <wait=40><rep_handlename>!","story.map10-dungeon7.066":"Cansei de ficar só correndo por aí.","story.map10-dungeon7.067":"Vá atrás daquela mulher pálida e derrube ela!","story.map10-dungeon7.068":"Eu cuido destes dois enquanto você estiver fora!","story.map10-dungeon7.069":"Não precisamos que você cuide da gente!","story.map10-dungeon7.070":"Desculpe te preocupar, <rep_handlename>.","story.map10-dungeon7.071":"Deixe as coisas aqui com a gente e vá atrás daquela discípula.","story.map10-dungeon7.072":"Prometo te compensar depois.","story.map10-dungeon7.073":"Contamos com você, <wait=20><rep_handlename>.","story.map10-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_clear.002":"<size=18>Está me...</size> <wait=20><size=20> *Bzz...zzz*</size>","story.map10-dungeon_ex_clear.003":"<size=20>*Bzz*</size> <size=18>...Senhor...?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_clear.004":"<size=18>*Bzz*</size><wait=20><size=20> Ah, pronto!</size>","story.map10-dungeon_ex_clear.005":"É tão difícil pegar sinal lá embaixo naquelas masmorras.","story.map10-dungeon_ex_clear.006":"Enfim, <wait=20>deixe-me contar o que descobri.","story.map10-dungeon_ex_clear.007":"Segundo a literatura antiga...","story.map10-dungeon_ex_clear.008":"...aquele lugar estava selado desde o período final do Império de Agni.","story.map10-dungeon_ex_clear.009":"Mas, 100 anos antes disso, houve um imperador que foi aprisionado lá em segredo.","story.map10-dungeon_ex_clear.010":"Muito tempo se passou sem que ninguém soubesse que ele estava lá embaixo. ","story.map10-dungeon_ex_clear.011":"Aquele imperador era temido por todos ao seu redor e visto como um tirano.","story.map10-dungeon_ex_clear.012":"Na verdade, <wait=20>não eram só seus súditos que o temiam, mas os filhos deles também.","story.map10-dungeon_ex_clear.013":"Um dia, uma criança que tinha sofrido nas mãos dele adoeceu e morreu.","story.map10-dungeon_ex_clear.014":"Foi por isso que ele foi aprisionado em segredo.","story.map10-dungeon_ex_clear.015":"Com o passar do tempo na masmorra escura como breu, a raiva do imperador cresceu junto com sua solidão.","story.map10-dungeon_ex_clear.016":"Ele renasceu como um fantasma imensamente poderoso e se vingou do império por 100 anos.","story.map10-dungeon_ex_clear.017":"Por causa disso, <wait=20>o fantasma do imperador foi selado junto com a masmorra.","story.map10-dungeon_ex_clear.018":"Ele ainda está em algum lugar lá embaixo, <wait=20>com a raiva crescendo a cada segundo.","story.map10-dungeon_ex_clear.019":"Dá medo só de pensar.","story.map10-dungeon_ex_clear.020":"Senhor, <wait=20>não precisa se forçar a encontrar esse fantasma!","story.map10-dungeon_ex_clear.021":"Você só precisa investigar a fundo o quão perigoso aquele lugar é.","story.map10-dungeon_ex_clear.022":"O-<wait=20>O quê?<wait=40> O que você acabou de dizer?","story.map10-dungeon_ex_clear.023":"Não acredito!","story.map10-dungeon_ex_clear.024":"Você foi lá e derrotou o fantasma do imperador enquanto eu fazia minha pesquisa!?","story.map10-dungeon_ex_clear.025":"Uau, Senhor...<wait=20>você é incrível.","story.map10-dungeon_ex_clear.026":"Mas espere! <wait=40>Espere só um segundo!","story.map10-dungeon_ex_clear.027":"Eu queria muito que você esperasse mais um pouquinho até eu terminar minha pesquisa...","story.map10-dungeon_ex_clear.028":"Hum...<wait=20> Bom, enfim!","story.map10-dungeon_ex_clear.029":"Da próxima vez, vou dar o meu melhor para colocar as informações nas suas mãos o mais rápido possível!","story.map10-dungeon_ex_clear.030":"Vou te provar que você não é o único que aprimorou suas habilidades!","story.map10-dungeon_ex_clear.031":"Entro em contato com você de novo em breve, então me aguarde!","story.map10-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_open.002":"<size=18>Se...</size> <wait=20><size=20>*Bzz...zzz*</size>","story.map10-dungeon_ex_open.003":"<size=20>*Bzz*</size> <size=18>...me...ouve?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_open.004":"<size=18>*Bzz*</size><wait=20><size=20>Senhor!</size>","story.map10-dungeon_ex_open.005":"Finalmente, conectamos!","story.map10-dungeon_ex_open.006":"Parece que você está num lugar com uma recepção bem ruim.","story.map10-dungeon_ex_open.007":"Enfim, <wait=20>deixe-me começar de novo.","story.map10-dungeon_ex_open.008":"Sou Lin Merylham, do Suporte Logístico...","story.map10-dungeon_ex_open.009":"...do Departamento de Investigação do Escritório de Pesquisa de Grand Gaia, ao seu dispor.","story.map10-dungeon_ex_open.010":"Confirmamos o desaparecimento de um grande poder na Região de Agni outro dia. ","story.map10-dungeon_ex_open.011":"Parece que isso fez uma estrutura subterrânea antes selada se romper. ","story.map10-dungeon_ex_open.012":"Segundo nossos registros, <wait=20>algo bem sinistro estava preso lá.","story.map10-dungeon_ex_open.013":"Sua missão desta vez é ir lá e dar um fim nisso...","story.map10-dungeon_ex_open.014":"...antes que consiga sair e causar algum estrago!","story.map10-dungeon_ex_open.015":"Parece que a estrutura já foi uma masmorra, muito tempo atrás.","story.map10-dungeon_ex_open.016":"Hã? <wait=40>Você já está lá?","story.map10-dungeon_ex_open.017":"Não me surpreende!","story.map10-dungeon_ex_open.018":"Muito bem, <wait=20>vou fazer o que puder para descobrir mais sobre a masmorra.","story.map10-dungeon_ex_open.019":"Terei novas informações para você antes de você terminar sua investigação.","story.map10-dungeon_ex_open.020":"Aguente só mais um pouquinho!","story.map10-ending.001":"S-<wait=20>Seus tolos...","story.map10-ending.002":"Como uma deusa como eu pôde ser derrotada por humanos...","story.map10-ending.003":"E-Então que seja!","story.map10-ending.004":"<size=20>Vou enterrar todos vocês junto com este santuário!</size>","story.map10-ending.005":"<size=14>*Rumble* *rumble*</size>","story.map10-ending.006":"<size=21>Não vou deixar isso acontecer!</size>","story.map10-ending.007":"Nngh, <wait=40>então você também sobreviveu!","story.map10-ending.008":"Tilith, discípula de Lucius!","story.map10-ending.009":"Estou aqui, <rep_handlename>!","story.map10-ending.010":"Muito bem, vamos todos sair daqui!","story.map10-ending.011":"Alto lá, <rep_handlename>!","story.map10-ending.012":"Não pense que já venceu!","story.map10-ending.013":"Não importa quantos de vocês se juntem.","story.map10-ending.014":"Diante do Lord Zevalhua vocês não são nada!","story.map10-ending.015":"E, além disso, a peça-chave entre vocês é...","story.map10-ending.016":"<size=15>*Rumble* *rumble*</size>","story.map10-ending.017":"Mare! <wait=40>Aceite, você perdeu!","story.map10-ending.018":"<rep_handlename>! <wait=40>Todos estão esperando!","story.map10-ending.019":"Vamos!","story.map10-ending.020":"<size=16>*Rumble* *rumble*</size>","story.map10-ending.021":"Nngh...","story.map10-ending.022":"<size=19>Lord Zevalhua...</size>","story.map10-ending.023":"<size=18>*Rumble* *rumble*</size>","story.map10-ending.024":"<rep_handlename>!","story.map10-ending.025":"Você conseguiu!","story.map10-ending.026":"Eu sabia que você conseguiria derrotar a Mare, meu <rep_handlename>!","story.map10-ending.027":"A-Ai...","story.map10-ending.028":"Voando de forma agressiva como sempre, pelo visto, <wait=40> Deusa.","story.map10-ending.029":"Não dá para ter só um pouquinho mais de cuidado?","story.map10-ending.030":"Ei, <wait=20>parem de reclamar, vocês dois!","story.map10-ending.031":"Mesmo assim, que bom que vocês dois estão bem, Karl e Seria.","story.map10-ending.032":"Fiquei muito preocupada carregando você, Seria, ferida desse jeito!","story.map10-ending.033":"Obrigada por isso...","story.map10-ending.034":"É, <wait=20>eu também sou grato a você, Deusa.","story.map10-ending.035":"E, claro, a você também, <rep_handlename>!","story.map10-ending.036":"Mas não deixe isso subir à cabeça, só faria a gente parecer mal.","story.map10-ending.037":"Desculpe por eu ter demorado tanto para me recuperar.","story.map10-ending.038":"Enfim, você foi incrível como sempre, <rep_handlename>!","story.map10-ending.039":"Você derrotou a Mare!","story.map10-ending.040":"É, <wait=20>isso mesmo.","story.map10-ending.041":"<rep_handlename>, <wait=40>tenho muito orgulho de poder te chamar de amigo próximo.","story.map10-ending.042":"Isso mesmo, Karl.","story.map10-ending.043":"Hum...","story.map10-ending.044":"Não quero estragar a festa, mas não estamos esquecendo alguém?","story.map10-ending.045":"É mesmo! <wait=40>Lugina!","story.map10-ending.046":"Onde ele pode estar?","story.map10-ending.047":"Quem é Lugina?","story.map10-ending.048":"Entendi, então você ainda não conheceu o Lugina pessoalmente, né, Deusa?","story.map10-ending.049":"Não acredito, <wait=40>quer dizer que você só trouxe a gente?","story.map10-ending.050":"Hum, <wait=40>para começar, eu nem sabia que havia mais alguém.","story.map10-ending.051":"Por acaso vocês estão falando daquela pessoa que estava meio enterrada no chão?","story.map10-ending.052":"<size=21>Lugina!</size>","story.map10-ending.053":"<size=22>Seus imbecis! <wait=40>Vou nocautear todos vocês!</size>","story.map10-ending.054":"Ei, pelo menos você chegou aqui inteiro.","story.map10-ending.055":"Heh... <wait=20>Você estava num estado e tanto lá atrás, Lugina.","story.map10-ending.056":"<size=20>Garota estúpida! <wait=40>Você vai levar a pior!","story.map10-ending.057":"Seria, eu disse para parar!","story.map10-ending.058":"Lugina, <wait=40>você realmente nos salvou desta vez.","story.map10-ending.059":"Obrigado.","story.map10-ending.060":"Heh, <wait=20>só ajudei vocês porque o Salão dos Invocadores me pediu.","story.map10-ending.061":"Sinceramente, não faria diferença quem fosse.","story.map10-ending.062":"Mesmo assim, como você sabia onde eu estava preso?","story.map10-ending.063":"Foi fácil.","story.map10-ending.064":"Eu sabia que aquela mulher tentaria pegar este cabeça-dura sozinho.","story.map10-ending.065":"Então eu sabia que, se eu facilitasse essa situação, ela com certeza viria correndo.","story.map10-ending.066":"Porém, ela era muito cautelosa.","story.map10-ending.067":"Karl, <wait=20>previ que ela usaria você como isca enquanto se aproximava aos poucos.","story.map10-ending.068":"O resto foi resolvido antes de eu sair de Elgaia.","story.map10-ending.069":"Tudo o que eu precisei fazer foi mandar esta garota burra salvar aquele imbecil.","story.map10-ending.070":"<size=20>Quem você está chamando de burra!</size>","story.map10-ending.071":"Bom, <wait=40>sua sugestão acabou me salvando.","story.map10-ending.072":"Assim que cheguei lá, mencionei para aquela discípula o nome do lugar próximo que você tinha me falado.","story.map10-ending.073":"Assim que eu disse, exatamente como você falou, ela foi embora.","story.map10-ending.074":"Heh, <wait=40>foi fácil adivinhar, já que eu sabia quando você chegaria.","story.map10-ending.075":"Não havia tantos lugares assim onde esconder alguém.","story.map10-ending.076":"Aquela discípula estúpida <wait=20>fez exatamente o que eu achei que faria.","story.map10-ending.077":"Ela partiu para o Santuário Oceânico para ver como estava o prisioneiro.","story.map10-ending.078":"E, com isso, me levou direto até ele.","story.map10-ending.079":"Uau, que incrível, Lugina.","story.map10-ending.080":"<size=19>É difícil imaginar alguém como você conseguindo algo assim.</size>","story.map10-ending.081":"<size=21>Como ousa!<\\\\size>","story.map10-ending.082":"Então você é o Lugina!","story.map10-ending.083":"Prazer em te conhecer!","story.map10-ending.084":"Eu sou Tilith, a deusa que cuida de <rep_handlename>.","story.map10-ending.085":"Sou discípula de Lucius.","story.map10-ending.086":"Uma deusa que é discípula de Lucius?","story.map10-ending.087":"Ei, <rep_handlename>!","story.map10-ending.088":"Essa garota é maluca ou o quê?","story.map10-ending.089":"Que malvado!","story.map10-ending.090":"E pensar que eu te trouxe de volta do Santuário Oceânico!","story.map10-ending.091":"Então foi você?","story.map10-ending.092":"Bom, se é assim...","story.map10-ending.093":"É, ela é uma deusa de verdade.","story.map10-ending.094":"<size=18>Não pode ser...</size>","story.map10-ending.095":"Aquele velho tolo do Grahdens.","story.map10-ending.096":"Do que diabos ele estava falando...","story.map10-ending.097":"Ah, e Lugina...","story.map10-ending.098":"Foi o Grahdens que pediu para você nos salvar, não foi?","story.map10-ending.099":"O que o velho está aprontando agora?","story.map10-ending.100":"O quê!? <wait=20>Como eu vou saber?","story.map10-ending.101":"Com certeza ele só está vagando por aí em algum lugar.","story.map10-ending.102":"Se estão falando do Ancião Grahdens, ele foi capturado por Zevalhua.","story.map10-ending.103":"É você...","story.map10-ending.104":"Quanto tempo, <rep_handlename>.","story.map10-ending.105":"Embora pareça que eu ainda não conheço nenhum dos seus amigos aí.","story.map10-ending.106":"Eu estava ansiosa para conhecer todos vocês.","story.map10-ending.107":"O que uma guarda imperial desprezível como você está fazendo aqui?","story.map10-ending.108":"Antes disso, como assim o velho foi capturado?","story.map10-ending.109":"He he he, <wait=20>não seja impaciente.","story.map10-ending.110":"Eu também tenho algumas coisas que quero perguntar.","story.map10-ending.111":"Como, por exemplo, por que você ainda está vivo mesmo depois de ser capturado por aquela discípula.","story.map10-ending.112":"Mas podemos discutir os detalhes em Milvana.","story.map10-ending.113":"Tudo bem para vocês dois...","story.map10-ending.114":"<rep_handlename> e Tilith, discípula do Lord Lucius?","story.map10-ending.115":"Sim, por mim está ótimo.","story.map10-ending.116":"Com certeza o Lord Lucius logo vai abrir um caminho para Milvana para nós.","story.map10-ending.117":"Isto já está virando uma dor de cabeça.","story.map10-ending.118":"Karl, <wait=40>você está bem?","story.map10-ending.119":"Grahdens...","story.map10-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Eu sou Lucius...<br><wait=40>Deus deste Portal...","story.map10-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você, <rep_handlename>,<wait=39> que desbloqueou Ryvern...","story.map10-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use meu poder <wait=40>e desbrave novas terras...","story.map10-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para trazer nova esperança a este mundo sem ordem...","story.map10-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você precisa ter fé no seu poder <wait=20>e continuar avançando...","story.map10-open.006":"<size=21><rep_handlename>! <wait=40>Por que demorou tanto!</size>","story.map10-open.007":"Fazendo esperar a pessoa que salvou sua vida, como você sempre faz, não acredito.","story.map10-open.008":"Tanto faz.","story.map10-open.009":"Vou ser bonzinho e explicar tudo para você e para essa sua cabeça de imbecil.","story.map10-open.010":"Por que foi você que me encontrou lá, é claro!","story.map10-open.011":"Eu tive uma visão.","story.map10-open.012":"Com minha mente genial, consegui prever o aperto em que você acabaria se metendo.","story.map10-open.013":"......","story.map10-open.014":"Você não acredita em mim, <wait=20>né?","story.map10-open.015":"Hunf, <wait=20>tanto faz.","story.map10-open.016":"Foi o velho Grahdens.","story.map10-open.017":"Ele me pediu para seguir todos vocês.","story.map10-open.018":"Foi um pedido direto dos Invocadores Anciãos para mim.","story.map10-open.019":"Isso prova que o Salão dos Invocadores confia na minha força!","story.map10-open.020":"<size=21>Ha ha ha ha!</size>","story.map10-open.021":"Enfim, <wait=20>o que eles queriam mesmo era que eu resgatasse aquele vagabundo do Karl.","story.map10-open.022":"......","story.map10-open.023":"Você vai me ajudar com isso.","story.map10-open.024":"Você não ousaria recusar o desejo da pessoa a quem deve a vida, ousaria?","story.map10-open.025":"Muito bem, vou seguir rumo ao Império de Agni.","story.map10-open.026":"Se as informações que consegui estiverem certas, o Karl está preso lá.","story.map10-open.027":"Não vai ser fácil, mas tudo começa no império.","story.map10-open.028":"Não é hora de hesitar! Ouviu bem?","story.map10-open.029":"Isso mesmo!","story.map10-open.030":"Aquela discípula, a Mare, ainda está de olho em você, não está?","story.map10-open.031":"É melhor você rezar para ela não te alcançar!","story.map10-open.032":"<size=22>Ha ha ha ha!</size>","story.map11-dungeon1.001":"<rep_handlename>...<wait=40>você está atrasado!! ","story.map11-dungeon1.002":"Pare de ser tão preguiçoso!","story.map11-dungeon1.003":"Sério...","story.map11-dungeon1.004":"Por que você fez a gente esperar tanto num lugar tão quente?","story.map11-dungeon1.005":"Ora, ora! <wait=20>Parece que vocês dois estão se dando muito bem.","story.map11-dungeon1.006":"<speed=15><size=21>Não brinque comigo! Para de brincar comigo!</size></speed>","story.map11-dungeon1.007":"Uau...<wait=20>vocês até falam exatamente a mesma coisa!","story.map11-dungeon1.008":"<speed=15><size=21>O que você disse?! Que que cê disse?!</size></speed>","story.map11-dungeon1.009":"Deusa, <wait=40>aquela é a Paris, da Guarda Imperial?","story.map11-dungeon1.010":"Eu te imploro, por favor, não coloque mais nenhum fardo nos meus ombros...","story.map11-dungeon1.011":"Os pais que me criaram já estão com problemas demais...","story.map11-dungeon1.012":"Hehe... <wait=20>Desculpe por isso.","story.map11-dungeon1.013":"E<wait=20><rep_handlename> também veio.","story.map11-dungeon1.014":"Pode me contar o resto da história o quanto antes?","story.map11-dungeon1.015":"É verdade que o Ancião Grahdens foi capturado por Zevalhua?","story.map11-dungeon1.016":"Sim, é verdade.","story.map11-dungeon1.017":"Não posso te dar muitos detalhes,","story.map11-dungeon1.018":"mas recebi a informação de um membro confiável da Guarda Imperial, então ela é bem confiável.","story.map11-dungeon1.019":"Entendo...","story.map11-dungeon1.020":"Tsc.<wait=40> Por que aquele velho Invocador tinha que ir lá e se deixar capturar? ","story.map11-dungeon1.021":"Que irritante.","story.map11-dungeon1.022":"Lugy! <wait=40> Não fale essas coisas!","story.map11-dungeon1.023":"Você sabe que o Elder Grah se esforça muito por todos nós!","story.map11-dungeon1.024":"Lugy?!","story.map11-dungeon1.025":"Lugy... <wait=80> Hehe...","story.map11-dungeon1.026":"Que apelido nojento...","story.map11-dungeon1.027":"Você certamente tem uma qualidade que os humanos não conseguem entender, Deusa.","story.map11-dungeon1.028":"Senhorita Guarda Imperial, você está enganada.","story.map11-dungeon1.029":"Ela só é meio maluca, só isso.","story.map11-dungeon1.030":"Vocês dois são muito malvados!!!","story.map11-dungeon1.031":"Seria, <wait=40>já chega, tá bom?","story.map11-dungeon1.032":"Se continuarmos assim, não vamos chegar a lugar nenhum.","story.map11-dungeon1.033":"E você...<wait=20> Podemos te chamar só de Paris?","story.map11-dungeon1.034":"Hehe.<wait=20> Você me honra só de dizer meu nome, ó famoso Invocador Karl.","story.map11-dungeon1.035":"Não zombe de mim.","story.map11-dungeon1.036":"Enfim, temos certeza de que o ancião está em algum lugar aqui em Mirvana, certo?","story.map11-dungeon1.037":"Sim. <wait=40>Receio que sim.","story.map11-dungeon1.038":"Acho que, se o Elder Grah foi capturado por Zevalhua, ele provavelmente também está em algum lugar de Mirvana.","story.map11-dungeon1.039":"Isso porque, graças a todos os esforços de <rep_handlename>, ","story.map11-dungeon1.040":"o único lugar que ainda resta sob o controle de Zevalhua é este.","story.map11-dungeon1.041":"E, se for assim, <wait=40> seria mais rápido nos separarmos e procurarmos lugares suspeitos.","story.map11-dungeon1.042":"Acho que dividir as forças não tem jeito mesmo, né?","story.map11-dungeon1.043":"Então vocês só fiquem fora do meu caminho!","story.map11-dungeon1.044":"Tá, tá. Já entendemos.","story.map11-dungeon1.045":"Dê o seu melhor, Lugy!","story.map11-dungeon1.046":"Garota estúpida! <wait=40>Vou te reduzir a pó!","story.map11-dungeon1.047":"Parece que ter algo para fazer vai deixar as coisas divertidas de novo!","story.map11-dungeon1.048":"Que saco...","story.map11-dungeon1.049":"<rep_handlename>, <wait=40><br>contamos com você nesta.","story.map11-dungeon1.050":"Ajude o ancião com o mesmo poder que você usou para me ajudar!","story.map11-dungeon2.001":"Hmm...","story.map11-dungeon2.002":"Não parece haver nenhum lugar suspeito por aqui...","story.map11-dungeon2.003":"Hã...?","story.map11-dungeon2.004":"Ah, Karl!","story.map11-dungeon2.005":"Olá, Deusa.","story.map11-dungeon2.006":"Encontrou alguma pista por lá?","story.map11-dungeon2.007":"Infelizmente, não.","story.map11-dungeon2.008":"Mas, sério, <wait=20>onde o ancião pode estar...?","story.map11-dungeon2.009":"É por fazer essas loucuras na idade dele que ele acabou sendo capturado, para começo de conversa.","story.map11-dungeon2.011":"Que nada. Dá para ver que você só está preocupado com ele, Karl.","story.map11-dungeon2.012":"Haha. Acho que não sou páreo para uma deusa.","story.map11-dungeon2.013":"Você não precisa se preocupar com ele!","story.map11-dungeon2.014":"Tenho certeza de que o Elder Grah está muito bem!","story.map11-dungeon2.015":"Você também ficou bem quando foi capturado, não ficou?","story.map11-dungeon2.016":"Então é óbvio que alguém ainda mais incrível como o Elder Grah também vai ficar bem.","story.map11-dungeon2.017":"Tem coisas nessa frase com as quais não posso concordar...","story.map11-dungeon2.018":"Mas acho que, mesmo que eu me preocupe com ele, ele não vai bater as botas tão cedo.","story.map11-dungeon2.019":"Obrigado, Deusa!","story.map11-dungeon2.020":"Mas é um pouco estranho.","story.map11-dungeon2.021":"Você...","story.map11-dungeon2.022":"Paris-ursinha.","story.map11-dungeon2.023":"U-Ursinha?!","story.map11-dungeon2.024":"É muito difícil dizer isto a uma deusa, mas...","story.map11-dungeon2.025":"...você poderia, por favor, parar de me chamar de \\"ursinha\\"?","story.map11-dungeon2.026":"Pode me chamar só de \\"Paris\\". Não me importo com isso.","story.map11-dungeon2.027":"Tá bom, tudo bem.","story.map11-dungeon2.028":"Então, Paris, o que exatamente você está fazendo aqui?","story.map11-dungeon2.029":"Bom, <wait=20>eu também estou procurando o Ancião Grahdens.","story.map11-dungeon2.030":"Então não deveria ser surpresa nenhuma eu ter encontrado vocês.","story.map11-dungeon2.031":"Tudo bem, tanto faz.","story.map11-dungeon2.032":"Então, o que você acha tão estranho em tudo isso?","story.map11-dungeon2.033":"Nossa, <wait=20>alguém como Karl de Nyonne não sabe do que estou falando?","story.map11-dungeon2.034":"Não tenho tempo para seus joguinhos bobos. Fale logo.","story.map11-dungeon2.035":"Hehe, <wait=20>parece que você é mesmo diferente do Lugina.","story.map11-dungeon2.036":"Bom, então está certo.","story.map11-dungeon2.037":"Tenho certeza de que você também acha estranho, não acha?","story.map11-dungeon2.038":"Por que os deuses o capturariam e o deixariam vivo?","story.map11-dungeon2.039":"...","story.map11-dungeon2.040":"Se o Ancião Grahdens lutou ao seu lado contra Zevalhua e foi capturado no processo,","story.map11-dungeon2.041":"então por que eles não teriam motivo suficiente para matá-lo?","story.map11-dungeon2.042":"...","story.map11-dungeon2.043":"Será que tudo isso está nos levando a uma armadilha?","story.map11-dungeon2.044":"...","story.map11-dungeon2.045":"Não dá para pensar nisso depois?! Temos que resgatar o Elder Grah!","story.map11-dungeon2.046":"Você tem razão.","story.map11-dungeon2.047":"Karl, <wait=20><rep_handlename>, ","story.map11-dungeon2.048":"a Deusa tem razão. Eu também vou continuar procurando o ancião.","story.map11-dungeon2.049":"Vamos dar o nosso melhor juntos.","story.map11-dungeon2.050":"É, nisso você me pegou. Obrigado pela ajuda.","story.map11-dungeon2.051":"Hehe, <wait=20>afinal, o Grahdens talvez consiga responder a esse pequeno enigma para nós.","story.map11-dungeon2.052":"É, talvez consiga...","story.map11-dungeon2.053":"Hehe...","story.map11-dungeon3.001":"Ah, <wait=20><rep_handlename>.","story.map11-dungeon3.002":"Você está sozinho agora?","story.map11-dungeon3.003":"Hehe, <wait=20>tenho pena de todos os Invocadores protegidos por aquela Deusa.","story.map11-dungeon3.004":"Não consegui ouvir sua resposta da última vez por causa do Lugina, mas","story.map11-dungeon3.005":"não é como se eu já tivesse desistido de você.","story.map11-dungeon3.006":"Fico feliz por poder lutar ao seu lado de novo assim.","story.map11-dungeon3.007":"É por isso que--","story.map11-dungeon3.008":"<size=23>De jeito nenhum!!!</size>","story.map11-dungeon3.009":"<size=21>Paris! <wait=20><br>Pare com isso!</size>","story.map11-dungeon3.010":"<size=21><rep_handlename> é o meu Invocador!</size>","story.map11-dungeon3.011":"Ah, então <rep_handlename> é o seu Invocador?","story.map11-dungeon3.012":"Bem, <wait=20>e o que exatamente isso quer dizer?","story.map11-dungeon3.013":"<size=20>Quer dizer exatamente o que parece!</size>","story.map11-dungeon3.014":"<size=20><rep_handlename> é o meu Invocador! <wait=20> Fim de papo!</size>","story.map11-dungeon3.015":"E-<wait=20>Entendo...","story.map11-dungeon3.016":"<rep_handlename>...<wait=40><br>você está <wait=20>passando por muita coisa agora, não está?","story.map11-dungeon3.017":"Bem, <wait=20>de qualquer forma, teremos nossa conversinha mais tarde.","story.map11-dungeon3.018":"Por enquanto, vou procurar o Ancião Grahdens.","story.map11-dungeon3.019":"Devem chegar novas informações também, então fique atento a elas.","story.map11-dungeon3.020":"Ah! <wait=40>Paris, isso não é justo!","story.map11-dungeon3.021":"Eu não vou perder para você, viu!","story.map11-dungeon3.022":"<rep_handlename>!","story.map11-dungeon3.023":"Vou mostrar a ela que esta deusa linda e invencível é quem vai te encontrar, Elder Grah!","story.map11-dungeon3.024":"Então não se preocupe e só me espere!","story.map11-dungeon3.025":"<rep_handlename>, <wait=40><br>sinto muito por você....","story.map11-dungeon4.001":"Tsc, é você.","story.map11-dungeon4.002":"Se você ainda está zanzando por aqui, quer dizer que continua o mesmo idiota de sempre.","story.map11-dungeon4.003":"Hã? <wait=40>Você disse que nós dois ainda estamos no mesmo lugar?","story.map11-dungeon4.004":"Tsc, <wait=20>é por isso que eu odeio imbecis.","story.map11-dungeon4.005":"Eu tenho um motivo de verdade para estar aqui.","story.map11-dungeon4.006":"Mas, mais importante, <rep_handlename>.","story.map11-dungeon4.007":"Tome muito cuidado com aquela Guarda Imperial, a Paris.","story.map11-dungeon4.008":"Aquela mulher <wait=20>com certeza está tramando alguma coisa.","story.map11-dungeon4.009":"Dizendo que os nobres do Império Randall estão trabalhando com o Salão dos Invocadores de Akras e tal...","story.map11-dungeon4.010":"não tem como isso ser verdade.","story.map11-dungeon4.011":"E tenho certeza de que ela tem um motivo para esse interesse todo em você também...","story.map11-dungeon4.012":"<size=23>Ei, seus imbecis!</size>","story.map11-dungeon4.013":"<size=23>Por que vocês estão aí parados?!</size>","story.map11-dungeon4.014":"Tsc, mas agora chegou uma mulher ainda mais irritante.","story.map11-dungeon4.015":"<size=20>Quem você está chamando de mulher irritante?!</size>","story.map11-dungeon4.016":"<size=16>Não é hora de tagarelar! O Ancião Grahdens precisa da nossa ajuda!</size>","story.map11-dungeon4.017":"Vocês estão tão unha e carne que chega a me dar arrepios...","story.map11-dungeon4.018":"<size=21>Quem você está chamando de unha e carne?! <wait=40><br>Imbecil!</size>","story.map11-dungeon4.019":"<size=22>Quem você está chamando de imbecil?!</size>","story.map11-dungeon4.020":"<size=21>Não tente bancar o superior quando estava com a cabeça enfiada no chão!</size>","story.map11-dungeon4.021":"Grr, <wait=20>aquilo foi culpa daquela Deusa esquisita...","story.map11-dungeon4.022":"Lugy, você devia se esforçar um pouco mais!","story.map11-dungeon4.023":"<size=23>Vou dar uma surra nessa garota burra!</size>","story.map11-dungeon4.024":"<size=21>Ei, <rep_handlename>!</size>","story.map11-dungeon4.025":"<size=21>Aonde você está fugindo?!</size>","story.map11-dungeon4.026":"<size=18>Espere, <rep_handlename>! Aonde você vai?!</size>","story.map11-dungeon4.027":"<size=16>Não me deixe com esses dois esquisitos!</size>","story.map11-dungeon4.028":"<size=14>Não sei o que eles vão acabar fazendo comigo!</size>","story.map11-dungeon4.029":"<size=12>Como se eu quisesse fazer alguma coisa com você!</size>","story.map11-dungeon4.030":"<size=10>E o que isso quer dizer?!</size>","story.map11-dungeon4.031":"<size=9>Não entendeu?!</size><wait=20><br><size=9>Que idiota!</size>","story.map11-dungeon4.032":"<size=8>Cale a boca!</size><wait=20><br><size=8>Seu fracassado!</size>","story.map11-dungeon5.001":"<rep_handlename>!!<wait=40> Escuta, escuta!!","story.map11-dungeon5.002":"Eu sei <wait=20>onde o Elder Grah está!","story.map11-dungeon5.003":"Então, hum... <wait=20>Parece que ele está num lugar chamado \\"Torre dos Deuses\\".","story.map11-dungeon5.004":"Zevalhua transformou a Torre dos Deuses na base dele.","story.map11-dungeon5.005":"Então, resumindo, <wait=20>se formos até aquela torre,","story.map11-dungeon5.006":"podemos derrotar Zevalhua <wait=20>e, de quebra, resgatar o Elder Grah.","story.map11-dungeon5.007":"Então diga ao Karl e aos outros para seguirem rumo à Torre dos Deuses!","story.map11-dungeon5.008":"Não se podia esperar menos da serva do Lord Lucius, a Senhora Tilith.","story.map11-dungeon5.009":"Ah, <wait=20>Paris!","story.map11-dungeon5.010":"Hehehe, <wait=20>eu sou mesmo muito boa, não sou?","story.map11-dungeon5.011":"Ora, sim.<wait=20><br>Como era de se esperar de uma deusa.","story.map11-dungeon5.012":"Mas <wait=20>como você descobriu onde o Ancião Grahdens está?","story.map11-dungeon5.013":"Bom...","story.map11-dungeon5.014":"Tem outro servo do Lord Lucius, como eu, que estava de olho em Zevalhua.","story.map11-dungeon5.015":"Esse servo foi até a Torre dos Deuses e relatou ter visto um velho preso numa sala de lá.","story.map11-dungeon5.016":"Entendo. <wait=20><br>Agora compreendo...","story.map11-dungeon5.017":"O Lord Lucius <wait=20>vive reunindo vários servos divinos incríveis!","story.map11-dungeon5.018":"Claro, eu também entro nessa categoria.","story.map11-dungeon5.019":"Sim, sei muito bem que você tem poderes incríveis, Deusa.","story.map11-dungeon5.020":"Mas <wait=20>isso é curioso.","story.map11-dungeon5.021":"Hã? <wait=20>O quê?","story.map11-dungeon5.022":"Se ele tem tantos seres divinos excelentes ao seu lado,","story.map11-dungeon5.023":"por que ele mesmo não vai atrás dos Deuses Caídos?","story.map11-dungeon5.024":"Hum, <wait=20>bem...","story.map11-dungeon5.025":"E também, <wait=20>o mensageiro do deus principal,","story.map11-dungeon5.026":"o Imperador Sagrado Karna Masta, também desperta minha curiosidade.","story.map11-dungeon5.027":"Mesmo com Grand Gaia em apuros, ele não demonstrou nenhum sinal de querer fazer algo a respeito.","story.map11-dungeon5.028":"Se o Lord Lucius e Karna Masta trabalham juntos, então não precisam de nós, humanos.","story.map11-dungeon5.029":"Sinto que eles poderiam derrotar facilmente os dois Deuses Caídos restantes sozinhos.","story.map11-dungeon5.030":"Bem... <wait=40><br>É, <wait=20>hum...","story.map11-dungeon5.031":"Será que o Lord Lucius e os outros não conseguem agir livremente por conta própria?","story.map11-dungeon5.032":"Por exemplo, <wait=20>talvez, depois de ser derrotado pelos Quatro Deuses Caídos antes, ele tenha sido selado por algum poder, ou--","story.map11-dungeon5.033":"Não... <wait=20>Não é nada disso!","story.map11-dungeon5.034":"O Lord Lucius está muito bem!","story.map11-dungeon5.035":"Não posso te contar tudo, mas ele não consegue se mover direito agora...","story.map11-dungeon5.036":"E...<wait=20>E o Karna Masta tem o mesmo problema!","story.map11-dungeon5.037":"Mas não é como se eles estivessem selados em algum lugar!","story.map11-dungeon5.038":"Peço desculpas.","story.map11-dungeon5.039":"Por favor, encontre no seu coração uma forma de perdoar esta humana tola e desconfiada.","story.map11-dungeon5.040":"Uma idiota como eu não pode esperar compreender as grandes ideias dos deuses.","story.map11-dungeon5.041":"Sou só uma pessoa que vive com medo.","story.map11-dungeon5.042":"Não, <wait=20>tudo bem.","story.map11-dungeon5.043":"Eu nunca imaginei que você me perguntaria algo assim, então fui pega de surpresa.","story.map11-dungeon5.044":"Só suas palavras já me ajudaram muito.","story.map11-dungeon5.045":"Bem, <wait=20>devemos partir para resgatar o Ancião Grahdens.","story.map11-dungeon5.046":"Karl e os outros parecem ter ido logo à frente, rumo à cidade em ruínas de Mirvana.","story.map11-dungeon5.047":"C-<wait=20>Certo. <wait=40><br>Isso mesmo!","story.map11-dungeon5.048":"Temos que contar ao Karl e aos outros onde o Elder Grah está o mais rápido possível!","story.map11-dungeon5.049":"Muito bem, <rep_handlename>! <wait=40> Vamos nessa!","story.map11-dungeon6.001":"Ah, <wait=20>Karl!","story.map11-dungeon6.002":"E aí, <wait=20>deusa e <rep_handlename>.","story.map11-dungeon6.003":"Estávamos esperando vocês.","story.map11-dungeon6.004":"Parece que vocês descobriram onde o Ancião Grahdens está, né?","story.map11-dungeon6.005":"Muito obrigado.","story.map11-dungeon6.006":"Ei, <wait=20>como você sabia disso?","story.map11-dungeon6.007":"A Paris passou por aqui mais cedo <wait=20>e nos contou.","story.map11-dungeon6.008":"O quêêê?!<wait=40> Paris, sua boba!!","story.map11-dungeon6.009":"Eu queria ser a pessoa a fazer a surpresa!!","story.map11-dungeon6.010":"Mas, ei, <wait=20>onde a Paris está agora?","story.map11-dungeon6.011":"Bom, <wait=20>ela disse que havia algo que a deixou curiosa, então foi para a Torre dos Deuses na nossa frente.","story.map11-dungeon6.012":"Entendo...","story.map11-dungeon6.013":"O que será <wait=20> que a deixou tão curiosa...?","story.map11-dungeon6.014":"Deusa, <wait=40>o que houve?","story.map11-dungeon6.015":"Você não parece muito bem.<wait=20> Aconteceu alguma coisa?","story.map11-dungeon6.016":"N-<wait=20>Não, não é nada!","story.map11-dungeon6.017":"Eu estou sempre cheia de energia!","story.map11-dungeon6.018":"Não é, <wait=20><rep_handlename>?","story.map11-dungeon6.019":"Tudo bem.","story.map11-dungeon6.020":"Bom, <wait=20>depois de salvarmos o Ancião Grahdens, pretendo fazê-lo nos contar a história toda.","story.map11-dungeon6.021":"Aquele velho... <wait=20>tenho a sensação de que ele ainda está escondendo muita coisa de nós.","story.map11-dungeon6.022":"Livrar a Deusa das preocupações dela pode ser útil para nós a longo prazo.","story.map11-dungeon6.023":"O Karl é um cara tão legal.","story.map11-dungeon6.024":"Mas acho que é assim que são os amigos de <rep_handlename>!","story.map11-dungeon6.025":"Haha. <wait=20>Quando você fala isso bem na minha frente, eu fico até um pouco sem graça.","story.map11-dungeon6.026":"Ah, <wait=20>mudando de assunto, mas...","story.map11-dungeon6.027":"E como está aquilo?","story.map11-dungeon6.028":"Aquilo...?","story.map11-dungeon6.029":"Bom, <wait=20>do mesmo jeito de sempre. <wait=40><br>Então, não se preocupe com isso...","story.map11-dungeon6.030":"Entendi! <wait=20><br>Então, do mesmo jeito de sempre, né?","story.map11-dungeon6.031":"Bom, então <wait=20>não vou me preocupar.","story.map11-dungeon6.032":"Eu já te disse! <wait=20>Eu vou ser a primeira a chegar na Torre dos Deuses!","story.map11-dungeon6.033":"Você não tem como saber!","story.map11-dungeon6.034":"Você devia ficar na entrada vigiando!","story.map11-dungeon6.035":"<size=18>Por que eu tenho que ser a que fica de guarda?!</size>","story.map11-dungeon6.036":"Porque é o trabalho perfeito para uma garota tonta como você.","story.map11-dungeon6.037":"<size=18>Eu não sou tonta!</size>","story.map11-dungeon6.038":"Vigiar também é um trabalho importante, de qualquer forma!","story.map11-dungeon6.039":"Se você não entende isso, vai fracassar em um monte de missões no futuro!","story.map11-dungeon6.040":"<size=18>O que foi que você me disse?!</size>","story.map11-dungeon6.041":"Se vigiar é um trabalho tão importante, então por que você não faz?!","story.map11-dungeon6.042":"Você está falando de duas coisas diferentes!","story.map11-dungeon6.043":"Ai, ai. <wait=20>esses dois me deixam muito nervoso...","story.map11-dungeon7.001":"Finalmente, <wait=40><br><rep_handlename>!","story.map11-dungeon7.002":"O Elder Grah está aqui,","story.map11-dungeon7.003":"e também um dos Quatro Deuses Caídos, \\"O Imperador Divino Zevalhua\\".","story.map11-dungeon7.004":"Consigo sentir um poder imenso lá fora...","story.map11-dungeon7.005":"Acho que não é tão surpreendente, vindo de um dos Deuses Caídos.","story.map11-dungeon7.006":"Tsc, <wait=20>não me importa o tamanho dele, se me irritar eu vou fazer ele em pedaços.","story.map11-dungeon7.007":"Mas, ei, <wait=20>cadê aquela moça da Guarda Imperial?","story.map11-dungeon7.008":"Parece que ela não está por aqui.","story.map11-dungeon7.009":"Hah, <wait=20>parece que não dá para contar com os soldados do Exército Imperial de Randall, no fim das contas.","story.map11-dungeon7.010":"Mas <wait=20>ela também tem a própria missão para cuidar.","story.map11-dungeon7.011":"Parece que ela anda ocupada com várias coisas por aí.","story.map11-dungeon7.012":"Ela está até interessada no motivo de o Ancião ter sido capturado...","story.map11-dungeon7.013":"Karl!","story.map11-dungeon7.014":"Não temos tempo para pensar nisso agora!","story.map11-dungeon7.015":"Temos que nos apressar e resgatar o Elder Grah antes que seja tarde demais!","story.map11-dungeon7.016":"Você tem razão. <wait=40><br>É exatamente como a Deusa diz.","story.map11-dungeon7.017":"Não adianta pensar nisso agora!","story.map11-dungeon7.018":"Bom, então <wait=20>vamos nos separar e tentar encontrar o Ancião!","story.map11-dungeon7.019":"Na verdade, eu gostaria que todos nos reuníssemos antes de enfrentar o Zevalhua, mas","story.map11-dungeon7.020":"dependendo da situação, talvez não seja possível. Se for preciso, talvez tenhamos que enfrentá-lo sozinhos.","story.map11-dungeon7.021":"Sem problemas.","story.map11-dungeon7.022":"Mesmo que não seja ele de verdade, ou que seja uma armadilha, eu vou lutar mesmo assim!","story.map11-dungeon7.023":"Hah! <wait=20>Eu nunca esperei muito do poder de vocês.","story.map11-dungeon7.024":"<rep_handlename>, <wait=20>contamos com o seu poder de novo.","story.map11-dungeon7.025":"Muito bem, <wait=20>não vão morrer por aí!","story.map11-dungeon7.026":"Isto é...","story.map11-dungeon7.027":"Parece que não tenho escolha a não ser mudar meus planos originais...","story.map11-ending.001":"Conseguimos, <wait=40><br><rep_handlename>!","story.map11-ending.002":"E pensar que você derrotou até o Zevalhua! Você é incrível, <rep_handlename>!","story.map11-ending.003":"E o Karl e o Ancião estão...","story.map11-ending.005":"*Arf* *arf* *arf* <wait=40><br><rep_handlename>...","story.map11-ending.006":"*Pff*<wait=40><br>*Arf*","story.map11-ending.007":"Uau, você conseguiu!","story.map11-ending.008":"Senti um poder imenso ficar ainda mais forte, então vim correndo para cá,","story.map11-ending.009":"mas acho que nem precisava ter corrido, afinal...","story.map11-ending.010":"Droga, <wait=20>parece que não cheguei a tempo.","story.map11-ending.011":"<rep_handlename>!","story.map11-ending.012":"Seu desgraçado, <wait=20>você ficou com toda a diversão só para você, né?!","story.map11-ending.013":"É por isso que eu não gosto de você!","story.map11-ending.014":"Ah, <wait=20>parece que todo mundo saiu ileso!","story.map11-ending.015":"<rep_handlename>!","story.map11-ending.016":"Eu sabia que você ia derrotar o Zevalhua! Afinal, você é meu amigo.","story.map11-ending.017":"Fico feliz em ver que estão todos sãos e salvos.","story.map11-ending.018":"E então, <wait=20>vocês conseguiram encontrar o Elder Grah?","story.map11-ending.019":"Ele não está aqui?","story.map11-ending.020":"Ele não estava em nenhuma das outras salas,","story.map11-ending.021":"então eu tinha certeza de que ele estaria aqui, já que era a única sala que faltava. Por isso vim correndo.","story.map11-ending.022":"Argh, <wait=20>agora vamos ter que lidar com ainda mais porcaria chata.","story.map11-ending.023":"Espero que o Ancião Grahdens <wait=20>esteja seguro em algum lugar...","story.map11-ending.024":"Ah, <wait=20>desculpa, Karl. <wait=20> Eu não quis falar desse jeito...","story.map11-ending.025":"Não, tudo bem.","story.map11-ending.026":"Não há nenhum vestígio indicando <wait=20>que ele veio para cá, então","story.map11-ending.027":"ele provavelmente escapou sozinho.","story.map11-ending.028":"Ho ho ho. <wait=40><br>Exatamente.","story.map11-ending.029":"Essa voz!","story.map11-ending.030":"Elder Grah!","story.map11-ending.031":"Ho ho ho.","story.map11-ending.032":"Parece que eu dei bastante trabalho a todos vocês.","story.map11-ending.033":"Ancião Grahdens...","story.map11-ending.034":"Não faça essa cara de criança.","story.map11-ending.035":"Posso ter preocupado vocês, <wait=20><br>mas ainda não virei um fracote.","story.map11-ending.036":"Q-Quem estava preocupado com você?!","story.map11-ending.037":"E mais importante, <wait=20>o que você estava fazendo esse tempo todo, e onde?!","story.map11-ending.038":"Explique para todo mundo por que tivemos que correr atrás de você!","story.map11-ending.039":"Hum, <wait=20>bem, eu fiz algo errado.","story.map11-ending.040":"Havia algo nesta torre que estava me incomodando, <wait=20>só um pouco.","story.map11-ending.041":"Fingi ser capturado por aquela Deusa Caída, Mare-sei-lá-o-quê, e fiz com que ela me trouxesse para cá.","story.map11-ending.042":"Talvez <wait=20>ela esperasse que me capturar lhe desse vantagem sobre vocês em batalha.","story.map11-ending.043":"Mas antes que Mare pudesse usar isso, ela foi derrotada por vocês.","story.map11-ending.044":"Como ela havia adquirido conhecimento sobre Zevalhua e Afla Dilith depois de lutar com eles,","story.map11-ending.045":"eu não queria enfrentá-la pessoalmente.","story.map11-ending.046":"Mas, como esperado, <wait=20>deixar que ela me capturasse trouxe a ajuda de vocês.","story.map11-ending.047":"E graças a isso tive tempo suficiente para conduzir minha pesquisa com calma.","story.map11-ending.048":"Nesse caso, <wait=20>era só ter contado isso para a gente.","story.map11-ending.049":"Velho irritante.","story.map11-ending.050":"Ho ho ho. <wait=40>Desculpe por isso, Lugina.","story.map11-ending.051":"Estou em dívida com vocês pelo que fizeram.","story.map11-ending.052":"Vou recompensá-los muito bem por isso.","story.map11-ending.053":"Pode apostar que vai.","story.map11-ending.054":"E não só isso, <wait=20>mas você também tem que contar para outras pessoas importantes <wait=20>tudo o que eu fiz.","story.map11-ending.055":"Sério, <wait=20>esse cara não tem classe nenhuma.","story.map11-ending.056":"Olha quem fala!","story.map11-ending.057":"Então, <wait=20>Ancião.<wait=40> Você sabe o que eu quero te perguntar, não sabe?","story.map11-ending.058":"Hum. <wait=40>Sobre o seu nascimento, estou certo?","story.map11-ending.059":"Está escrito no meu testamento. Não pode esperar até lá para ler?","story.map11-ending.060":"Não dá.","story.map11-ending.061":"Ho ho ho. <wait=40>Eu estava brincando. <wait=20>Não precisa ficar tão bravo.","story.map11-ending.062":"Mas <wait=20>não é um segredo tão grande assim.","story.map11-ending.063":"Karl.","story.map11-ending.064":"Eu te encontrei ainda bebê e te criei. Isso você sabe, certo?","story.map11-ending.065":"Sim, <wait=20>e sou grato a você por isso.","story.map11-ending.066":"Mas <wait=20>tem algo especial no lugar onde você me encontrou?","story.map11-ending.067":"Hum. <wait=20><br>Bem, tem sim.","story.map11-ending.068":"Acho que você mesmo pode ter sentido isso vagamente, <wait=20><br>mas eu te encontrei em Grand Gaia.","story.map11-ending.069":"Espera, <wait=20>o quê?!","story.map11-ending.070":"Tsc, <wait=20>então é assim.","story.map11-ending.071":"...","story.map11-ending.072":"Mas <wait=20>eu achava que não havia sobreviventes humanos em Grand Gaia...?","story.map11-ending.073":"Nem eu entendo.","story.map11-ending.074":"Eu só vim para cá com outros Invocadores, e, enquanto examinávamos a área,","story.map11-ending.075":"encontramos um bebê nas ruínas de Mistral.","story.map11-ending.076":"E então, <wait=40>nós o levamos conosco de volta para Elgaia.","story.map11-ending.077":"Isso é tudo.","story.map11-ending.078":"Eu não fazia ideia de que tipo de ser aquele bebê realmente era.","story.map11-ending.079":"Karl.","story.map11-ending.080":"Não sei se você é um órfão sobrevivente de Grand Gaia, ","story.map11-ending.081":"ou se é um filho dos deuses.","story.map11-ending.082":"Porém--","story.map11-ending.083":"Ancião. <wait=40><br>Você não precisa me dizer mais nada.","story.map11-ending.084":"Porque eu sou muito grato a você e a todos os outros Invocadores.","story.map11-ending.085":"...","story.map11-ending.086":"Karl...","story.map11-ending.087":"Uau, então o Karl tinha um segredo desses guardado, né?","story.map11-ending.088":"Hmm... <wait=40>Um bebê deixado em Grand Gaia.","story.map11-ending.089":"Nunca ouvi falar de nada assim.","story.map11-ending.090":"Será que o Lord Lucius sabe de alguma coisa?","story.map11-ending.091":"Acho <wait=20>que vou lá perguntar para ele!","story.map11-ending.092":"<rep_handlename>!","story.map11-ending.093":"Bom, só falta mais um Deus Caído para cuidarmos, e é o Deus Fera Afla Dilith!","story.map11-ending.094":"Tenho certeza de que conseguimos derrotá-lo se trabalharmos juntos!","story.map11-ending.095":"E, claro, <wait=20>também vamos contar com seus poderes de Invocador, <rep_handlename>.","story.map11-ending.096":"Bom, então <wait=20>vou perguntar sobre o Karl e falo com vocês da próxima vez!","story.map11-ending.097":"Ah, <wait=20>espera! <wait=20><br>Deusa!","story.map11-ending.098":"Eu queria dizer a ela que não me importo tanto assim...","story.map11-ending.099":"Ela não escuta, né?","story.map11-ending.100":"Ho ho ho. <wait=40><br>É porque a Tilith é uma garota gentil.","story.map11-ending.101":"E então, <wait=20>o que vamos fazer com essa presença ruim que apareceu depois que a Deusa foi embora?","story.map11-ending.102":"Eu sou bem duro com presenças ruins.","story.map11-ending.103":"Você é...","story.map11-ending.104":"Eu sou Eriole.","story.map11-ending.105":"Venho do Império de Randall,","story.map11-ending.106":"onde sirvo como comandante da Guarda Imperial, que protege a família imperial.","story.map11-ending.107":"Heh, <wait=20>já ouvi boatos sobre esse nome.","story.map11-ending.108":"Boatos dizendo que ele é um cara desagradável que se tornou a pessoa mais jovem a ter o título de comandante.","story.map11-ending.109":"Que grosseria!","story.map11-ending.110":"Ah, <wait=20>a moça que estava com medo demais de enfrentar os Quatro Deuses Caídos voltou!","story.map11-ending.111":"Este homem é um--","story.map11-ending.112":"Paris, recue um pouco.","story.map11-ending.113":"O quê? <wait=20>M-<wait=20>Mas--","story.map11-ending.114":"Paris.","story.map11-ending.115":"E-<wait=20>Entendido...","story.map11-ending.116":"Então, <wait=20>o que exatamente o comandante da Guarda Imperial quer conosco?","story.map11-ending.117":"Eu também agradeceria se você pudesse nos explicar quem é aquela pessoa assustadora atrás de você.","story.map11-ending.118":"...","story.map11-ending.119":"Esta pessoa é meu associado. <wait=40><br>Não se preocupem com ele.","story.map11-ending.120":"Vocês devem ter ouvido muitas coisas da minha subordinada, Paris.","story.map11-ending.121":"Eu queria conversar com todos vocês pelo menos uma vez,","story.map11-ending.122":"mas, como enviado do Imperador de Randall,","story.map11-ending.123":"desta vez vim falar especificamente com o Invocador Grahdens.","story.map11-ending.124":"Ho ho ho.","story.map11-ending.125":"Se você só queria falar comigo, <wait=20>não precisava ter vindo até aqui, sabe.","story.map11-ending.126":"Ha ha ha.","story.map11-ending.127":"Temos nossos motivos para fazer isso.","story.map11-ending.128":"Explicaremos em detalhes mais tarde.","story.map11-ending.129":"Você pretende levar o Ancião com você?","story.map11-ending.130":"Acha mesmo que ele vai sem fazer barulho?","story.map11-ending.131":"Por favor, não me entenda mal.","story.map11-ending.132":"Não viemos aqui para lutar.","story.map11-ending.133":"Eu sei disso.","story.map11-ending.134":"Afinal, se algo acontecer comigo, seria muito inconveniente para vocês.","story.map11-ending.135":"...","story.map11-ending.136":"Pessoal, <wait=20>com licença. <wait=40><br>Vou ter uma conversinha com estes senhores por um momento.","story.map11-ending.137":"Eu queria agradecer a todos vocês direito, mas parece que vai ter que ficar para a próxima.","story.map11-ending.138":"Karl.","story.map11-ending.139":"Fiquei feliz em ver desta vez<wait=20> o quanto você cresceu.","story.map11-ending.140":"Ancião Grahdens...","story.map11-ending.141":"E você, <rep_handlename>.","story.map11-ending.142":"Você se saiu bem ao derrotar o Zevalhua.","story.map11-ending.143":"Porém, <wait=20>da próxima vez você vai enfrentar Afla Dilith.","story.map11-ending.144":"E, ao contrário dos outros Deuses Caídos, tenho certeza de que ele estará preparado para lutar contra você.","story.map11-ending.145":"Não tenho dúvida de que será uma batalha difícil, mas você precisa desafiar a si mesmo e aos seus amigos.","story.map11-ending.146":"Além disso, <wait=20>deixo o Karl em suas mãos.","story.map11-ending.147":"Acho que você talvez já saiba disso, mas","story.map11-ending.148":"ainda faltam algumas peças nele aqui e ali, então ele me preocupa.","story.map11-ending.149":"Eu não preciso que ninguém cuide de mim...","story.map11-ending.150":"Ho ho ho.","story.map11-ending.151":"Pois bem, enviado do Império de Randall, <wait=40><br>vamos indo?","story.map11-ending.152":"Eu lhe agradeço<wait=20> pela consideração e pela compreensão.","story.map11-ending.153":"Paris, <wait=40>vamos.","story.map11-ending.154":"Sim, senhor!","story.map11-ending.155":"Ele foi embora assim, sem mais nem menos, né?","story.map11-ending.156":"Como é o Ancião Grahdens, tenho certeza de que ele vai ficar bem. Mas, mesmo assim...","story.map11-ending.157":"Hum. <wait=20>aqueles caras do Império de Randall não conseguem encostar um dedo no velho Invocador.","story.map11-ending.158":"Você tem razão.","story.map11-ending.159":"Afinal, estamos falando do Ancião Grahdens. <wait=40><br>Ele vai ficar bem.","story.map11-ending.160":"Mais importante, <wait=20>devíamos focar no que podemos fazer para ajudar do nosso lado.","story.map11-ending.161":"<rep_handlename>,","story.map11-ending.162":"você vai enfrentar Afla Dilith, <wait=20> o último dos Quatro Deuses Caídos, <wait=20>não vai?","story.map11-ending.163":"A verdade é que a Seria e eu queremos te dar uma mão nisso, mas também não podemos simplesmente ignorar o demônio Graham.","story.map11-ending.164":"É verdade! <wait=40><br>Eu me esqueci completamente dele!","story.map11-ending.165":"Se não o derrotarmos...","story.map11-ending.166":"<rep_handlename>!","story.map11-ending.167":"Vamos ter que nos separar, <wait=20><br>mas você vai ficar bem, né?","story.map11-ending.168":"Vamos derrotar o Graham e voltar logo, então se cuida!","story.map11-ending.169":"Ora, ora... <wait=20>Parece que a grande demônia Seria também tem um lado legal, no fim das contas.","story.map11-ending.170":"Idio-- <wait=20>Imbe-- <wait=20>É isso que se deve dizer numa hora dessas!","story.map11-ending.171":"Ei, <rep_handlename>!","story.map11-ending.172":"Não vá tentar ficar com todo o crédito <wait=20>por derrotar o Zevalhua sozinho.","story.map11-ending.173":"Também não se esqueça de tudo <wait=40><br>o que eu fiz.","story.map11-ending.174":"Se eu vou te salvar ou não da próxima vez pode depender do quanto você for grato a mim.","story.map11-ending.175":"Haha, <wait=20>esse é o Lugina.","story.map11-ending.176":"<rep_handlename>, <wait=40><br>temos que ir agora.","story.map11-ending.177":"Se você vir a Deusa de novo, por favor, diga a ela que sou muito grato pela ajuda dela.","story.map11-ending.178":"E <wait=20>se você ouvir algo sobre mim e quiser conversar comigo sobre isso, fica a seu critério.","story.map11-ending.179":"Porque, se for você a me contar, <wait=20>tenho certeza de que vou conseguir lidar com qualquer verdade que vier.","story.map11-ending.180":"Bom, então <wait=20>estou ansioso para te ver da próxima vez.","story.map11-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Eu sou Lucius...<wait=40><br>o deus que rege este Portal...","story.map11-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Libertador de Agni...<wait=40><br><rep_handlename>...","story.map11-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use o meu poder...<wait=40><br>e parta em uma jornada rumo a uma nova terra...","story.map11-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>para levar a nossa palavra<wait=40><br>a este mundo mergulhado no caos...","story.map11-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Acredite em si mesmo<wait=20><br>e continue avançando...","story.map11-open.006":"<rep_handlename>! <wait=40><br>Chegou a hora!","story.map11-open.007":"Esta é Mirvana, a região que o Zevalhua transformou em base durante a batalha contra os deuses.","story.map11-open.008":"Parece que, por causa disso, <wait=20>a região de Agni se tornou o maior campo de batalha da guerra.","story.map11-open.009":"A paisagem por aqui é tão sombria...","story.map11-open.010":"Ah! <wait=20>Desculpa, desculpa!","story.map11-open.011":"Não é hora de ficar sentimental!","story.map11-open.013":"Bom, <wait=20>vamos derrotar o Zevalhua e resgatar o Elder Grah!","story.map11-open.014":"Sei que podemos contar com você, <rep_handlename>. Eu acredito em você!","story.map2-dungeon1.001":"<size=22>Ué?! <rep_handlename>!!","story.map2-dungeon1.002":"Não acredito, <wait=20>nunca imaginei que a gente fosse se encontrar num lugar desses!","story.map2-dungeon1.003":"Entendi, <wait=40>também está indo para a Torre de Morgan, né?","story.map2-dungeon1.004":"Você também deve estar com o Exército de Invocadores, atrás dos Quatro Deuses Caídos...","story.map2-dungeon1.005":"Não? <wait=40>Foi a Tilith que mandou você vir?","story.map2-dungeon1.006":"Ah, <wait=20>deve ser aquela garota de quem você falou antes.","story.map2-dungeon1.007":"Parece que ela cuida bem de você.  <wait=20>Preciso ser educado e cumprimentá-la quando a gente se encontrar. <wait=19>Me apresenta pra ela, tá?","story.map2-dungeon1.008":"Hã? <wait=20>Ela não está aqui? <wait=40>Você também está procurando por ela?","story.map2-dungeon1.009":"Hmm... <wait=40>Bom, <wait=40>acho que não preciso perguntar mais nada.","story.map2-dungeon1.010":"Nós, os Caçadores de Demônios, estamos perseguindo o demônio Graham.","story.map2-dungeon1.011":"Já encurralamos ele algumas vezes, <wait=20>mas ele sempre dá um jeito de escapar...","story.map2-dungeon1.012":"Ele fugiu para o deserto, então estamos prestes a entrar lá atrás dele.","story.map2-dungeon1.013":"Bom, <wait=20>vamos indo, então?","story.map2-dungeon1.014":"Aliás, <wait=40>este deserto é quente demais, então tome muito cuidado.","story.map2-dungeon1.015":"E fique de olho, porque andaram vendo por aí um bobalhão sacudindo uma espada flamejante!","story.map2-dungeon1.016":"Se cuida, <wait=20>a gente se vê logo, logo!","story.map2-dungeon2.001":"Ah, <rep_handlename>!!","story.map2-dungeon2.002":"Está sentindo? <wait=40>Essa brisa do mar não é simplesmente incrível?","story.map2-dungeon2.003":"Hã? <wait=40>Por que a gente está aqui?","story.map2-dungeon2.004":"Porque estava quente demais lá atrás...","story.map2-dungeon2.005":"<size=22>Ah! <wait=40>Retiro o que eu disse!!","story.map2-dungeon2.006":"A gente não está aqui só por causa do calor...","story.map2-dungeon2.007":"Eu tenho mesmo uns assuntos pra resolver aqui! <wait=40>E pare já com essa cara de desconfiado!","story.map2-dungeon2.008":"Bom, preciso ir! <wait=40>Alcanço você assim que terminar o que tenho pra fazer.","story.map2-dungeon2.009":"Vai na frente, <rep_handlename>!<br><wait=40>E nada de enrolar, hein?","story.map2-dungeon2.010":"Aliás, <wait=40>parece que tem uma espadachim inimiga nesta praia, e ouvi dizer que ela controla o ar gelado!","story.map2-dungeon2.011":"Também ouvi dizer que ela é linda, mas eu sei que sou muito mais fofa que ela!","story.map2-dungeon2.012":"Trate de derrotá-la, <wait=20>e rapidinho, viu!","story.map2-dungeon2.013":"Enfim, <wait=20>vou ficar esperando aqui! <wait=40>Boa sorte!","story.map2-dungeon3.001":"É você, <rep_handlename>?!<br><wait=40>Você viu o Graham?!","story.map2-dungeon3.002":"Ah, <wait=20>não viu... <wait=40>Droga... <wait=40>Argh...","story.map2-dungeon3.003":"Ah, <wait=20>não se preocupe. <wait=40>É só um arranhão, nada de mais...","story.map2-dungeon3.004":"Mas o pior é que, <wait=20>quase todos os meus companheiros foram eliminados...","story.map2-dungeon3.005":"O Graham... <wait=30>Ele está na Floresta Noturna agora.","story.map2-dungeon3.006":"Pelo jeito, esta floresta é território de um dos cavaleiros do Graham.","story.map2-dungeon3.007":"Esse cavaleiro conhece as sombras da floresta como a palma da mão e usa a pouca visibilidade a seu favor.","story.map2-dungeon3.008":"Ele está derrubando os Invocadores um por um.","story.map2-dungeon3.009":"Se conseguirmos derrotar esse cavaleiro, talvez dê pra expulsar o Graham da floresta.","story.map2-dungeon3.010":"Tudo o que sei é que esse cavaleiro luta com uma lança.","story.map2-dungeon3.011":"Do jeito que as coisas estão, nós, Caçadores de Demônios, não podemos fazer muito além de cercar o Graham...","story.map2-dungeon3.012":"E eu não vou ficar parado vendo meus companheiros caírem um por um.","story.map2-dungeon3.013":"Seja como for, vou arrancar ele desta floresta nem que seja sozinho!","story.map2-dungeon3.014":"Bom, então vamos nessa.<br><wait=40>Espero que você também dê tudo de si!","story.map2-dungeon4.001":"Ei, <wait=20><rep_handlename>!<br><wait=40>Que bom ver você inteiro!","story.map2-dungeon4.002":"Bom, <wait=20>não que eu achasse que você fosse perder pra alguém daquele tipo!","story.map2-dungeon4.003":"Você está indo para a Torre de Morgan, né?","story.map2-dungeon4.004":"Se for isso, vai ter que atravessar os Ermos de Asekutt.","story.map2-dungeon4.005":"As feras que rondam os Ermos de Asekutt são bem fortes.","story.map2-dungeon4.006":"Seria perigoso se suas unidades tivessem desvantagem de elemento contra essas feras, então tome cuidado.","story.map2-dungeon4.007":"Hmm? <wait=40>Está preocupado com a situação do nosso lado?","story.map2-dungeon4.008":"Bom, de algum jeito consegui arrancar o Graham da floresta.","story.map2-dungeon4.009":"Só que, ao contrário da Floresta Noturna, Asekutt é campo aberto.","story.map2-dungeon4.010":"Ele não vai conseguir fugir e se esconder como fez na Floresta Noturna.","story.map2-dungeon4.011":"Mesmo que a força da nossa equipe de Caçadores de Demônios tenha caído pela metade...","story.map2-dungeon4.012":"Pretendo resolver isso de uma vez por todas em Asekutt.","story.map2-dungeon4.013":"Isso é pelos meus companheiros, <wait=40>pelo sacrifício deles.","story.map2-dungeon4.014":"Então, infelizmente, <wait=40>não posso ir com você.","story.map2-dungeon4.015":"Mas pode ficar tranquilo, tenho plena confiança de que você vai derrotar Maxwell.","story.map2-dungeon4.016":"Até mais!","story.map2-dungeon5.001":"E aí, <rep_handlename>.<br><wait=40>O Graham escapou de novo...","story.map2-dungeon5.002":"Droga, <wait=40>estávamos tão perto!","story.map2-dungeon5.003":"E perdi ainda mais companheiros... <wait=40>Juro que vou esmagá-lo quando puser as mãos nele.","story.map2-dungeon5.004":"...<wait=20>Mas agora nós, Caçadores de Demônios, somos poucos demais.","story.map2-dungeon5.005":"Então estamos voltando ao Salão dos Invocadores atrás de reforços.","story.map2-dungeon5.006":"Eu também ia encontrar ela aqui, mas...","story.map2-dungeon5.007":"Ah, <wait=20>lá está ela!","story.map2-dungeon5.008":"Opa, Seria, <wait=40>toda animada, hein?","story.map2-dungeon5.009":"Karl! <wait=40>Isto não é hora pra conversa fiada!","story.map2-dungeon5.010":"O que <rep_handlename> está fazendo aqui?!","story.map2-dungeon5.011":"Você não faz parte dos Caçadores de Demônios, faz?!","story.map2-dungeon5.012":"Ah, <wait=40><rep_handlename> e eu só nos encontramos aqui por acaso.","story.map2-dungeon5.013":"Sua próxima parada <wait=20>é o Santuário de Lystia, imagino?","story.map2-dungeon5.014":"Se você não é membro dos Caçadores de Demônios, não tem motivo pra estar aqui.","story.map2-dungeon5.015":"Ei, <wait=20>Seria. <wait=40>Não precisa falar desse jeito!","story.map2-dungeon5.016":"<size=12>...<wait=40>Por que eu é que levo a bronca??","story.map2-dungeon5.017":"Mais importante, tenho notícias pra você, Karl.","story.map2-dungeon5.018":"Segundo informações do Salão dos Invocadores, <wait=20>parece que o Graham era um dos favoritos de Abaddon.","story.map2-dungeon5.019":"Ele tem o favor de Abaddon? <wait=40>Que história é essa?","story.map2-dungeon5.020":"Parece que ele é muito estimado, até entre os outros deuses...","story.map2-dungeon5.021":"Então, se o Graham estiver em perigo, pode ter certeza de que mais problemas virão logo em seguida.","story.map2-dungeon5.022":"Talvez até o próprio Abaddon apareça...","story.map2-dungeon5.023":"Se isso for verdade, precisamos abater o Graham pra atrair Abaddon.","story.map2-dungeon5.024":"É por isso que recebemos ordens do Salão dos Invocadores para avançar até a Torre de Morgan. ","story.map2-dungeon5.025":"Entendi.","story.map2-dungeon5.026":"Deve ser por isso que nosso pedido de reforços foi aceito tão rápido.","story.map2-dungeon5.027":"Enfim, não acha que já está na hora de parar com o papo furado!?","story.map2-dungeon5.028":"Você devia estar a caminho da Torre de Morgan, não é?","story.map2-dungeon5.029":"Ainda temos muito planejamento pela frente...","story.map2-dungeon5.030":"...então por que você não vai logo sozinho!","story.map2-dungeon5.031":"Hã? <wait=20>E-<wait=20>Ei, Seria! <wait=40><rep_handlename>!!","story.map2-dungeon6.001":"<rep_handlename>! <wait=40>Você está bem?!","story.map2-dungeon6.002":"Você saiu correndo depois que a Seria gritou com você. <wait=20>Achei que tivesse ficado bravo.","story.map2-dungeon6.003":"Bom, <wait=20>que bom ver que você está bem.","story.map2-dungeon6.004":"Nós também acabamos de passar pelo Santuário de Lystia.","story.map2-dungeon6.005":"Ei, <wait=40>por que você sempre aparece em todo lugar que a gente vai?!","story.map2-dungeon6.006":"Não está nos perseguindo, está?!","story.map2-dungeon6.007":"Dá pra parar com essa agressividade sem sentido?!","story.map2-dungeon6.008":"Por que você sempre tem que arrumar briga?","story.map2-dungeon6.009":"E-<wait=20>Eu não estou arrumando briga!","story.map2-dungeon6.010":"Ele nem é tão forte assim...","story.map2-dungeon6.011":"Me irrita muito ver você elogiando alguém como ele. Sério, olha só pra ele!","story.map2-dungeon6.012":"*Suspiro* <wait=40>Se isso não é arrumar briga, <wait=20>não sei o que é...","story.map2-dungeon6.013":"Não sei se você não percebeu, <wait=20>mas <rep_handlename> chegou até aqui sozinho.","story.map2-dungeon6.014":"<rep_handlename> nos ajudou derrotando o subordinado do Graham na Floresta Noturna.","story.map2-dungeon6.015":"<rep_handlename> não é nenhum fracote, isso é certo.","story.map2-dungeon6.016":"Hunf. <wait=40>Bom, pra mim tanto faz.","story.map2-dungeon6.017":"Pode se deliciar com esses elogios sem fundamento, não estou nem aí!","story.map2-dungeon6.018":"...<wait=40>Eu realmente não entendo as mulheres.","story.map2-dungeon6.019":"Bom, <wait=20>enfim...","story.map2-dungeon6.020":"Vamos atravessar esta catedral destruída pra chegar à Torre de Morgan...","story.map2-dungeon6.021":"<rep_handlename>, quer vir junto?","story.map2-dungeon6.022":"<size=24>Eu me oponho!","story.map2-dungeon6.023":"Heh, <wait=20>sabia que você ia dizer isso.","story.map2-dungeon6.024":"Bom, <wait=20>não dá pra entrar numa batalha juntos brigando entre nós desse jeito. Melhor não forçar.","story.map2-dungeon6.025":"Nós vamos pelo nosso caminho, você vai pelo seu.","story.map2-dungeon6.026":"Nos vemos na Torre de Morgan!","story.map2-dungeon7.001":"<rep_handlename>!! <wait=40>Você é rápido, <wait=20>não achei que já estaria aqui.","story.map2-dungeon7.002":"Heh, <wait=40>é o mínimo que ele podia fazer...","story.map2-dungeon7.003":"Como sempre, já partindo pra briga...","story.map2-dungeon7.004":"Então, <wait=20>enfim... <wait=40>Esta é a base de Abaddon, <wait=20>a Torre de Morgan.","story.map2-dungeon7.005":"Abaddon e Graham provavelmente estão aqui.","story.map2-dungeon7.006":"Este é praticamente o único lugar pra onde o Graham poderia fugir.","story.map2-dungeon7.007":"Nós pegamos o Graham. <wait=40><br>E você, <rep_handlename>, enfrenta Abaddon.","story.map2-dungeon7.008":"Chegamos até aqui, <wait=40>agora vamos esmagá-los!","story.map2-dungeon7.009":"Mas talvez a gente derrote Abaddon antes mesmo de você ter uma chance!","story.map2-dungeon7.010":"E o que você diria se <rep_handlename> derrotasse o Graham antes de nós?","story.map2-dungeon7.011":"Bom, <wait=40>é natural você querer enfrentar pessoalmente os inimigos dos seus amigos...","story.map2-dungeon7.012":"Mas acho melhor trabalharmos juntos, cada um na sua frente, e darmos tudo de nós!","story.map2-dungeon7.013":"Ei... <wait=20>ei! <wait=40>Parece um tremor, está ouvindo?","story.map2-dungeon7.014":"Ali!!","story.map2-dungeon7.015":"O-<wait=20>O que é aquilo!? <wait=40>Hordas de... <wait=20>monstros?!","story.map2-dungeon7.016":"...Maxwell. <wait=40>Então ela pretende nos deter aqui...","story.map2-dungeon7.017":"Não tem volta... <wait=40>Não temos escolha a não ser lutar... <wait=40>Aqui e agora...","story.map2-dungeon7.018":"...<wait=40>Espera, <wait=40>talvez haja outro jeito.","story.map2-dungeon7.019":"Só precisamos subir até o topo da Torre de Morgan <wait=40>e derrotar Abaddon lá.","story.map2-dungeon7.020":"Impossível!","story.map2-dungeon7.021":"Não tem como enfrentar todos esses monstros e ainda Abaddon...","story.map2-dungeon7.022":"Nem pense nisso. <wait=40>Provavelmente nem chegaríamos perto o bastante pra ver Abaddon.","story.map2-dungeon7.023":"Você tem razão. <wait=40>Mas <wait=20>esses monstros não vão passar daqui.","story.map2-dungeon7.024":"Eu vou detê-los bem aqui!","story.map2-dungeon7.025":"Karl!? <wait=40>Do que você está falando!?","story.map2-dungeon7.026":"Você pretende mesmo segurá-los aqui enquanto nós vamos enfrentar Abaddon?!","story.map2-dungeon7.027":"Isso mesmo. <wait=40>É a nossa única opção...","story.map2-dungeon7.028":"Mas olha só quantos são. <wait=40>Ninguém dá conta de todos eles sozinho!","story.map2-dungeon7.029":"Sim... <wait=40>Eu sei disso.","story.map2-dungeon7.030":"Mas se é aqui que tudo deve terminar, vou apostar no que der a melhor chance de derrotar Abaddon.","story.map2-dungeon7.031":"Karl...","story.map2-dungeon7.032":"<rep_handlename>, <wait=40>vá com a Seria.","story.map2-dungeon7.033":"Eu vou deter esses monstros. <wait=40>Você precisa ir e eliminar Abaddon.","story.map2-dungeon7.034":"...<wait=40>Eu não vou.","story.map2-dungeon7.035":"Seria!!","story.map2-dungeon7.036":"Essa horda <wait=20>é demais pra você enfrentar sozinho, Karl.","story.map2-dungeon7.037":"Se eu te ajudar a segurá-los <wait=20>só mais um pouquinho...","story.map2-dungeon7.038":"Talvez seja todo o tempo extra de que precisamos <wait=20>pra derrotar Abaddon.","story.map2-dungeon7.039":"Seria, <wait=40>você...","story.map2-dungeon7.040":"<rep_handlename>!","story.map2-dungeon7.041":"Você, <wait=40>os Invocadores Ancestrais reconheceram sua força como Invocador, não foi?","story.map2-dungeon7.042":"Então prove isso pra mim.","story.map2-dungeon7.043":"Eu acabo com você se não derrotar Abaddon!!","story.map2-dungeon7.044":"...<wait=40>Muito bem, <wait=20>vamos nessa!!","story.map2-dungeon7.045":"Tsc... <wait=20>Essa garota...","story.map2-dungeon7.046":"<rep_handlename>, <wait=40>vamos dar tudo de nós pra segurá-los.","story.map2-dungeon7.047":"Você precisa derrotar Abaddon.","story.map2-dungeon7.048":"Contamos com você, <wait=40><rep_handlename>.","story.map2-dungeon7.049":"Agora, <wait=40>à batalha!!","story.map2-ending.001":"<size=20><rep_handlename>! Você está bem?!</size>","story.map2-ending.002":"Ah, <wait=20>você... <wait=40>derrotou Abaddon?","story.map2-ending.003":"Uau... <wait=40>Você é mesmo muito forte.","story.map2-ending.004":"Não acredito que você conseguiu derrotar Abaddon sozinho...","story.map2-ending.005":"Ah, eu? <wait=20>Eu estou bem.","story.map2-ending.006":"Depois que nos separamos, <wait=20>dei tudo de mim protegendo a entrada da torre.","story.map2-ending.007":"Eu e a Seria fomos até o nosso limite, estávamos quase sendo derrotados...","story.map2-ending.008":"Mas, por sorte, os reforços do Salão dos Invocadores chegaram bem a tempo.","story.map2-ending.009":"Eles deram tudo de si pra nos ajudar...","story.map2-ending.010":"Hmm? <wait=20>A Seria? <wait=40>Ela está ali... <wait=40>Hã? <wait=20>Seria?","story.map2-ending.011":"Pra onde ela foi? <wait=40>...<wait=40>Hmm, <wait=20>deixa pra lá.","story.map2-ending.012":"Aliás, <wait=20>ela estava bem preocupada com você.","story.map2-ending.013":"Ela estava toda esfarrapada e exausta, mas insistiu em te ajudar e subiu direto pela torre...","story.map2-ending.014":"Hehe, <wait=20>nem sei o que ela faria se descobrisse que eu te contei tudo isso...","story.map2-ending.015":"Então não conta pra ela que eu te contei, tá?","story.map2-ending.016":"Mas, falando sério, <wait=40>você ficou forte de verdade.","story.map2-ending.017":"Corremos pra te ajudar, <wait=40>mas parece que você nem precisava de reforços.","story.map2-ending.018":"Pra mim, você já é um Invocador de primeira linha.","story.map2-ending.019":"Ah, <wait=20>é mesmo...","story.map2-ending.020":"No fim, não conseguimos derrubar o Graham.","story.map2-ending.021":"Mas conseguimos capturar alguns monstros e fazer eles abrirem o bico sobre o esconderijo do Graham.","story.map2-ending.022":"Só que ele fugiu pra um lugar aonde não conseguimos chegar... <wait=20>Desgraçado... ","story.map2-ending.023":"Não vai ser fácil encontrar ele.","story.map2-ending.024":"Vou ter que me reportar ao Salão dos Invocadores de Akras...","story.map2-ending.025":"Você... <wait=40>Bom, <wait=40>imagino que tenha seus próprios assuntos pra resolver.","story.map2-ending.026":"...<wait=20>É melhor eu ir indo.","story.map2-ending.027":"Nossos objetivos podem ser diferentes, <wait=40>mas sempre vou estar do seu lado.","story.map2-ending.028":"Trate de continuar vivo! <wait=40>Até mais!","story.map2-ending.029":"Ei! <wait=40><rep_handlename>!!","story.map2-ending.030":"Finalmente te alcancei!","story.map2-ending.031":"Você é simplesmente incrível!!","story.map2-ending.032":"Enquanto eu estava na Praia da Brisa, competindo com a Rainha do Gelo Selena pra ver quem era mais fofa...","story.map2-ending.033":"...parece que você derrotou Abaddon! Inacreditável!","story.map2-ending.034":"...Hã?!","story.map2-ending.035":"N-<wait=20>Não me entenda mal! <wait=40>Não foi um concurso de beleza nem nada do tipo...","story.map2-ending.036":"Quer dizer, a Selena nem apareceu!","story.map2-ending.037":"Além disso, <rep_handlename>, você não estava lá, então nem tinha ninguém pra julgar a competição, né?!","story.map2-ending.038":"...<wait=40>Que cara é essa!","story.map2-ending.039":"Eu tinha mesmo assuntos importantes na Praia da Brisa!","story.map2-ending.040":"Ah! <wait=20>Está ouvindo?<br><wait=40>Parece que o Lord Lucius está te chamando?","story.map2-ending.041":"<speed=12>Faça uma <wait=10>boa <wait=20>viagem<wait=30>...","story.map2-ending.042":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Eu sou Lucius...<br><wait=40>Deus do Portal...","story.map2-ending.043":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Salvador de Morgan...","story.map2-ending.044":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use meu poder <wait=40>e desbrave novas terras...","story.map2-ending.045":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Siga em frente <wait=20>e use seu poder para trazer paz a este mundo...","story.map2-ending.046":"Ah, <wait=20>você acordou.","story.map2-ending.047":"Bom dia, <wait=20> <rep_handlename>.","story.map2-ending.048":"Olha... <wait=40>Finalmente chegamos a St. Lamia.","story.map2-ending.049":"Este é... <wait=40>o domínio de Maxwell.","story.map2-ending.050":"...<wait=40><rep_handlename>, você também sente?","story.map2-ending.051":"Sinto as ondas de um poder imenso...","story.map2-ending.052":"Os monstros também estão mais fortes que antes. <wait=40>Precisamos manter o foco...","story.map2-ending.053":"Maxwell está no Palácio de St. Lamia.","story.map2-ending.054":"Batalhas duras nos esperam, <wait=40>vamos dar o nosso melhor juntos!","story.map2-ending.055":"O quê? <wait=40>Você quer saber onde eu estava quando você lutava em Morgan?","story.map2-ending.056":"Não seja mesquinho...","story.map2-ending.057":"Prometo dar o meu melhor em St. Lamia, <wait=40>tá?","story.map2-ending.058":"Muito bem, <wait=20>vamos nessa!!","story.map3-dungeon1.001":"<size=13>Que calor! <wait=40>Quero ir pra casa... <wait=40>Minha pobre pele não aguenta mais...","story.map3-dungeon1.002":"<size=20>Ei! <wait=20><rep_handlename>!","story.map3-dungeon1.003":"Você! <wait=20>Atrasado de novo!!","story.map3-dungeon1.004":"Não me diga que estava fazendo corpo mole em algum lugar mais fresquinho!?","story.map3-dungeon1.005":"Isto não é hora pra brincadeira! <wait=40>O que você tem a dizer?","story.map3-dungeon1.006":"Hã? <wait=20>E eu?","story.map3-dungeon1.007":"<size=15>Eu <size=14>não <size=13>fiz <size=12>corpo <size=11>mole <size=10>em <size=9>nenhum <size=8>momento<size=7>...<size=6>","story.map3-dungeon1.008":"Enfim, <wait=40>a partir de hoje vamos escalar o Vulcão Eldent.","story.map3-dungeon1.009":"O Vulcão Eldent é um vulcão ativo, então é muito perigoso.","story.map3-dungeon1.010":"Fique de olho nos fluxos de lava!","story.map3-dungeon1.011":"Bom, <wait=20>boa viagem!","story.map3-dungeon1.012":"O quê? <wait=40>Você quer conselhos mais práticos?","story.map3-dungeon1.013":"Está quente demais... Já cheguei no meu limite!","story.map3-dungeon1.014":"<size=20>Ah! <wait=40>Não aguento mais!","story.map3-dungeon1.015":"Vou pra casa tomar um banho,<wait=20> não vá morrer antes de eu voltar!","story.map3-dungeon2.001":"<size=12>Brrr...","story.map3-dungeon2.002":"Ah, <wait=20><rep_handlename>! <wait=40>Puxa, <wait=20>por que demorou tanto?!","story.map3-dungeon2.003":"Hã? <wait=40>O que tem de errado comigo?","story.map3-dungeon2.004":"Não tem nada de errado. <wait=40>Sou a mesma Tilith cheia de energia de sempre!","story.map3-dungeon2.005":"Tá, <wait=20>admito que está ficando um pouquinho frio por aqui.","story.map3-dungeon2.006":"Mas é só porque você me fez esperar demais, <rep_handlename>!","story.map3-dungeon2.007":"Fora isso, <wait=20>acho melhor eu te contar um pouco mais sobre o Monte Sagrado Craylia.","story.map3-dungeon2.008":"Esta montanha sagrada, o Monte Craylia, é a mais alta de St. Lamia.","story.map3-dungeon2.009":"Dizem que no pico dela existe uma fonte de poder espiritual, que parece ser a origem desta nevasca sem fim.","story.map3-dungeon2.010":"Além disso, <wait=40>dizem que o Rei dos Mares Leviathan também vive lá.","story.map3-dungeon2.011":"Por que será que ele saiu do mar pra morar no alto de uma montanha...","story.map3-dungeon2.012":"Hmm<wait=20>...","story.map3-dungeon2.013":"<size=12><wait=20>Hã... <wait=20>Brrr...","story.map3-dungeon2.014":"O quê? <wait=40>Não, sério, <wait=20>estou ótima!","story.map3-dungeon2.015":"Mas parece que fiquei tanto tempo parada neste lugar congelante que peguei um resfriado...","story.map3-dungeon2.016":"Acho que vou na frente. <wait=40>Boa sorte subindo esta montanha nevada!","story.map3-dungeon3.001":"*Suspiro* <wait=20>Hunf... <wait=40>Só mais um pouco...","story.map3-dungeon3.002":"Ah, <wait=20><rep_handlename>! <wait=40>Estava te esperando.","story.map3-dungeon3.003":"Pra chegar até Maxwell, temos que passar por aqui, <wait=40>a Floresta de Sangue.","story.map3-dungeon3.004":"Floresta de Sangue, que nome sinistro...","story.map3-dungeon3.005":"Dizem que quem tenta atravessar esta floresta acaba sendo encontrado coberto de sangue...","story.map3-dungeon3.006":"<size=20><size=18>Isso <size=20>é <size=16>muito, <size=19><size=17>muito, <size=18>completamente, <size=15>totalmente <size=17>sinistro<size=19>!","story.map3-dungeon3.007":"O quê? <wait=40>Você acha que estou agindo estranho?","story.map3-dungeon3.008":"Não estou agindo estranho! <wait=40>Estou graciosa como sempre, não acha?","story.map3-dungeon3.009":"Você está preocupado... <wait=20>comigo?","story.map3-dungeon3.010":"Entendi, <wait=20>mas se tem tempo pra ficar dizendo bobagens, por que não se apressa e encara logo esta floresta!","story.map3-dungeon3.011":"Boa sorte!!","story.map3-dungeon3.012":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon4.001":"*Cof* <wait=20>*Cof*... <wait=40>Ahh, <wait=20>ugh...","story.map3-dungeon4.002":"Ah, <wait=40><rep_handlename>... <wait=40>Você chegou...","story.map3-dungeon4.003":"Eu... <wait=40>não posso <wait=40>mais esconder isso de você...","story.map3-dungeon4.004":"Meu estado, <wait=20>não é uma doença. <wait=40>Eu não estou doente.","story.map3-dungeon4.005":"Maxwell... <wait=40>Ela me lançou uma maldição.","story.map3-dungeon4.006":"Desde... <wait=20>que pisamos em St. Lamia.","story.map3-dungeon4.007":"Agora que estamos chegando perto do Palácio de St. Lamia, <wait=40>está piorando...","story.map3-dungeon4.008":"Maxwell provavelmente <wait=40>me achou um incômodo...","story.map3-dungeon4.009":"Hmm? <wait=40>Você não foi afetado porque...","story.map3-dungeon4.010":"Eu estou... <wait=40>te protegendo dela.","story.map3-dungeon4.011":"...<wait=40>Tudo bem. <wait=40>Eu não me importo.","story.map3-dungeon4.012":"Obrigada por se preocupar... <wait=40>mas eu vou ficar bem.","story.map3-dungeon4.013":"Eu sou uma deusa, <wait=40>sua guia...","story.map3-dungeon4.014":"Com certeza vou <wait=40>te proteger...","story.map3-dungeon4.015":"Logo... <wait=40>vamos pegar Maxwell.","story.map3-dungeon4.016":"<wait=20>Vamos nessa, <rep_handlename>!!","story.map3-dungeon4.017":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon5.001":"<speed=12>...Ugh. <wait=40>*Cof* <wait=20>*Ofegante*... <wait=40>*Ofegante*...","story.map3-dungeon5.002":"<speed=12><rep_handlename>... <wait=40>Desculpa... <wait=40>Eu...","story.map3-dungeon5.003":"<speed=12>Eu não consigo... <wait=40>ir mais longe<wait=40>...","story.map3-dungeon5.004":"<speed=12><rep_handlename>, <wait=40>eu...","story.map3-dungeon5.005":"<speed=12>Não estou fazendo isso porque o Lord Lucius mandou...","story.map3-dungeon5.006":"<speed=12>Estou fazendo isso porque você é <rep_handlename>... <wait=40>E-<wait=20>Eu só queria te proteger.","story.map3-dungeon5.007":"<speed=12>Eu pedi ao Lord Lucius que me deixasse... <wait=40>*Cof* <wait=20>*Cof*","story.map3-dungeon5.008":"<speed=12>Tem tantos outros lugares <wait=40>que eu queria visitar com você...","story.map3-dungeon5.009":"<speed=12>Eu queria <wait=40>viajar mais...","story.map3-dungeon5.010":"<speed=12>Mas... <wait=40>parece que meu tempo está acabando...","story.map3-dungeon5.011":"<speed=12>Mesmo que eu caia... <wait=40>minha magia vai continuar te protegendo.","story.map3-dungeon5.012":"<speed=12>Me prometa<wait=20>.<wait=20>.<wait=40>.","story.map3-dungeon5.013":"<speed=10>...que <wait=40>você vai <wait=40>com certeza <wait=12>derrotar <wait=10>Max<wait=7>well<wait=5>...","story.map3-dungeon5.014":"<speed=10>Ugh...","story.map3-dungeon5.015":"<size=24>(Desmaia)","story.map3-dungeon5.016":"...<wait=40>...<wait=40>...","story.map3-dungeon5.017":"Ei! <wait=40>É você mesmo, <rep_handlename>!?","story.map3-dungeon5.018":"Você deve ser bem durão, <wait=40>pra chegar até aqui sozinho...","story.map3-dungeon5.019":"E aí, como foi com Abaddon??<wait=40>","story.map3-dungeon5.020":"<size=18>Ei, <wait=20>o que aconteceu com essa garota?! <wait=40>Ela ficou toda azul!!","story.map3-dungeon5.021":"<rep_handlename>... <wait=40>Não me diga que<wait=20>...","story.map3-dungeon5.022":"Não me diga que você ainda não sabe sintetizar antídotos?!","story.map3-dungeon5.023":"Eu sei, eu sei. <wait=40>Só estava brincando.","story.map3-dungeon5.024":"...É uma maldição? <wait=40>Como assim?","story.map3-dungeon5.025":"Peraí, do que você está falando!?","story.map3-dungeon5.026":"...<wait=60>...<wait=60>...<wait=60>!","story.map3-dungeon5.027":"Espera... <wait=40>você está dizendo que <wait=20>essa garota é uma deusa?","story.map3-dungeon5.028":"Você não está...<wait=40> brincando <wait=20>comigo, <wait=40>está?","story.map3-dungeon5.029":"E?","story.map3-dungeon5.030":"...<wait=60>...<wait=60>...","story.map3-dungeon5.031":"Então... <wait=40>foi Maxwell, é...","story.map3-dungeon5.032":"Queria poder ajudar, <wait=40>mas isso está além de mim...","story.map3-dungeon5.033":"Não é algo que dê pra curar sintetizando poções...","story.map3-dungeon5.034":"Mas espera, <wait=40>essa maldição foi lançada por Maxwell, certo?","story.map3-dungeon5.035":"Então derrotar Maxwell deve desfazer a maldição dela, não acha?","story.map3-dungeon5.036":"Se derrotar Maxwell não resolver, você sempre pode dar uma surra nela até ela desfazer!","story.map3-dungeon5.037":"É o único outro jeito que me vem à cabeça agora.","story.map3-dungeon5.038":"...<wait=20>Pode deixar. <wait=40>Eu cuido dela.","story.map3-dungeon5.039":"Minha equipe montou um acampamento aqui perto, vou levá-la pra lá.","story.map3-dungeon5.040":"É melhor você se apressar.","story.map3-dungeon5.041":"<size=22>Pare de ficar aí parado olhando pro nada!!","story.map3-dungeon5.042":"Ela está sofrendo por sua causa!","story.map3-dungeon5.043":"Isto não é hora de ficar à toa, você devia estar correndo para o Palácio de St. Lamia!","story.map3-dungeon5.044":"<size=14>...<wait=20>Que idiota.","story.map3-dungeon7.001":"<size=20><rep_handlename>! <wait=40>Que bom ver você vivo!!","story.map3-dungeon7.002":"Por que estou aqui? <wait=40>Ora, vim te ajudar!","story.map3-dungeon7.003":"<size=20>Droga!","story.map3-dungeon7.004":"<size=24>*Corte*","story.map3-dungeon7.005":"<size=24>*Corte*","story.map3-dungeon7.006":"...Raios, <wait=40>que horda temos aqui, hein?","story.map3-dungeon7.007":"A Seria me contou tudo.","story.map3-dungeon7.008":"Deixa que eu cuido das coisas aqui.","story.map3-dungeon7.009":"Seu tempo está acabando, não está? <wait=40>Corre!","story.map3-dungeon7.010":"<size=20>Ugh!","story.map3-dungeon7.011":"<size=24>*Corte*","story.map3-dungeon7.012":"<size=20>Vai logo!!","story.map3-dungeon7.013":"<rep_handlename>... <wait=40>contamos com você...","story.map3-ending.001":"<size=20><rep_handlename>!!","story.map3-ending.002":"*Ofegante*... <wait=40>hunf...","story.map3-ending.003":"Minha nossa, <wait=40>o Invocador conseguiu...","story.map3-ending.004":"Maxwell, um dos Quatro Deuses Caídos, foi derrotada!!","story.map3-ending.005":"Ufa... <wait=40>Mas foi por um triz...","story.map3-ending.006":"<size=20><rep_handlename>, muito bem!!","story.map3-ending.007":"Parece que derrotar Maxwell desfez mesmo a maldição.","story.map3-ending.008":"Pode apostar, <wait=40>que bom ver essa jovem deusa se recuperar...","story.map3-ending.009":"Aliás, <wait=20>como você chegou aqui antes de mim?!","story.map3-ending.010":"...<wait=20>Ela deve ser mesmo uma deusa. <wait=40>Acho que os poderes dela voltaram quando a maldição foi desfeita.","story.map3-ending.011":"Não acredito que <rep_handlename> teve a ajuda de uma deusa esse tempo todo<wait=40>...","story.map3-ending.012":"E, Seria, até você me surpreendeu. Você se dedicou de verdade por esses dois, não foi?","story.map3-ending.013":"E-<wait=30>Eu não agi pra defender <rep_handlename>.","story.map3-ending.014":"Fiz o que fiz pelo bem da deusa e também do mundo.","story.map3-ending.015":"Tá bom, tá bom... <wait=40>Já chega.","story.map3-ending.016":"<size=18>Você derrotou Maxwell! Esse é o meu <rep_handlename>!!","story.map3-ending.017":"...<wait=40>Bom, <wait=20>tudo bem.","story.map3-ending.018":"Enfim, <wait=40>pra um novato melhorar tão rápido...","story.map3-ending.019":"Bom, <wait=40>é mesmo impressionante.","story.map3-ending.020":"<rep_handlename>! <wait=40>Eu reconheço que você é um verdadeiro...","story.map3-ending.021":"<rep_handlename> conseguiu!! <wait=40><rep_handlename> venceu!!","story.map3-ending.022":"Abaddon e até Maxwell, todos foram derrotados!!","story.map3-ending.023":"Fiquei um pouco preocupada quando nos conhecemos...","story.map3-ending.024":"...mas agora <wait=20>não há dúvida de que você é o Invocador mais forte que existe!!","story.map3-ending.025":"<size=18>C-<wait=20>Com licença! <wait=40>Você está sendo bem irritante, por que não se acalma logo?!","story.map3-ending.026":"Não pode me culpar. <wait=40>Meu Invocador derrotou um dos Quatro Deuses Caídos!","story.map3-ending.027":"Nunca estive tão feliz!","story.map3-ending.028":"Ah, cala a boca! <wait=40>Pare de interromper quando alguém está tentando falar!!","story.map3-ending.029":"E que história melosa é essa de <wait=40>\'meu <rep_handlename>\'!?","story.map3-ending.030":"Vocês não estão namorando, estão?!","story.map3-ending.031":"Meu <rep_handlename> é o meu <rep_handlename>!","story.map3-ending.032":"Eu arrisquei minha vida pra manter <rep_handlename> vivo.","story.map3-ending.033":"Além disso, <wait=20><rep_handlename> se esforçou tanto pra me salvar...","story.map3-ending.034":"<rep_handlename> e eu estamos ligados pelo destino!","story.map3-ending.035":"Qual é o problema? <wait=40>Está com ciúmes ou algo assim?","story.map3-ending.036":"<size=20>Q-Qu-Quem teria ciúmes de uma pirralha dessas!?","story.map3-ending.037":"<size=18>E como assim, destino? <wait=40><size=24>Você é burra!?","story.map3-ending.038":"...Ei, <wait=20>calma, vocês duas...","story.map3-ending.039":"Só uma tola pegaria uma maldição por alguém como <rep_handlename>. <wait=20>Que burrice!","story.map3-ending.040":"<rep_handlename> teria ficado bem mesmo se você tivesse deixado ele em paz!!","story.map3-ending.041":"Além do mais, <wait=20>você não devia ser uma deusa?!","story.map3-ending.042":"Não dava pra você mesma quebrar a maldição?!","story.map3-ending.043":"Como assim!? <wait=40>Está dizendo que eu não dei o meu melhor!?","story.map3-ending.044":"Você estava à beira da morte no Santuário Recluso!","story.map3-ending.045":"Se eu não estivesse lá, você teria sido devorada por aqueles monstros!!","story.map3-ending.046":"Que absurdo! <wait=40><rep_handlename> teria me protegido mesmo sem você por perto!","story.map3-ending.047":"Você só fala, também não fez nada!","story.map3-ending.048":"E-<wait=10>Espera aí!! <wait=40>Quem você acha que cuidou de você?!","story.map3-ending.049":"Eu estava inconsciente, não lembro de nada...","story.map3-ending.050":"Ora, sua!!","story.map3-ending.051":"Ei, vocês duas... <wait=40>Parem com isso.","story.map3-ending.052":"<size=24>Cala a boca!!","story.map3-ending.053":"Opa...","story.map3-ending.054":"Pra começo de conversa, por que a Seria vive dando ordens pro <rep_handlename>!?","story.map3-ending.055":"Ela não conseguiu derrotar nem o Graham, quanto mais Abaddon!","story.map3-ending.056":"<size=12>Ai... <wait=40>Eu também estava naquela batalha, sabia...","story.map3-ending.057":"Pare de fazer pouco do meu <rep_handlename>!!","story.map3-ending.058":"E-<wait=20>Eu digo o que eu quiser! <wait=40>Está querendo briga!?","story.map3-ending.059":"Foi você que começou!","story.map3-ending.060":"E fique sabendo que eu sou bem poderosa quando não estou amaldiçoada!","story.map3-ending.061":"<size=24>Ah, pelo amor de Deus! <wait=40>Já chega!!","story.map3-ending.062":"<rep_handlename> derrotou Maxwell!","story.map3-ending.063":"Não é hora de discutir.","story.map3-ending.064":"...Hunf.","story.map3-ending.065":"Hunf.","story.map3-ending.066":"Vocês duas <wait=20>estão se comportando pior que a própria Maxwell...","story.map3-ending.067":"Mas enfim, <wait=20>tenho mesmo que tirar o chapéu pra você, <wait=20><rep_handlename>.","story.map3-ending.068":"Tenho orgulho de ser seu amigo.","story.map3-ending.069":"...<wait=40>Odeio dizer isso, <wait=40>mas não posso negar que você derrotou Maxwell.","story.map3-ending.070":"<wait=40>Bom trabalho.","story.map3-ending.071":"Ufa.","story.map3-ending.072":"Muito bem, <wait=20>a Seria e eu temos que ir agora.","story.map3-ending.073":"...Hã? <wait=40>Não precisa me agradecer.","story.map3-ending.074":"Só prometa que vai dar uma mão da próxima vez que a gente precisar!","story.map3-ending.075":"A gente se vê depois, amigo.","story.map3-ending.076":"Hunf, <wait=20>tchau.","story.map3-ending.077":"...Bom, <wait=40>deixa eu dizer de novo.","story.map3-ending.078":"Parabéns! <wait=40><rep_handlename>.","story.map3-ending.079":"Eu tinha fé de que você com certeza derrotaria Maxwell.","story.map3-ending.080":"Mas, em vez de eu te ajudar... <wait=40>foi você quem acabou me ajudando.","story.map3-ending.081":"Estou muito feliz. <wait=40>Obrigada.","story.map3-ending.082":"Hehe. <wait=40>Puxa, que vergonha.","story.map3-ending.083":"Ah, <wait=20>é mesmo. A gente prometeu visitar vários lugares juntos, não foi?","story.map3-ending.084":"Achei que eu ia morrer, <wait=40>por isso te fiz prometer aquilo.","story.map3-ending.085":"Mas, agora que você derrotou Maxwell, as coisas devem ficar ainda mais agitadas.","story.map3-ending.086":"Mesmo com Maxwell derrotada, <wait=40>os Quatro Deuses Caídos são quatro no total.","story.map3-ending.087":"Três deles ainda estão por aí.","story.map3-ending.088":"Até você derrotar todos os Deuses Caídos, <wait=40>a paz não vai voltar a Grand Gaia.","story.map3-ending.089":"Dito isso, <wait=40>vamos ter que adiar a aventura que prometemos um ao outro.","story.map3-ending.090":"Sinto muito, <wait=40>mas deusas são muito ocupadas, sabia?","story.map3-ending.091":"Bom, <wait=40>já está na hora de eu me reportar ao Lord Lucius.","story.map3-ending.092":"Continue aprimorando suas habilidades, <wait=20>você precisa ficar ainda mais forte se pretende derrotar o resto dos Deuses Caídos.","story.map3-ending.093":"Ah, <wait=40>e mais uma coisa...","story.map3-ending.094":"Se encontrar aqueles dois de novo, diga que eu agradeci.","story.map3-ending.095":"Diga que sou muito grata por tudo o que fizeram por nós.","story.map3-ending.096":"Bom, então, <wait=20>acho que vou indo!","story.map3-ending.097":"A gente se vê de novo em breve, <wait=20>tenho certeza!","story.map3-ending.098":"Até mais!!!","story.map4-dungeon1.001":"Pff... Não encontrei um único<br>monstro desde que cheguei aqui!","story.map4-dungeon1.002":"Não acredito... <wait=40> Por que eu, o poderoso Lugina, tenho que ficar com tarefas tão banais...","story.map4-dungeon1.003":"Hã?<wait=40><br>Ei, você aí! <wait=20>Identifique-se!","story.map4-dungeon1.004":"Ahá! <wait=20>Membro do Exército de Akras, é?<br>Qual é o seu nome?","story.map4-dungeon1.005":"<rep_handlename>?<wait=40><br>Pff... <wait=40>Nome bem esquisito, se quer saber.","story.map4-dungeon1.006":"O que foi?<wait=40><br>Quer saber o meu nome?","story.map4-dungeon1.007":"Não que eu tenha motivo para me apresentar<br>a um membro do exército regular, mas...","story.map4-dungeon1.008":"<wait=20>...Bom, se quer tanto saber, acho que não custa nada contar.","story.map4-dungeon1.009":"Eu sou o poderoso Invocador Lugina,<wait=40><br>estimado líder da 23ª Divisão de Caçadores de Demônios,<wait=40>","story.map4-dungeon1.010":"também conhecida como Sky Garden!<br>Trate de não esquecer!","story.map4-dungeon1.011":"E aí,<wait=40> está procurando alguma coisa por aqui ou o quê?","story.map4-dungeon1.012":"Hã?<wait=40> Você está numa missão para derrotar os Quatro Deuses Caídos?","story.map4-dungeon1.013":"Pff... Hehe... <size=24>Buahaha!","story.map4-dungeon1.014":"Então os velhotes de Akras<br>finalmente perderam o juízo!","story.map4-dungeon1.015":"Você não acha mesmo que o exército regular<br>tem chance contra os Quatro Deuses Caídos, acha?","story.map4-dungeon1.016":"Já passou da hora desses velhos caquéticos se aposentarem<br>e deixarem a caça aos demônios para profissionais como eu.","story.map4-dungeon1.017":"Hum? <wait=40>Você recebe ordens de uma deusa, é isso?<br>Não do Salão dos Invocadores?","story.map4-dungeon1.018":"...Isso é alguma piada?<wait=40><br>Ou você é burro assim mesmo?","story.map4-dungeon1.019":"Você ao menos sabe o que eu<br>estou fazendo aqui no fim do mundo?","story.map4-dungeon1.020":"Inacreditável... <wait=40>É por isso que eu sempre digo","story.map4-dungeon1.021":"que não dá para confiar em ninguém do exército regular.","story.map4-dungeon1.022":"Você sabia que este território onde<br>estamos foi descoberto há pouco pelo Salão dos Invocadores de Akras?","story.map4-dungeon1.023":"Ainda não foi investigado direito,<br>então é bom tomar cuidado por onde anda.","story.map4-dungeon1.024":"Você sabe como é, monstros e tudo mais.","story.map4-dungeon1.025":"Enfim, cabe a Invocadores poderosos<br>e fortes como este que vos fala","story.map4-dungeon1.026":"garantir que áreas potencialmente perigosas<br>como esta fiquem seguras o bastante para","story.map4-dungeon1.027":"Invocadores novatos<br>como você porem os pés.","story.map4-dungeon1.028":"Se tem juízo,<br>vá para um lugar mais seguro até eu terminar aqui!","story.map4-dungeon1.029":"Tem muitas áreas por aí em Grand Gaia<br>que ainda não foram investigadas direito.","story.map4-dungeon1.030":"O quê? Eu gaguejei ou algo assim?<wait=40><br>Credo, você é tão burro quanto parece.","story.map4-dungeon1.031":"Olha, vou ser mais claro...<br><wait=40>Sai da frente e me deixa trabalhar em paz!<wait=40>","story.map4-dungeon1.032":"Pare de perder tempo lutando com esses monstrinhos e vá procurar em outro lugar!","story.map4-dungeon1.033":"Tsc... Com patetas como você no exército regular, não admira que o Salão dos Invocadores esteja em apuros...","story.map4-dungeon2.001":"Você de novo?!<wait=40><br>Eu mandei você sumir daqui!","story.map4-dungeon2.002":"Que cara de pau a sua,<br>me ignorar desse jeito!","story.map4-dungeon2.003":"Ou será que precisa de alguém para segurar<br>sua mão e te levar para casa?","story.map4-dungeon2.004":"Credo... <wait=40>Nem o pessoal do Exército Imperial é tão incompetente assim.","story.map4-dungeon2.005":"Hã?<wait=40><br>Que cara de perdido é essa?","story.map4-dungeon2.006":"Espera aí... <wait=40>Não me diga que você <br>nunca ouviu falar do Exército Imperial de Randall?","story.map4-dungeon2.007":"Nossa. Simplesmente nossa...","story.map4-dungeon2.008":"Sério, você quase me faz<br>sentir pena de você.","story.map4-dungeon2.009":"Nesse caso, não tem outro jeito.","story.map4-dungeon2.010":"Eu, Lugina, de coração puro e virtuoso, vou te ensinar tudo o que você precisa saber!","story.map4-dungeon2.011":"Enxugue essas lágrimas de gratidão<br>e grave bem o que vou te dizer!","story.map4-dungeon2.012":"Vamos começar pelo fácil. <wait=40>Você já sabe que a nossa terra, Elgaia, se separou de Grand Gaia.","story.map4-dungeon2.013":"Sabe, a Terra dos Deuses,<br>certo?","story.map4-dungeon2.014":"Muito bem,<wait=40> pelo menos alguma coisa você sabe!","story.map4-dungeon2.015":"Não sei por que essa cara de orgulho!<wait=40> Isso é o básico do básico.","story.map4-dungeon2.016":"Credo...","story.map4-dungeon2.017":"Certo, vamos continuar. <wait=40>Elgaia é formada por dois grandes países.","story.map4-dungeon2.018":"Um deles, o Império Randall, abriga o Salão dos Invocadores de Akras.","story.map4-dungeon2.019":"O Salão dos Invocadores de Akras cuida dos assuntos econômicos","story.map4-dungeon2.020":"e militares da nação, então essa história de império é só fachada, na verdade.","story.map4-dungeon2.021":"A elite de Randall descende<br>daqueles que reconstruíram a nação depois que ela","story.map4-dungeon2.022":"se separou de Grand Gaia, o que explica em parte por que eles são tão arrogantes.","story.map4-dungeon2.023":"Hoje em dia não passam de um bando de velhos caquéticos curtindo sua vida mimada.","story.map4-dungeon2.024":"Nem preciso dizer que o exército deles é quase só fachada, uma demonstração de autoridade, por assim dizer.","story.map4-dungeon2.025":"Se bem que, de vez em quando, um ou outro soldado talentoso passou pelas fileiras deles.","story.map4-dungeon2.026":"Enfim, <wait=40>o outro país é a Federação de Elgaia,","story.map4-dungeon2.027":"mas a história deles é bem parecida.","story.map4-dungeon2.028":"Nenhum dos dois países tem o que é preciso para enfrentar o Salão dos Invocadores de Akras,","story.map4-dungeon2.029":"então, na prática, o Salão governa<br>Elgaia inteira.","story.map4-dungeon2.030":"E como eu sou o Invocador mais poderoso<br>do Salão dos Invocadores de Akras,","story.map4-dungeon2.031":"isso me torna o mais poderoso de Elgaia inteira!","story.map4-dungeon2.032":"E aí?<wait=40><br>Deve estar querendo meu autógrafo, né?","story.map4-dungeon2.033":"<size=14>(Rumble, rumble)","story.map4-dungeon2.034":"O-<wait=20>Opa!","story.map4-dungeon2.035":"F-<wait=20>Foi um terremoto?!","story.map4-dungeon2.036":"Mas não pareceu um terremoto<br>comum...","story.map4-dungeon2.037":"Agora entende o que eu quis dizer?!","story.map4-dungeon2.038":"Cordelica não vai estar segura enquanto não descobrirmos o que está acontecendo.","story.map4-dungeon2.039":"Agora ouça minhas sábias palavras e saia daqui enquanto ainda pode!","story.map4-dungeon2.040":"Você vai se arrepender se cruzarmos caminho de novo!","story.map4-dungeon3.001":"<size=20>Você de novo?!<wait=40> <rep_handlename>!","story.map4-dungeon3.002":"Por que ainda está aqui!?","story.map4-dungeon3.003":"Certo, agora chega!","story.map4-dungeon3.004":"Se não vai ouvir meu conselho,<wait=40> vou ter que enfiar um pouco de juízo nessa sua cabeça na marra!","story.map4-dungeon3.005":"Agora fique parado aí!","story.map4-dungeon3.006":"<size=14>(Rumble, rumble)","story.map4-dungeon3.007":"D-De novo não!<wait=40><br>O que é que há com esses terremotos ultimamente?","story.map4-dungeon3.008":"Ei!<wait=40> <rep_handlename>!","story.map4-dungeon3.009":"Agora entende do que<br>eu estou falando?","story.map4-dungeon3.010":"Isto aqui não é lugar para um Invocador novato como você ficar zanzando.","story.map4-dungeon3.011":"Agora volte para casa e confira<br>se não é só o Exército Imperial aprontando alguma!","story.map4-dungeon3.012":"...<wait=20>Que cara é essa?","story.map4-dungeon3.013":"Por que tenho a impressão de que você ainda não entendeu o quanto eu sou incrível...","story.map4-dungeon3.014":"Certo, preste atenção.<wait=40><br>Eu já te disse isso antes,","story.map4-dungeon3.015":"mas aqui em Elgaia existem várias facções separadas,<br>cada uma com seu próprio exército.","story.map4-dungeon3.016":"O mais forte desses exércitos pertence ao Salão dos Invocadores de Akras.","story.map4-dungeon3.017":"Faz sentido, né?<br>Quer dizer, eles reúnem quase todos os","story.map4-dungeon3.018":"Invocadores de Elgaia, afinal...","story.map4-dungeon3.019":"Enfim, o exército de Akras é composto<br>por três tipos diferentes de forças.","story.map4-dungeon3.020":"Primeiro, <wait=40>tem o Exército de Invocadores, também chamado de Exército Regular, onde todo Invocador novato","story.map4-dungeon3.021":"começa. Esse é o seu regimento, aliás.","story.map4-dungeon3.022":"Sua missão oficial é derrotar os Quatro Deuses Caídos, mas... bem, como posso dizer?","story.map4-dungeon3.023":"Na verdade, ninguém espera que o<br>Exército Regular consiga alguma coisa.","story.map4-dungeon3.024":"Então de quem esperam que resolva o problema, você pergunta?<br>Ora, da minha turma, os Caçadores de Demônios!","story.map4-dungeon3.025":"Somos uma tropa de elite de Invocadores<br>escolhidos a dedo nas fileiras do Exército Regular.","story.map4-dungeon3.026":"Os mais fortes, como eu, por exemplo, recebem o comando de esquadrões menores.","story.map4-dungeon3.027":"E, claro, o mais forte de todos é justamente o que eu comando:","story.map4-dungeon3.028":"A 23ª Divisão de Caçadores de Demônios, Sky Garden!","story.map4-dungeon3.029":"E você achando que eu não conseguiria<br>me superar, hein?","story.map4-dungeon3.030":"Hum? <wait=40>E os exércitos de Randall<br>e da Federação de Elgaia, você diz?","story.map4-dungeon3.031":"Ha! Mal têm um punhado de Invocadores juntos. São ainda mais inúteis que o nosso Exército Regular.","story.map4-dungeon3.032":"Agora pare de me encher com essas perguntas e volte para casa, que é o seu lugar!","story.map4-dungeon3.033":"Os monstros daqui não são<br>moles como os que você está acostumado a enfrentar!","story.map4-dungeon3.034":"Ouviu bem? Xô!","story.map4-dungeon3.035":"*Suspiro* <wait=40>O que foi que eu fiz para<br>me mandarem para este fim de mundo?","story.map4-dungeon3.036":"Então mandaram o Caçador de Demônios Lugina, do Sky Garden...","story.map4-dungeon3.037":"Heh. Provavelmente só queriam que ele<br>parasse de incomodá-los um pouco...","story.map4-dungeon3.038":"Ainda assim, parece que vai ser bem fácil usá-lo para os meus propósitos.","story.map4-dungeon3.039":"Agora só falta bolar um plano...","story.map4-dungeon4.001":"<size=20>Você de novo?! <rep_handlename>!","story.map4-dungeon4.002":"Agora chega! Acabou o bonzinho!","story.map4-dungeon4.003":"Espero que goste desse lugar onde você está, porque é aí que vou te enterrar quando terminar!","story.map4-dungeon4.004":"<size=18>(Rumble, rumble)","story.map4-dungeon4.005":"Mais um...?<br>Esses terremotos definitivamente não são normais.","story.map4-dungeon4.006":"Aqueles velhos tolos do Salão dos Invocadores...<br>Que se danem todos eles!","story.map4-dungeon4.007":"Escuta, <rep_handlename>!","story.map4-dungeon4.008":"Este lugar é perigoso demais para<br>ficarmos de bobeira.","story.map4-dungeon4.009":"Vou registrar o que descobri e voltar<br>para Elgaia agora mesmo. <wait=40>Você vai ser minha testemunha, né?","story.map4-dungeon4.010":"Pense em tudo o que eu te ensinei!<br>Você não deixaria um velho camarada na mão, deixaria?","story.map4-dungeon4.011":"Que discurso covarde para alguém que se diz do alto escalão dos Caçadores de Demônios, não acha?","story.map4-dungeon4.012":"...?!<br><wait=40>Quem é você?","story.map4-dungeon4.013":"E-Esse brasão...","story.map4-dungeon4.014":"Não pode ser!<br>Um membro da Guarda Imperial?!","story.map4-dungeon4.015":"Exatamente.<br>Talvez você tenha mesmo jeito para ensinar.","story.map4-dungeon4.016":"Meu nome é Paris. Pertenço a uma<br>das forças “inúteis” que você estava descrevendo agora há pouco.","story.map4-dungeon4.017":"Você ficou escutando escondida esse tempo todo?<br>Ninguém nunca te ensinou boas maneiras?","story.map4-dungeon4.018":"Eu poderia perguntar o mesmo a você.","story.map4-dungeon4.019":"Ou você consideraria ignorar as<br>ordens do seu país, sem falar em menosprezar","story.map4-dungeon4.020":"o Exército Imperial que trabalha<br>pela prosperidade do nosso reino, um comportamento honrado?","story.map4-dungeon4.021":"Pff...<br><wait=40>Ah, mil perdões! Por favor, me desculpe!","story.map4-dungeon4.022":"Como eu imaginava, vocês do Salão dos Invocadores<br>são todos igualmente grosseiros...","story.map4-dungeon4.023":"Conta isso para quem se importa,<br>moça!","story.map4-dungeon4.024":"Além disso, vocês patetas da Guarda Imperial<br>protegem a Família Imperial, não é?","story.map4-dungeon4.025":"O que está fazendo aqui no fim do mundo?","story.map4-dungeon4.026":"Não tenho o dia todo,<br>então desembucha logo!","story.map4-dungeon4.027":"Heh...<br>Você é bem animado para um ajudante.","story.map4-dungeon4.028":"Quem você está chamando de ajudante?!","story.map4-dungeon4.029":"Acha que eu e esse pateta aqui somos parceiros? Ha!","story.map4-dungeon4.030":"Tanto faz, moça.<br>Tenho coisa melhor para fazer com","story.map4-dungeon4.031":"meu tempo do que arrumar briga com a<br>Guarda Imperial aqui no meio do mato.","story.map4-dungeon4.032":"Ah, a famosa diplomacia dos Caçadores de Demônios.<br>Pelo menos todo mundo sabe onde está pisando.","story.map4-dungeon4.033":"Bem, para ser sincera, vim de tão longe para te pedir um favor.","story.map4-dungeon4.034":"Queremos sua ajuda<br>para investigar Cordelica.","story.map4-dungeon4.035":"Ha!<wait=40><br>Você disse mesmo o que eu acho que disse?","story.map4-dungeon4.036":"Não estou procurando briga, <wait=40>mas também não vou seguir suas ordens!","story.map4-dungeon4.037":"Este lugar não é seguro para ficarmos,<br>caso você não tenha notado.","story.map4-dungeon4.038":"Vejo que você está ciente do perigo<br>que esta região representa.","story.map4-dungeon4.039":"Claro, eu não esperaria nada<br>menos de alguém que se diz líder dos Caçadores de Demônios.","story.map4-dungeon4.040":"O que você está querendo insinuar, hein?","story.map4-dungeon4.041":"Insinuar?<wait=40> Não, só estou constatando fatos.","story.map4-dungeon4.042":"Alguém que tem medo de<br>uns terremotos de nada não poderia","story.map4-dungeon4.043":"liderar um esquadrão talentoso como você diz que lidera, certo?","story.map4-dungeon4.044":"Ora, sua!<wait=40><br>Olha como fala!","story.map4-dungeon4.045":"Está me chamando de covarde?!","story.map4-dungeon4.046":"Não me faça rir!<wait=40><br>Vou te mostrar o que é ter medo!","story.map4-dungeon4.047":"Ei!<wait=40> <rep_handlename>!","story.map4-dungeon4.048":"Está na hora de você fazer a sua parte por aqui!","story.map4-dungeon4.049":"Até agora você ignorou tudo<br>o que eu te disse.","story.map4-dungeon4.050":"Deve se achar o máximo, né?","story.map4-dungeon4.051":"Bom, se você é tão bom assim, por que não prova acabando com o nanico escondido naquela fortaleza ali!","story.map4-dungeon4.052":"Os monstros que vamos encontrar<br>vão ficar mais fortes daqui em diante,","story.map4-dungeon4.053":"mas até você não deve ter<br>problema com aquele bando ali.","story.map4-dungeon4.054":"Hehe... <wait=40>Isso vai ser interessante.","story.map4-dungeon4.055":"...E aí?! Não fique parado aí de boca aberta!<wait=40><br>Vá lá e mostre do que é capaz!","story.map4-dungeon4.056":"Você ouviu o homem,<br><rep_handlename>... Hehe.","story.map4-dungeon5.001":"Hunf! <wait=40>Você demorou<br>uma eternidade para chegar aqui.","story.map4-dungeon5.002":"E ainda perguntam por que eu não<br>respeito mais vocês do Exército Regular.","story.map4-dungeon5.003":"Ainda assim, pelo menos você chegou antes daquela metida da Guarda Imperial, já é alguma coisa.","story.map4-dungeon5.004":"E quem seria essa, então?","story.map4-dungeon5.005":"O quê? <wait=20>Você?!<wait=40><br>Há quanto tempo está aí parada!","story.map4-dungeon5.006":"Desde pouco antes de você chegar e<br>começar a passar vergonha.","story.map4-dungeon5.007":"Ora, sua! <wait=40>Você ficou<br>me vigiando esse tempo todo!","story.map4-dungeon5.008":"Ah, relaxa, pode ser?","story.map4-dungeon5.009":"Tenho coisas mais importantes para fazer<br>com meu tempo do que analisar cada movimentinho seu.","story.map4-dungeon5.010":"Argh, me deixa pegar ela!","story.map4-dungeon5.011":"É por isso que eu odeio vocês da Guarda<br>Imperial, sempre tão convencidos!","story.map4-dungeon5.012":"Você pode reclamar depois.<wait=40><br>Primeiro, me diga o que está fazendo aqui.","story.map4-dungeon5.013":"Hã?<wait=40> <br>Isso é alguma piada?","story.map4-dungeon5.014":"Estou aqui para investigar as ruínas, é claro.","story.map4-dungeon5.015":"Olhe só para elas! Devem estar<br>aqui desde antes do Grande Colapso.","story.map4-dungeon5.016":"Você já viu algum lugar<br>implorando tanto para ser investigado?","story.map4-dungeon5.017":"Enfim, vim aqui dar uma<br>olhada, e esse aí veio me seguindo.","story.map4-dungeon5.018":"Entendo...<wait=40><br>Então você lê a escrita antiga, imagino?","story.map4-dungeon5.019":"Eu tinha a impressão de que quem<br>deveria investigar era eu...","story.map4-dungeon5.020":"O que foi? Acha que eu não dou conta, é!?","story.map4-dungeon5.021":"Só você é capaz<br>de algo intelectual, é isso?","story.map4-dungeon5.022":"Não, <wait=40>na verdade, estou bem impressionada.","story.map4-dungeon5.023":"Talvez você não seja tão burro quanto<br>esse seu jeito bruto sugere.","story.map4-dungeon5.024":"...<wait=40>Estou te avisando,<br>moça.","story.map4-dungeon5.025":"Não pense que eu não vou reagir se continuar me provocando.","story.map4-dungeon5.026":"E acredite, quando eu fico bravo,<br>sou capaz de reduzir as coisas a pó!","story.map4-dungeon5.027":"Guarda Imperial ou não.","story.map4-dungeon5.028":"Nossa, que medo.<br>Melhor eu ficar do seu lado bom, então.","story.map4-dungeon5.029":"Grrr...<wait=40><br>Eu sabia! Você está tirando sarro de mim!","story.map4-dungeon5.030":"Hehe...<wait=40><br>Acha mesmo que eu seria tão cruel?","story.map4-dungeon5.031":"Aliás, é melhor você também tomar cuidado para não irritar o Lugina, entendeu?","story.map4-dungeon5.032":"Não que eu consiga imaginar<br>um amigo do Karl ficando","story.map4-dungeon5.033":"com medo de alguém do Sky Garden...","story.map4-dungeon5.034":"Hã?<wait=40><br>Esse Karl de quem você fala... <wait=40>Por acaso seria o Karl de Nyonne?","story.map4-dungeon5.035":"<size=20>Buahaha!","story.map4-dungeon5.036":"Ah, fazia tempo que eu não ria assim.<wait=40><br>Só a ideia desse pateta ser amigo do Karl!","story.map4-dungeon5.037":"Agora eu já ouvi de tudo...","story.map4-dungeon5.038":"Ei, aonde você pensa que vai?!","story.map4-dungeon5.039":"Investigar.<wait=40><br>Cobrimos mais terreno se nos separarmos, não acha?","story.map4-dungeon5.040":"Lugina,<wait=40><br>você verifica ali.","story.map4-dungeon5.041":"E-Espera!<wait=40><br>Como é que eu vou saber onde...","story.map4-dungeon5.042":"...Hunf.","story.map4-dungeon5.043":"Se ela vai mentir na minha cara,<br>podia pelo menos tentar ser um pouco convincente.","story.map4-dungeon5.044":"Heh, como se esse ignorante pateta<br>pudesse mesmo conhecer o Karl...","story.map4-dungeon5.045":"Grr... <wait=40>Só de pensar naquele<br>almofadinha de cara de menina, meu sangue ferve!","story.map4-dungeon5.046":"Ei, você! <wait=40>Não fique aí parado com cara de bobo! Vá lá e cuide daqueles monstros!","story.map4-dungeon6.001":"<size=20>Argh, <wait=40>agora chega!","story.map4-dungeon6.002":"Cansei disso!<br>O que foi que eu fiz para merecer isso, hein?!","story.map4-dungeon6.003":"Por que sou eu que tenho que<br>enfrentar essas feras monstruosas!","story.map4-dungeon6.004":"Não é justo!<wait=40><br>Eu não fiz nada para merecer isso!","story.map4-dungeon6.005":"Aaah!!<wait=40><br>...Ah, é só você, <rep_handlename>.","story.map4-dungeon6.006":"Tsc... Só tive problemas<br>desde que esbarrei em você.","story.map4-dungeon6.007":"Reclamando como sempre, pelo visto?<br>Francamente, Lugina, isso não fica bem para um homem da sua posição.","story.map4-dungeon6.008":"Cala a boca, você!<wait=40><br>Qual é a sua, afinal, vivendo me pegando de surpresa desse jeito!","story.map4-dungeon6.009":"Você é um dos motivos de eu ter<br>me metido nessa confusão, para começo de conversa!","story.map4-dungeon6.010":"Nossa situação atual está longe do ideal,<br>isso eu admito.","story.map4-dungeon6.011":"Mas xingar as pessoas e reclamar das coisas não vai mudar a situação.","story.map4-dungeon6.012":"Acha que eu já não sei<br>disso?!","story.map4-dungeon6.013":"Tenho uma novidade para você: eu não estou rastejando por esses túneis imundos por diversão, tá bom!","story.map4-dungeon6.014":"Hehe...<wait=40><br>Não, isso eu percebo.","story.map4-dungeon6.015":"Ainda assim, você parece saber<br>o que precisa ser feito.","story.map4-dungeon6.016":"Certo. <wait=40>E é disso que eu estou reclamando.","story.map4-dungeon6.017":"Muito bem! Vamos atravessar logo este<br>túnel e correr para as Ruínas do Gigante.","story.map4-dungeon6.018":"Nossa, alguém parece estar com pressa...<wait=40> É melhor você se apressar também.","story.map4-dungeon6.019":"Se não nos apressarmos, os grandes deuses vão<br>despertar e devastar este continente inteiro.","story.map4-dungeon6.020":"Não temos tempo para ficar explicando as coisas para esse tapado!","story.map4-dungeon6.021":"Eu vou na frente.","story.map4-dungeon6.022":"Você acaba com os retardatários<br>que conseguirem passar por mim!","story.map4-dungeon6.023":"Heh...<wait=40><br>Falou como um verdadeiro guerreiro, Lugina.","story.map4-dungeon6.024":"Mas você está enganado sobre uma coisa.","story.map4-dungeon6.025":"<rep_handlename> tem o direito de saber<br>do perigo da nossa situação.","story.map4-dungeon6.026":"Você viu <rep_handlename> lutar,<br>não viu?","story.map4-dungeon6.027":"Devemos aproveitar todo o<br>poderio militar ao nosso alcance.","story.map4-dungeon6.028":"Hunf! <wait=40>Faça como quiser.<br>Mas toda a explicação fica com você!","story.map4-dungeon6.029":"Já estou por aqui de<br>bancar a babá desse bebezão.","story.map4-dungeon6.030":"Parece que ele decidiu ir<br>sozinho, afinal.","story.map4-dungeon6.031":"Tsc... Ele nunca vai fazer amigos<br>com esse azedume todo.","story.map4-dungeon6.032":"Bem,<wait=40><br>parece que finalmente somos só nós dois!","story.map4-dungeon6.033":"Então você é a pessoa de quem os Anciãos falam, amigo de Karl,","story.map4-dungeon6.034":"líder da todo-poderosa 24ª Divisão de Caçadores de Demônios, Rebluens.","story.map4-dungeon6.035":"Ouvi grandes histórias sobre você,<br><rep_handlename>.","story.map4-dungeon6.036":"Não precisa ficar tão<br>alarmado.","story.map4-dungeon6.037":"Relaxa.<wait=40><br>Estou do seu lado, sabia?","story.map4-dungeon6.038":"Pela sua expressão, ainda tenho um longo caminho até ganhar sua confiança.","story.map4-dungeon6.039":"Onde eu estava mesmo?<wait=40><br>Ah, sim, os gigantes.","story.map4-dungeon6.040":"Na verdade, não é tão complicado.","story.map4-dungeon6.041":"Há muito tempo, uma raça de gigantes vivia<br>aqui em Cordelica.","story.map4-dungeon6.042":"Porém, a raça inteira foi<br>exterminada por forças além da nossa compreensão.","story.map4-dungeon6.043":"Todos, exceto um deles:<br>aquele hoje conhecido como o Deus Gigante.","story.map4-dungeon6.044":"Tomado pela fúria e pelo desespero<br>por seus companheiros caídos, ","story.map4-dungeon6.045":"o gigante se selou nesta terra.","story.map4-dungeon6.046":"Esta é a lenda como está inscrita na<br>Torre da Luz. <wait=40>Quem a escreveu, não sabemos.","story.map4-dungeon6.047":"Lugina deve ter encontrado<br>a mesma inscrição.","story.map4-dungeon6.048":"Depois de lê-la, <wait=40>ele deve<br>ter chegado à mesma conclusão que eu...","story.map4-dungeon6.049":"Ou seja, que o Deus Gigante logo vai<br>despertar do seu sono, espumando de raiva.","story.map4-dungeon6.050":"Heh...<wait=40> <br>Parece que finalmente tenho toda a sua atenção.","story.map4-dungeon6.051":"Relaxa.<wait=40><br>A julgar pela força dos tremores,","story.map4-dungeon6.052":"o Deus Gigante ainda não despertou por completo.","story.map4-dungeon6.053":"Segundo a inscrição das ruínas,<br>quando o gigante enfim despertar,","story.map4-dungeon6.054":"esta ilha inteira será engolida<br>num instante.","story.map4-dungeon6.055":"Venha.<wait=40><br>Precisamos partir agora mesmo.","story.map4-dungeon6.056":"As ruínas onde jaz o Deus Gigante devem ficar logo depois deste túnel.","story.map4-dungeon7.001":"...Sim. <wait=40>Grantos ainda está sonolento,<br>mas agora está acordado.","story.map4-dungeon7.002":"Não, senhor, <wait=40>isso não será<br>problema.","story.map4-dungeon7.003":"Claro, senhor.<wait=40><br>Eu o manterei informado de qualquer novidade.","story.map4-dungeon7.004":"Ei, <wait=40>mulher!","story.map4-dungeon7.005":"Já terminou de fofocar<br>aí?","story.map4-dungeon7.006":"Está me dedurando para algum dos seus<br>amiguinhos Imperiais, é?","story.map4-dungeon7.007":"Heh. Nada te escapa, não é?","story.map4-dungeon7.008":"O Império tem grande interesse em<br>jovens Invocadores talentosos.","story.map4-dungeon7.009":"Bah!<wait=40><br>Pois o interesse não é recíproco!","story.map4-dungeon7.010":"...!","story.map4-dungeon7.011":"Ei, <rep_handlename>!<br>Dá para se apressar um pouco?","story.map4-dungeon7.012":"Caso você não tenha percebido, estamos<br>meio que no meio de uma emergência aqui!","story.map4-dungeon7.013":"Se está com tanta pressa,<br>por que não foi na frente sem nós?","story.map4-dungeon7.014":"Vocês podem não estar à altura do grande Lugina, mas até amadores como vocês têm sua utilidade!","story.map4-dungeon7.015":"Heh...","story.map4-dungeon7.016":"Certo, prestem atenção.<wait=40><br>Eu vou lá matar Grantos,","story.map4-dungeon7.017":"o Deus Gigante que está dormindo<br>há centenas de anos.","story.map4-dungeon7.018":"Como sou poderoso e tudo mais,<br>eu é que vou fazer o trabalho pesado.","story.map4-dungeon7.019":"Dito isso, não quero ser incomodado<br>por lacaios irritantes enquanto isso.","story.map4-dungeon7.020":"É aí que vocês entram.<wait=40> Vocês vão atrair a atenção deles enquanto eu enfrento o grandão!","story.map4-dungeon7.021":"Você vai enfrentar um monstro<br>daquele tamanho sozinho? Que cavalheiro...","story.map4-dungeon7.022":"Sarcástica, é?","story.map4-dungeon7.023":"Como se vocês tivessem o que é preciso<br>para encarar um gigante daqueles!","story.map4-dungeon7.024":"Prefiro enfrentá-lo sozinho a ter que tirar vocês dois de apuros quando tudo der errado.","story.map4-dungeon7.025":"Vocês vão ver, <wait=40>vou mostrar o que é poder de verdade.","story.map4-dungeon7.026":"Então estamos entendidos? <wait=40>Vocês distraem os lacaios enquanto eu salvo o mundo!","story.map4-dungeon7.027":"E lembrem-se: se estragarem tudo,<br>eu acabo com vocês com as suas próprias espadas!","story.map4-dungeon7.028":"Mandão ele certamente é, o bastante para liderar<br>um regimento de Caçadores de Demônios...","story.map4-dungeon7.029":"O tom dele deixa muito a desejar,","story.map4-dungeon7.030":"mas pelo menos ele parece capaz<br>e bem informado.","story.map4-dungeon7.031":"Sem falar que reuniu mais<br>dados do que eu esperava.","story.map4-dungeon7.032":"Ainda assim, pelo que eu descobri,","story.map4-dungeon7.033":"não tem como ele enfrentar<br>Grantos sozinho.","story.map4-dungeon7.034":"Acho que vou precisar dar uma mãozinha a ele.","story.map4-dungeon7.035":"Claro,<wait=40><br>ele também vai precisar da sua ajuda.","story.map4-dungeon7.036":"Está na hora de ver do que você é<br>realmente capaz.","story.map4-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_clear.002":"Você conseguiu, <rep_handlename>!","story.map4-dungeon_ex_clear.003":"Muito obrigada!","story.map4-dungeon_ex_clear.004":"Eu sabia que você conseguiria!","story.map4-dungeon_ex_clear.005":"Você é demais!","story.map4-dungeon_ex_clear.006":"Hehe, <wait=20>desculpe, me empolguei um pouco.","story.map4-dungeon_ex_clear.007":"Enfim, descobrimos o que era aquele monstro.","story.map4-dungeon_ex_clear.008":"Parece que originalmente os gigantes o mantinham para cuidar do lixo.","story.map4-dungeon_ex_clear.009":"Porém, ele logo ficou tão grande que nem eles conseguiam mais controlá-lo. ","story.map4-dungeon_ex_clear.010":"No fim, ele foi trancado naquele lugar por um certo herói.","story.map4-dungeon_ex_clear.011":"Esse herói devia ser incrivelmente forte para dominar um monstro que nem os gigantes conseguiam controlar.","story.map4-dungeon_ex_clear.012":"Ah, <wait=20>mas é claro que você também é forte!","story.map4-dungeon_ex_clear.013":"Quer dizer, você derrotou aquele monstro enorme sozinho!","story.map4-dungeon_ex_clear.014":"E ele era tão gosmento e nojento...","story.map4-dungeon_ex_clear.015":"Eu admiro muito você, <rep_handlename>!","story.map4-dungeon_ex_clear.016":"Hã, o que é isso?","story.map4-dungeon_ex_clear.017":"Tem alguma coisa no seu ombro. <wait=20>Será que...","story.map4-dungeon_ex_clear.018":"<size=21>Kyaaaaahh!</size>","story.map4-dungeon_ex_clear.019":"<size=21>Eca, está todo gosmento!!</size>","story.map4-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_open.002":"Senhor, <wait=20>temos um problema! <wait=40>Um problemão!","story.map4-dungeon_ex_open.003":"Desculpe! Não queria causar pânico...","story.map4-dungeon_ex_open.004":"Lin Merylham, do Suporte Logístico...","story.map4-dungeon_ex_open.005":"...do Departamento de Investigação do Escritório de Pesquisa de Grand Gaia, ao seu dispor.","story.map4-dungeon_ex_open.006":"C-<wait=20>Como você consegue ficar tão calmo numa hora dessas!?","story.map4-dungeon_ex_open.007":"<rep_handlename>, como membro do Exército de Invocadores do Salão dos Invocadores de Akras...","story.map4-dungeon_ex_open.008":"...pedimos que você investigue a Caverna de Ignia!","story.map4-dungeon_ex_open.009":"Parece que havia um monstro adormecido atrás das Cataratas de Ignia.","story.map4-dungeon_ex_open.010":"Porém, o terremoto em Cordelica outro dia parece tê-lo despertado.","story.map4-dungeon_ex_open.011":"E sobre o monstro em si...","story.map4-dungeon_ex_open.012":"Ele é todo molhado e grudento, e come tudo!","story.map4-dungeon_ex_open.013":"Só de imaginar um monstro enorme e nojento assim já me dá arrepios.","story.map4-dungeon_ex_open.014":"<size=21>Kyaaaaaahh! Que nojo!!</size>","story.map4-ending.001":"Heh, <wait=40>bem como eu suspeitava.","story.map4-ending.002":"Não admira que Karl tenha você em tão alta conta.","story.map4-ending.003":"(Uff... <wait=40>arf...)","story.map4-ending.004":"Ora, <wait=40>vejam só quem finalmente chegou!","story.map4-ending.005":"...<wait=40>Argh, lá vamos nós de novo.","story.map4-ending.006":"Imagino que já soube da notícia?","story.map4-ending.007":"<rep_handlename> acabou de derrotar<br>Grantos.","story.map4-ending.008":"Seus serviços não foram necessários, afinal.<br>E depois de toda aquela bravata lá atrás...","story.map4-ending.009":"O-Ora, sua...<wait=40><br>Se quer bravata, eu te enfrento aqui mesmo!","story.map4-ending.010":"Pode largar essa pose de valentão.<wait=40><br>Você teve sua chance e desperdiçou.","story.map4-ending.011":"C-Cala a boca!<wait=40><br>Não havia nada de errado com as informações que eu descobri!","story.map4-ending.012":"Aquele gigante maldito deve ter mudado de posição ou algo assim...","story.map4-ending.013":"Isso eu admito: você chegou às mesmas conclusões que eu","story.map4-ending.014":"e conseguiu dar conta de alguns monstros difíceis no caminho até aqui.","story.map4-ending.015":"Mesmo assim, você não conseguiu cumprir sua missão.","story.map4-ending.016":"De que adianta ser bom se você vai falhar quando realmente importa?","story.map4-ending.017":"Grr...<wait=40> Eu vou te mostrar!<br>O que é que você sabe, afinal?!","story.map4-ending.018":"Agora chega! Para mim, acabou!","story.map4-ending.019":"Nunca pedi para bancar a babá de vocês, para começo de conversa, e olha no que deu!","story.map4-ending.020":"Vou voltar para Elgaia!","story.map4-ending.021":"Além disso, preciso entregar meu relatório<br>para aqueles velhos caquéticos do Salão dos Invocadores.","story.map4-ending.022":"......","story.map4-ending.023":"Ei!<wait=40> <rep_handlename>!","story.map4-ending.024":"Não vá se achando o tal só porque teve sorte de derrotar Grantos!","story.map4-ending.025":"Eu teria vencido ele de olhos<br>fechados e com uma mão nas costas!","story.map4-ending.026":"Aliás, você devia era me agradecer!","story.map4-ending.027":"Isso mesmo! <wait=40>Agradecer ao Invocador mais poderoso de todo o Salão dos Invocadores de Akras por cuidar de você!","story.map4-ending.028":"Ahem.<wait=40> O mais poderoso do Salão dos Invocadores não é o Karl, do esquadrão Rebluens?","story.map4-ending.029":"Está querendo levar um olho roxo<br>ou o quê?","story.map4-ending.030":"Pare de falar esse nome!","story.map4-ending.031":"Tenho mais talento no meu dedo mindinho do que aquele farsante no corpo inteiro!","story.map4-ending.032":"Aquele chato só estava no lugar certo na hora certa, só isso!","story.map4-ending.033":"Lá em Randall, dizem que ele derrotou sozinho Sagamur, o Dragão Infernal.","story.map4-ending.034":"Depois disso, dizem que ele foi recrutado pessoalmente para a Guarda Imperial.","story.map4-ending.035":"Ha! Ele?!<wait=40><br>Ele pode ter dado o golpe final,","story.map4-ending.036":"mas foi outro regimento que<br>realmente o deixou de joelhos!","story.map4-ending.037":"E sim,<wait=40> caso você esteja se perguntando,<wait=40>","story.map4-ending.038":"esse outro regimento era o Sky Garden, muito obrigado!","story.map4-ending.039":"Ah, sim, <wait=40>agora me lembro.","story.map4-ending.040":"Algo sobre o líder do Sky Garden ter desmaiado ao ouvir uivos na escuridão...","story.map4-ending.041":"Mas o quê?!","story.map4-ending.042":"N-Não foi isso que aconteceu!","story.map4-ending.043":"Arrisquei minha vida para proteger aqueles fracotes do que quer que estivesse à espreita lá atrás!","story.map4-ending.044":"Foi graças a mim que eles<br>conseguiram sequer lutar!","story.map4-ending.045":"Se eu não estivesse lá, eles não teriam a menor chance de vencer!","story.map4-ending.046":"Hehe. <wait=40>Nesse caso, devo<br>pedir desculpas por duvidar do grande líder do Sky Garden.","story.map4-ending.047":"Pode apostar que deve!","story.map4-ending.048":"Tsc... <wait=40>Viu, é por isso que eu<br>não suporto aquele farsante do Karl.","story.map4-ending.049":"Cadê o respeito dele?<br>Eu sou superior a ele, pelo amor de Deus!","story.map4-ending.050":"Não me importa se é você<br>ou aquela imperial metida e idiota,","story.map4-ending.051":"qualquer um que fique do lado do Karl não passa de uma pedra no meu sapato!","story.map4-ending.052":"Escuta aqui, <rep_handlename>, porque eu só vou falar uma vez!","story.map4-ending.053":"Da próxima vez que você entrar no meu caminho,","story.map4-ending.054":"vou te dar uma surra tão grande que você vai passar uma semana tirando espinhos do traseiro!","story.map4-ending.055":"Se não gosta da ideia, sugiro que comece a me mostrar algum respeito!","story.map4-ending.056":"Eu sou o grande e poderoso Lugina, e não se esqueça disso!","story.map4-ending.057":"Heh...<wait=40> <br>Bem, isso poderia ter sido melhor.","story.map4-ending.058":"Por falar nisso,<wait=40><br>já está na hora de eu seguir meu caminho também.","story.map4-ending.059":"Se você ainda pretende ir atrás dos Quatro Deuses Caídos,<wait=40> talvez nossos caminhos se cruzem de novo algum dia.","story.map4-ending.060":"Estou ansiosa para lutar ao<br>seu lado no futuro.","story.map4-ending.061":"Boa sorte para você,<br>bravo guerreiro.","story.map4-ending.062":"––Entendo.<wait=40><br>Então não estava em Cordelica, afinal...","story.map4-ending.063":"––Eu já suspeitava,<wait=40><br>mas não consigo evitar ficar um pouco decepcionado.","story.map4-ending.064":"––Hum?<wait=40><br>Você não precisa se desculpar por nada.","story.map4-ending.065":"––Se alguém deve pedir<br>desculpas, sou eu, por mandar você atrás de uma pista falsa.","story.map4-ending.066":"––Sim, claro.<wait=40><br>Continue com o bom trabalho.","story.map4-ending.067":"––Lembre-se, conto com você.","story.map4-ending.068":"Hehe...","story.map4-ending.069":"Então, <wait=40>o jovem Invocador<br>conseguiu derrotar Grantos...","story.map4-ending.070":"Bem como eu esperava.","story.map4-ending.071":"Parece que o mundo está mesmo<br>seguindo na direção certa.","story.map4-ending.072":"Agora só falta Paris se apressar<br>e encontrar aquilo que realmente dorme em Grand Gaia.","story.map4-ending.073":"......","story.map4-ending.074":"Você está ouvindo, imagino?","story.map4-ending.075":"O relógio começou a correr.<wait=40><br>Não há mais volta.","story.map4-ending.076":"É melhor seu mestre se preparar<br>para o que está por vir.","story.map4-ending.077":"......","story.map4-ending.078":"...<wait=40>Hehe.","story.map4-ending.079":"<size=20>Muahaha!","story.map4-open.001":"(Toc, <wait=20>toc.)","story.map4-open.002":"Com licença, senhor.","story.map4-open.003":"Segundo nossas fontes no governo,","story.map4-open.004":"o Salão dos Invocadores de Akras assumiu<br>o controle da região sul de Mistral.","story.map4-open.005":"...<wait=40>Sim, <wait=40>foi o que ouvi.","story.map4-open.006":"Eles também estão se tornando uma<br>força e tanto em Grand Gaia.","story.map4-open.007":"Ao que parece...","story.map4-open.008":"Paris,<wait=40><br>quero que você vá para Cordelica.","story.map4-open.009":"Preciso que me mantenha informado<br>de qualquer novidade na fronteira.","story.map4-open.010":"...<wait=40>Claro, senhor.<wait=40><br>...<wait=40>E quanto às minhas funções habituais?","story.map4-open.011":"Eu explicarei a situação ao Imperador.","story.map4-open.012":"Obrigada, senhor.<wait=40><br>Nesse caso, eu me despeço.","story.map4-open.013":"......","story.map4-open.014":"...Ah,<wait=40><br>não tinha visto você aí.","story.map4-open.015":"Você nunca foi de bater à porta, não é?","story.map4-open.016":"......","story.map4-open.017":"O Salão dos Invocadores de Akras <wait=40>e o Governo da Federação de Elgaia...<wait=60><br>A Facção Abel está se movimentando...","story.map4-open.018":"......","story.map4-open.019":"...<wait=40>Hehe.","story.map4-open.020":"<size=20>Muahaha!","story.map4-open.021":"Parece que as coisas estão prestes<br>a ficar interessantes...","story.map5-dungeon1.001":"...<wait=40>Este lugar é bem deprimente. ","story.map5-dungeon1.002":"Parece que a luta chegou até aqui também.","story.map5-dungeon1.003":"Que trágico...","story.map5-dungeon1.004":"Temos que fazer de tudo para que isso não se repita.","story.map5-dungeon1.005":"Nossa, <wait=40><rep_handlename>,<wait=40> que cara confiante é essa!","story.map5-dungeon1.006":"Isso, <wait=40>vamos acabar com aquele Cardes malvado!","story.map5-dungeon1.007":"Hã? <wait=40>Você quer saber quem é Cardes?","story.map5-dungeon1.008":"Ai, desculpa!<wait=40> <br>Eu não te contei sobre ele, né!?","story.map5-dungeon1.009":"Ahem, <wait=40>muito bem, <wait=40>é hora da historinha da Tilith!","story.map5-dungeon1.010":"Este Arquipélago de Palmyna é governado por \\"Cardes, o Malévolo\\", um dos Quatro Deuses Caídos. ","story.map5-dungeon1.011":"Nosso objetivo agora, <rep_handlename>, é derrotá-lo!","story.map5-dungeon1.012":"E você vai ter que ficar de guarda, porque ele é bem mais forte que a Maxwell! ","story.map5-dungeon1.013":"Mas não precisa se preocupar!","story.map5-dungeon1.014":"Na verdade, <wait=20>a maior parte do poder de Cardes está selada no momento.","story.map5-dungeon1.015":"Dizem que ele foi selado durante a grande guerra, nas profundezas de Palmyna, num lugar conhecido como \\"Mundo Espiritual\\"...","story.map5-dungeon1.016":"Devia ter uns humanos bem impressionantes por aqui além de você, <rep_handlename>.","story.map5-dungeon1.017":"Espera,<wait=40> só um segundo...","story.map5-dungeon1.018":"Isso quer dizer que Cardes continuou governando esta terra mesmo depois de ter os poderes selados, né? ","story.map5-dungeon1.019":"Talvez ele seja ainda mais poderoso do que eu imaginava...","story.map5-dungeon1.020":"...<wait=20>...","story.map5-dungeon1.021":"Enfim, <wait=40>temos que derrubá-lo de qualquer jeito!","story.map5-dungeon1.022":"Mas não vai ser problema nenhum pra você, <rep_handlename>!","story.map5-dungeon1.023":"Preciso ir. <wait=20>Tenho que pesquisar mais sobre Cardes!","story.map5-dungeon1.024":"Boa sorte!!","story.map5-dungeon2.001":"<size=14><rep_handlename>!","story.map5-dungeon2.002":"<size=14>Ca-<wait=20>Cadê você?","story.map5-dungeon2.003":"<size=20>Aaaaah!!","story.map5-dungeon2.004":"...N-<wait=40>Não chegue de fininho assim!","story.map5-dungeon2.005":"Hã?<wait=40><br>Do que eu tenho medo?","story.map5-dungeon2.006":"N-<wait=40>Nada!","story.map5-dungeon2.007":"E-<wait=41>Eu não tenho medo de nada!","story.map5-dungeon2.008":"Não tem nada de assustador em navios fantasmas nem nada do tipo!","story.map5-dungeon2.009":"Quer dizer, <wait=40>eu poderia até morar aqui, sabia?","story.map5-dungeon2.010":"Ah!<wait=40> Já entendi!","story.map5-dungeon2.011":"Você só está dizendo isso porque está com medo, <wait=40>não é, <rep_handlename>!?","story.map5-dungeon2.012":"Hehe, <wait=40><rep_handlename> é um medrosinho!","story.map5-dungeon2.013":"Devia ter me falado, <wait=40>eu teria te protegido.","story.map5-dungeon2.014":"Afinal, <wait=20>como deusa eu não sou só bonita, também sou durona!","story.map5-dungeon2.015":"É, <wait=20>isso mesmo!","story.map5-dungeon2.016":"Parece que tem um monstro por aqui que devora almas humanas, então fique de olho!","story.map5-dungeon2.017":"<size=18>*Chuá*","story.map5-dungeon2.018":"<size=20>Hã?<wait=40> O-O que foi isso!","story.map5-dungeon2.019":"V-Você ouviu, <wait=20>aquele barulho estranho agora há pouco!?","story.map5-dungeon2.020":"Hã?<wait=40> Eram só os seus passos?","story.map5-dungeon2.021":"...<wait=40>...<wait=40>...","story.map5-dungeon2.022":"<size=20><rep_handlename>, seu bobo!","story.map5-dungeon2.023":"Eu trouxe uma informação importante pra você, <wait=40>mas agora acho que não quero mais contar!","story.map5-dungeon2.024":"Vou pra casa!","story.map5-dungeon2.025":"Hehe, <wait=40>você acreditou mesmo?","story.map5-dungeon2.026":"Levou um susto?","story.map5-dungeon2.027":"Uma deusa nunca ficaria tão chateada assim. ","story.map5-dungeon2.028":"Enfim, <wait=40>segundo a minha pesquisa, Palmyna, o lugar onde Cardes está selado...","story.map5-dungeon2.029":"...fica depois de Encervis, <wait=40>que fica logo depois de Amdahl.","story.map5-dungeon2.030":"Primeiro temos que passar pelo Castelo de Amdahl, <wait=40>depois podemos atravessar Encervis!","story.map5-dungeon2.031":"Então vamos passar por esta área bem rapidinho, <wait=40>ela me dá muitos arrepios...","story.map5-dungeon2.032":"<size=18>*Chuá* *Chuá*","story.map5-dungeon2.033":"Hã?","story.map5-dungeon2.034":"*Plof* *Plof*","story.map5-dungeon2.035":"<size=20>Aaaah!!","story.map5-dungeon3.001":"<speed=10>Ora, o que temos aqui...<wait=40><br>Este é bem diferente dos outros Invocadores.","story.map5-dungeon3.002":"Está decidido, <wait=20>vou acabar com você aqui.","story.map5-dungeon3.003":"Não precisa se preocupar.<wait=50><br>Logo tudo vai terminar.","story.map5-dungeon3.004":"Esta presença...<wait=20>...","story.map5-dungeon3.005":"Ah, entendi...","story.map5-dungeon3.006":"Aí está você!","story.map5-dungeon3.007":"Ei, <wait=40>aconteceu alguma coisa?<wait=40> Você está com uma cara aflita.","story.map5-dungeon3.008":"Devia estar mais feliz com um tempo bonito desses! Vamos, sorria pra mim!","story.map5-dungeon3.009":"E você também tem a mim aqui, <wait=40>então trate de se animar!","story.map5-dungeon3.010":"Além disso, <wait=40>olha só como este lugar é tranquilo.","story.map5-dungeon3.011":"Eu adoraria passar um tempo relaxando em lugares assim com você, <rep_handlename>.","story.map5-dungeon3.012":"Hehe, <wait=40>brincadeirinha!","story.map5-dungeon3.013":"Você está numa missão importante para derrotar os Quatro Deuses Caídos, <rep_handlename>.","story.map5-dungeon3.014":"Não tem tempo pra ficar à toa!","story.map5-dungeon3.015":"Hã? <wait=40>E eu?","story.map5-dungeon3.016":"Claro que eu também não tenho esse tempo...<wait=40> Ou seja...","story.map5-dungeon3.017":"Por acaso parece pra você<wait=40> que eu só estou de brincadeira aqui!?","story.map5-dungeon3.018":"Que audácia!!","story.map5-dungeon3.019":"Eu estou fazendo tudo o que posso pra te ajudar, <rep_handlename>!","story.map5-dungeon3.020":"Hã? <wait=40>Por exemplo?","story.map5-dungeon3.021":"É-<wait=40>É tanta coisa que nem dá pra explicar...<wait=40> *R<size=15>e<size=14>s<size=13>m<size=12>u<size=11>ngo* <size=12>*R<size=11>e<size=10>s<size=9>m<size=8>u<size=7>n<size=6>go*","story.map5-dungeon3.022":"Enfim, <wait=40>chega de falar de mim!","story.map5-dungeon3.023":"O importante agora é o caminho à frente!","story.map5-dungeon3.024":"Muito bem, <wait=40>vamos seguir para o Castelo de Amdahl!","story.map5-dungeon4.001":"Eca, <wait=20>que horror! <wait=40>Este lugar é nojento!","story.map5-dungeon4.002":"Nem o Graham poria os pés num lugar desses!","story.map5-dungeon4.003":"Eu já te expliquei isso, não expliquei?","story.map5-dungeon4.004":"É bem provável que o Graham esteja em Edila, a cidade fantasma logo depois destas minas.","story.map5-dungeon4.005":"Chega de reclamar! <wait=40> Precisamos continuar avançando!","story.map5-dungeon4.006":"De qualquer forma, <wait=40>parece que só recebemos informação furada do Salão dos Invocadores!","story.map5-dungeon4.007":"Sério, Seria, <wait=40>você é a mulher mais dura que eu conheço...","story.map5-dungeon4.008":"Hum?<wait=40> Ah!<wait=40> <rep_handlename>!","story.map5-dungeon4.009":"Hunf...","story.map5-dungeon4.010":"Então você também veio para o Arquipélago de Palmyna, afinal!","story.map5-dungeon4.011":"Eu achava que, se alguém conseguisse chegar, seria você, <rep_handlename>.","story.map5-dungeon4.012":"Imagino que esteja atrás de Cardes?","story.map5-dungeon4.013":"Haha, <wait=40>tenho a impressão de que ele não é páreo pra você, depois do que fez com a Maxwell. ","story.map5-dungeon4.014":"Hunf! <wait=40>Não fique se achando, <wait=40>senão algo ruim pode te acontecer.","story.map5-dungeon4.015":"Do que você está falando agora? <wait=50> Por que não trata <rep_handlename> com um pouco mais de respeito?<wait=40>","story.map5-dungeon4.016":"*Tóim*","story.map5-dungeon4.017":"<size=18>N-<wait=20>Não foi nada! <wait=40>Sério, eu paro!","story.map5-dungeon4.018":"Enfim, <wait=40>tem um subordinado de Cardes no Arquipélago de Palmyna que é temido até pelas forças mais poderosas...","story.map5-dungeon4.019":"Hesite um pouquinho que seja e você está acabado!","story.map5-dungeon4.020":"Ah, Seria...","story.map5-dungeon4.021":"Mas, na verdade, <wait=40>tem um fundo de verdade no que ela diz. ","story.map5-dungeon4.022":"Na realidade, <wait=40>além do Graham, que estamos perseguindo agora...","story.map5-dungeon4.023":"...Há boatos de uma fera tão poderosa quanto ele, ou até mais, nestas bandas, conhecida como Zebra. ","story.map5-dungeon4.024":"Todo cuidado é pouco, <wait=40>então vamos todos avançar com cautela. ","story.map5-dungeon4.025":"Aliás, <wait=40>o que aconteceu com aquela deusa?","story.map5-dungeon4.026":"Vocês dois viviam grudados feito unha e carne...","story.map5-dungeon4.027":"Ah, já sei!<wait=40> Ela finalmente se cansou de como você é sem graça!?","story.map5-dungeon4.028":"Seria, <wait=40>já chega.","story.map5-dungeon4.029":"...<wait=40>Era só uma brincadeirinha, ora.","story.map5-dungeon4.030":"Estamos indo para Edila, logo adiante, atrás do Graham. ","story.map5-dungeon4.031":"Eu gostaria que lutássemos juntos, como um só, <wait=40>mas com uma companheira chata como você...","story.map5-dungeon4.032":"Eu não estava sendo chata...","story.map5-dungeon4.033":"Haha... <wait=40>Então, pretende seguir adiante sozinho?","story.map5-dungeon4.034":"Há inimigos bem ferozes te esperando mais à frente,<wait=40> mas acredito que vamos sobreviver para nos encontrar de novo!","story.map5-dungeon4.035":"Karl! <wait=40>Não temos tempo pra ficar enrolando, vamos em frente!","story.map5-dungeon4.036":"Faça o possível para não virar presa daqueles demônios!","story.map5-dungeon4.037":"E-<wait=40>Ei, <wait=40>espera aí!","story.map5-dungeon4.038":"Francamente... <wait=40>Bom, <wait=20>até a próxima, <rep_handlename>!","story.map5-dungeon5.001":"Ah, <wait=40>que delícia!","story.map5-dungeon5.002":"Ah, <wait=40><rep_handlename>!","story.map5-dungeon5.003":"Você chegou aqui inteirinho. <wait=40>Eu sabia que você conseguiria!","story.map5-dungeon5.004":"Mesmo acreditando em você, fico aliviada de te ver.","story.map5-dungeon5.005":"Hã? <wait=40>O que eu estava fazendo?","story.map5-dungeon5.006":"Hehe, <wait=40>aproveitando o santuário, ora!","story.map5-dungeon5.007":"Cada cantinho banhado de luz, <wait=20>nada supera um bom santuário.","story.map5-dungeon5.008":"O clima solene e toda essa luz linda são irresistíveis para uma deusa como eu.","story.map5-dungeon5.009":"E não tem nenhum barulho estranho como os que ouvimos no navio fantasma!","story.map5-dungeon5.010":"<size=18>*Farfalha* *Farfalha*","story.map5-dungeon5.011":"O que foi isso!?<wait=40> Quem está aí!?","story.map5-dungeon5.012":"Ho ho ho. <wait=40><br>Eu a assustei?","story.map5-dungeon5.013":"Perdoe-me, <wait=20>mocinha.","story.map5-dungeon5.014":"Não era minha intenção assustá-la, <wait=40>é que você tem uma voz tão agradável. ","story.map5-dungeon5.015":"Ah, <wait=40>h-<wait=40>hum...","story.map5-dungeon5.016":"Quem é você, velhinho?","story.map5-dungeon5.017":"Ho ho ho. <wait=40><br>Peço desculpas por isso.","story.map5-dungeon5.018":"Meu nome é Grah. <wait=40><br>Por favor, chame-me de Elder Grah.","story.map5-dungeon5.019":"Elder Grah, é...","story.map5-dungeon5.020":"Ho ho ho. <wait=40><br>Um belo nome, não acha?","story.map5-dungeon5.021":"Eu lhe disse o meu nome, <wait=40>não vai me dizer o seu?","story.map5-dungeon5.022":"Hum, <wait=40>meu nome é Tilith! <wait=40>Sou uma garota normal, igualzinha a qualquer outra por aí.","story.map5-dungeon5.023":"E esta pessoa adorável aqui é <rep_handlename>!","story.map5-dungeon5.024":"<rep_handlename> é um Invocador incrivelmente forte!","story.map5-dungeon5.025":"Que coragem.","story.map5-dungeon5.026":"Então, Elder Grah, <wait=40>o que o traz a um lugar como este?","story.map5-dungeon5.027":"Bem, <wait=40>eu só ia dar uma caminhada ali adiante.","story.map5-dungeon5.028":"Uma caminhada, é...","story.map5-dungeon5.029":"Achei que esta área estivesse cheia de monstros...","story.map5-dungeon5.030":"Hum, <wait=20>bem, parece que eles não me deram atenção. ","story.map5-dungeon5.031":"Hum...<wait=40> Você ainda me parece meio suspeito...","story.map5-dungeon5.032":"Olha só essas armas poderosas que você carrega...","story.map5-dungeon5.033":"He he he...","story.map5-dungeon5.034":"Parece que fui descoberto!","story.map5-dungeon5.035":"Na verdade, eu sou <wait=20>Grah, o deus que governa esta terra!","story.map5-dungeon5.036":"E agora vou fazer vocês dois desaparecerem dela imediatamente!","story.map5-dungeon5.037":"Mas o quê!?","story.map5-dungeon5.038":"Só estou brincando com vocês.","story.map5-dungeon5.039":"Ho ho ho. <wait=40><br>Assustei vocês?","story.map5-dungeon5.040":"Você fica tão incrivelmente fofa quando se assusta, mocinha.","story.map5-dungeon5.041":"Hunf!","story.map5-dungeon5.042":"Perdoe-me, por favor.","story.map5-dungeon5.043":"Há muito tempo, eu parti numa espécie de aventura. ","story.map5-dungeon5.044":"Usei esta lança naquela época, <wait=40>embora hoje ela sirva só de enfeite.","story.map5-dungeon5.045":"Estou aqui para investigar a lenda dos antigos Quatro Heróis, <wait=40>mas parece improvável que eu encontre algo importante aqui.","story.map5-dungeon5.046":"Muito bem, <wait=40>acho que é hora de me despedir.","story.map5-dungeon5.047":"Tive a chance de conhecer um Invocador tão interessante, <wait=40>então acho que foi um bom dia. ","story.map5-dungeon5.048":"Bem, <wait=40>aguardo ansioso o nosso próximo encontro.","story.map5-dungeon5.049":"Aquele velhinho, <wait=40>ele era meio esquisito, não era?","story.map5-dungeon5.050":"Não é qualquer pessoa normal que consegue passear por aqui.","story.map5-dungeon5.051":"Com certeza ele está escondendo alguma coisa<wait=20>.<wait=20>.<wait=20>.","story.map5-dungeon5.052":"Enfim, <wait=40>não adianta se preocupar com isso agora.","story.map5-dungeon5.053":"Não é como se isso afetasse o nosso objetivo!","story.map5-dungeon5.054":"Certo, <wait=40>vamos passar rapidinho por aqui e depois seguir para o Castelo de Amdahl!","story.map5-dungeon6.001":"Seria!<wait=40> Como estão as coisas aí!?","story.map5-dungeon6.002":"Nada!<wait=40> Não há sinal dele em lugar nenhum...","story.map5-dungeon6.003":"Droga! <wait=40>Ele escapou de nós de novo!","story.map5-dungeon6.004":"Desse jeito, <wait=40>nunca vamos conseguir vingá-los...","story.map5-dungeon6.005":"Karl...","story.map5-dungeon6.006":"<size=18>Hã!?<wait=40> <size=16>De onde você saiu?","story.map5-dungeon6.007":"Ora, se não é <rep_handlename>...","story.map5-dungeon6.008":"Hehe, <wait=40>parece que você nos pegou numa hora ruim.","story.map5-dungeon6.009":"Mais uma vez, <wait=20>o Graham escorregou por entre os nossos dedos.","story.map5-dungeon6.010":"Comparados a você, que lutou com tanta bravura contra os Quatro Deuses Caídos, <wait=20>devemos parecer patéticos...","story.map5-dungeon6.011":"Do que você está falando!","story.map5-dungeon6.012":"<rep_handlename> só tem sorte!<wait=40> Karl, você já derrotou inimigos centenas de vezes mais fortes do que os dele!","story.map5-dungeon6.013":"Haha, <wait=40>muito obrigado, Seria.","story.map5-dungeon6.014":"É realmente especial receber um elogio seu.","story.map5-dungeon6.015":"Acho que não tenho motivo pra ficar desanimado, né!","story.map5-dungeon6.016":"Como assim, \\"especial\\"?","story.map5-dungeon6.017":"Haha, <wait=40>só estou tentando te agradecer, só isso. ","story.map5-dungeon6.018":"Ah, e <rep_handlename>...","story.map5-dungeon6.019":"O motivo de termos perdido o Graham de novo não foi só a força dele...","story.map5-dungeon6.020":"Quando o alcançamos desta vez, <wait=40>havia outro monstro incrivelmente forte com ele.","story.map5-dungeon6.021":"Desculpe ser tão vago.","story.map5-dungeon6.022":"Para falar a verdade, <wait=40>nós nem chegamos a ver o outro monstro.","story.map5-dungeon6.023":"Assim que sentimos aquele poder incrível, <wait=40>fomos literalmente arremessados longe.","story.map5-dungeon6.024":"Quando voltamos a nós, <wait=40>o Graham tinha sumido para algum lugar.","story.map5-dungeon6.025":"Nós o teríamos pegado se não fôssemos atacados daquele jeito...","story.map5-dungeon6.026":"Você provavelmente tem razão...","story.map5-dungeon6.027":"Mas a única coisa de que temos certeza <wait=40>é que nenhuma pessoa normal teria um poder desses...","story.map5-dungeon6.028":"Isso é verdade...","story.map5-dungeon6.029":"Enfim, <wait=40>tivemos a sorte de não sofrer tantas baixas.","story.map5-dungeon6.030":"Vamos continuar procurando o Graham.","story.map5-dungeon6.031":"Você está indo para o Castelo de Amdahl, logo adiante, certo?","story.map5-dungeon6.032":"Também sinto uma presença forte e perigosa vindo de lá.","story.map5-dungeon6.033":"Tome todas as precauções.","story.map5-dungeon6.034":"Se der de cara com aquele monstro, você já era!","story.map5-dungeon6.035":"Haha, <wait=40>dura com <rep_handlename> como sempre, pelo visto.","story.map5-dungeon6.036":"N-<wait=40>Não é só com <rep_handlename> que eu sou dura...","story.map5-dungeon6.037":"Aí está você!","story.map5-dungeon6.038":"Onde você estava? <wait=40>Procurei você por toda parte!","story.map5-dungeon6.039":"Hã?<wait=40> O que é isso?<wait=40><br>Eu já vi vocês antes, não vi?","story.map5-dungeon6.040":"...<wait=20>...","story.map5-dungeon6.041":"Olá, deusa.<wait=40> Há quanto tempo.","story.map5-dungeon6.042":"Faz mesmo um tempão!<wait=40> Você parece em forma como sempre, Karl!","story.map5-dungeon6.043":"E você, <wait=40>andou implicando com o meu <rep_handlename> como sempre faz?","story.map5-dungeon6.044":"<size=18>Como assim, \\"implicando\\"!","story.map5-dungeon6.045":"E como eu já disse, <wait=40><rep_handlename> não é propriedade sua!","story.map5-dungeon6.046":"Por que esse escândalo todo?<wait=40> Será que <wait=20>você está com ciúmes? ","story.map5-dungeon6.047":"...<wait=20>...","story.map5-dungeon6.048":"<size=18>*Clang*","story.map5-dungeon6.049":"<size=18>E-Espera um pouco!","story.map5-dungeon6.050":"Calma, Seria!","story.map5-dungeon6.051":"V-<wait=20>Vamos lá, <wait=40>temos que voltar ao rastro do Graham!","story.map5-dungeon6.052":"C-<wait=40>Certo!?","story.map5-dungeon6.053":"<speed=14>Bom, então, <wait=20><rep_handlename>!","story.map5-dungeon6.054":"<speed=14>Vamos prometer que os dois vão dar tudo de si no caminho à frente!","story.map5-dungeon6.055":"<speed=14>Certo, estamos indo! Você também, Seria!","story.map5-dungeon6.056":"Karl! <wait=20> Espera!<wait=40> Já entendi, <wait=40>não precisa puxar com tanta força!","story.map5-dungeon6.057":"Deusa! <wait=40>É bom você se comportar!","story.map5-dungeon6.058":"Hunf!!","story.map5-dungeon6.059":"Ufa, <wait=40>finalmente ela foi embora.","story.map5-dungeon6.060":"Mesmo assim, <wait=40>espero que eles consigam derrotar o Graham!","story.map5-dungeon6.061":"Estamos quase lá. <wait=40>Passando por aqui, chegamos aos portões do Castelo de Amdahl!","story.map5-dungeon6.062":"Conto com você!","story.map5-dungeon7.001":"Finalmente chegamos.","story.map5-dungeon7.002":"Atravesse o Castelo de Amdahl e o caminho para Encervis fica livre.","story.map5-dungeon7.003":"Aí estaremos um passo mais perto de Cardes e da terra onde ele está selado.","story.map5-dungeon7.004":"Hehe, <wait=40>não fique com essa cara de nervoso.","story.map5-dungeon7.005":"Eu sei que você consegue, <rep_handlename>!","story.map5-dungeon7.006":"Vamos atravessar este castelo depressa!","story.map5-dungeon7.007":"Acha mesmo que vai ser tão fácil assim?","story.map5-dungeon7.008":"O quê-!!","story.map5-dungeon7.009":"Eu a assustei de novo?","story.map5-dungeon7.010":"Que audácia! <wait=40>Não chegue de fininho assim!!","story.map5-dungeon7.011":"Ho ho ho.","story.map5-dungeon7.012":"Você continua tão fofa quanto eu me lembrava, mocinha.","story.map5-dungeon7.013":"Hunf, <wait=40>velho malvado...","story.map5-dungeon7.014":"Ho ho ho.","story.map5-dungeon7.015":"Enfim, <wait=40><rep_handlename>...","story.map5-dungeon7.016":"Você também percebeu, não foi? <wait=40>A presença maligna adiante...","story.map5-dungeon7.017":"Sim, <wait=40>posso ver no seu rosto.","story.map5-dungeon7.018":"Muito bem, <wait=40>deixe-me fazer o favor de lhe dizer o que esperar.","story.map5-dungeon7.019":"Logo adiante, o antigo senhor deste castelo o aguarda.","story.map5-dungeon7.020":"O último imperador do Império de Amdahl, que foi destruído por Palmyna. ","story.map5-dungeon7.021":"Agora um fantasma, ele guarda um grande rancor dos humanos.","story.map5-dungeon7.022":"Um fantasma que guarda rancor dos humanos...","story.map5-dungeon7.023":"Ho ho ho.","story.map5-dungeon7.024":"O que você esperava?","story.map5-dungeon7.025":"Nem tudo o que existe aqui em Grand Gaia tem necessariamente a ver com os deuses.","story.map5-dungeon7.026":"Basta olhar para a história humana para perceber...","story.map5-dungeon7.027":"Os humanos mataram muito mais uns aos outros do que foram destruídos pelos deuses.","story.map5-dungeon7.028":"......","story.map5-dungeon7.029":"Ho ho ho.","story.map5-dungeon7.030":"Enfim, <wait=40>já estou um pouco velho para isso, <wait=40>acho melhor seguir meu caminho.","story.map5-dungeon7.031":"Mas, antes de ir, <wait=40>mesmo sendo uma deusa, ela ainda tem suas fraquezas.","story.map5-dungeon7.032":"É bom fazer o possível para protegê-la.","story.map5-dungeon7.033":"Hã?<wait=40> Espera um pouco!","story.map5-dungeon7.034":"Ho ho ho.","story.map5-dungeon7.035":"Ele sumiu...","story.map5-dungeon7.036":"Quando foi que eu contei ao Elder Grah que era uma deusa?","story.map5-dungeon7.037":"Ele sabe tanta coisa, <wait=40>quem será ele, afinal?","story.map5-dungeon7.038":"Ah, <wait=40>deixa pra lá!","story.map5-dungeon7.039":"Não adianta se preocupar com isso agora! <wait=40>","story.map5-dungeon7.040":"Temos que passar por aqui antes de enfrentar Cardes!","story.map5-dungeon7.041":"Bom, <rep_handlename>, eu não sei o que pensar dessa história de fantasma...","story.map5-dungeon7.042":"...mas, seja o que for, vamos derrubar! <wait=40>Com certeza isso vai surpreender o Elder Grah!","story.map5-ending.001":"Você conseguiu, <rep_handlename>!","story.map5-ending.002":"Aquele cara foi moleza!","story.map5-ending.003":"Nem os fantasmas de imperadores do passado têm chance contra você, <rep_handlename>!","story.map5-ending.004":"<size=18>Uau!","story.map5-ending.005":"O quê-!!","story.map5-ending.006":"Ei, <wait=40>por que você vive tentando me assustar...","story.map5-ending.007":"Desculpe por isso, <wait=40>é que eu sinto o mesmo que você, Tilith...","story.map5-ending.008":"Também fiquei surpreso com o jeito que <rep_handlename> lidou com aquele espectro.","story.map5-ending.009":"Hunf.","story.map5-ending.010":"Ho ho ho.","story.map5-ending.011":"Mas, <wait=40>para <rep_handlename> derrotar o fantasma de um imperador daquele jeito...","story.map5-ending.012":"Hehe, <wait=40>né?","story.map5-ending.013":"Isso quer dizer que <rep_handlename> é mesmo um Invocador incrível, certo?","story.map5-ending.014":"Hum, <wait=40>foi mesmo um magnífico duelo de espadas.","story.map5-ending.015":"Devo dizer, <wait=40>muito bem.","story.map5-ending.016":"<size=18><rep_handlename>!<wait=40> Você ainda está vivo!!","story.map5-ending.017":"Ufa... <wait=40>ufa...","story.map5-ending.018":"E-<wait=40>Espera um segundo...","story.map5-ending.019":"O-<wait=40>O que aconteceu com aquele fantasma?","story.map5-ending.020":"<rep_handlename> acabou com ele!","story.map5-ending.021":"...<wait=40>...","story.map5-ending.022":"<size=14>Hunf...<wait=40><br>Karrrrrrll!!","story.map5-ending.023":"Então você estava preocupada com <rep_handlename>, afinal, não é, Seria!?","story.map5-ending.024":"Parece que você tem um lado carinhoso.","story.map5-ending.025":"N-<wait=40>Não é nada disso!<wait=40> Eu só ouvi dizer que o Graham tinha aparecido por aqui...","story.map5-ending.026":"Ora, <wait=20>não precisa se esconder atrás de uma mentira tão descarada.","story.map5-ending.027":"Grr...","story.map5-ending.028":"Ho ho ho.","story.map5-ending.029":"<size=20>!?","story.map5-ending.030":"Acho que ainda não fomos apresentados.","story.map5-ending.031":"Srta. Seria, <wait=40>por favor, chame-me de Elder Grah.","story.map5-ending.032":"Hã!?<wait=40> E-<wait=40>Elder Grah?","story.map5-ending.033":"Isso mesmo.","story.map5-ending.034":"Hã, <wait=40>mas... <wait=40>q-<wait=40>quer dizer...","story.map5-ending.035":"É Elder Grah.","story.map5-ending.036":"Trate de lembrar, <wait=40>Srta. Seria.","story.map5-ending.037":"Elder Grah, <wait=40>você é mesmo um velhinho estranho, não é!","story.map5-ending.038":"Sempre aparecendo de repente em lugares estranhos, <wait=40>e sabe das coisas mais obscuras.","story.map5-ending.039":"E vive tentando me assustar!","story.map5-ending.040":"O-<wait=40>O-<wait=40>O que você está dizendo!?<wait=40> Este homem é...","story.map5-ending.041":"...o Elder Grah, só um velhinho brincalhão.","story.map5-ending.042":"Não é, <wait=40>Srta. Seria?","story.map5-ending.043":"Hã?<wait=40> A-<wait=40>Ah, <wait=20>é...","story.map5-ending.044":"Ho ho ho.","story.map5-ending.045":"Hunf, <wait=40>tem algo estranho com você, Seria!","story.map5-ending.046":"T-<wait=40>Tanto faz! <wait=40>Só estou com umas coisas na cabeça!","story.map5-ending.047":"Tipo o quê?","story.map5-ending.048":"N-<wait=40>Não tem motivo pra você saber!","story.map5-ending.049":"Hunf, <wait=40>o que deu em você!","story.map5-ending.050":"Será que está chateada porque o Karl te enganou pra vir atrás da gente?","story.map5-ending.051":"H-<wait=40>Hã? <wait=20>Como você sabe disso!?","story.map5-ending.052":"Uma deusa sabe de tudo!","story.map5-ending.053":"E que tipo de deusa é você!?<wait=40> Você não consegue fazer nada sozinha!","story.map5-ending.054":"Que maldade!","story.map5-ending.055":"Ei, <rep_handlename>, <wait=40>me ajuda aqui e fala alguma coisa!","story.map5-ending.056":"Por quê?<wait=40> Você já sabe o que <rep_handlename> diria, né?","story.map5-ending.057":"Ho ho ho.","story.map5-ending.058":"Os jovens são tão cheios de vida.","story.map5-ending.059":"Enfim, <rep_handlename>...","story.map5-ending.060":"Ao derrotar aquele espectro, <wait=40>você rompeu a barreira que cobria esta região.","story.map5-ending.061":"Em breve, o caminho para Encervis vai se abrir.","story.map5-ending.062":"Zebra deve estar à sua espera...","story.map5-ending.063":"...o demônio que agora governa o Arquipélago de Palmyna no lugar de Cardes.","story.map5-ending.064":"Treine bastante e não deixe o orgulho atrapalhar.","story.map5-ending.065":"Ah!<wait=40> Eu ia dizer isso!","story.map5-ending.066":"Tudo o que você diz é besteira, <wait=40>deixe isso com o Grahde...","story.map5-ending.067":"Elder Grah! Deixe isso com o Elder Grah!","story.map5-ending.068":"Besteira, é!?","story.map5-ending.069":"Qual o problema em dizer o que você realmente é?","story.map5-ending.070":"Chega!<wait=40> Vou te mostrar o verdadeiro poder de uma deusa!","story.map5-ending.071":"Pode vir!<wait=50> Vou te mostrar o quanto sou mais forte que você!","story.map5-ending.072":"<size=20>Prepare-se!!","story.map5-ending.073":"Ho ho ho.","story.map5-ending.074":"Vocês são mesmo um par de mocinhas esquentadas, hein.","story.map5-ending.075":"Enfim, <wait=40><rep_handlename>...","story.map5-ending.076":"Devíamos voltar para Elgaia.","story.map5-ending.077":"<rep_handlename>! <wait=40>Espere só um segundo!","story.map5-ending.078":"Tenho um recado do Karl!","story.map5-ending.079":"Ele disse: \\"Eu acredito na sua força.\\"","story.map5-ending.080":"Isso lá é hora pra isso!?","story.map5-ending.081":"<rep_handlename>!","story.map5-ending.082":"Vamos para Encervis depois que eu der uma liçãozinha de respeito na Seria!","story.map5-ending.083":"Se acha que pode me vencer, <wait=40>então tente!","story.map5-ending.084":"Chega!!<wait=40> Agora é hora de mostrar o meu imenso poder mágico!","story.map5-ending.085":"Hunf, <wait=40>parece que está falando sério. <wait=40>OK, <wait=40>vamos nessa!","story.map5-ending.086":"<size=20>Toma essa!!","story.map5-ending.087":"Certo, <wait=40>acho que nós vamos indo...","story.map5-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você, <rep_handlename>,<wait=40> que derrotou Maxwell, Deusa da Criação…","story.map5-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>A crise trazida pelos Quatro Deuses Caídos<wait=40> ainda persiste…","story.map5-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para trazer nova esperança a este mundo tão repleto de tristeza…","story.map5-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você deve ter fé no seu poder <wait=20>e continuar seguindo em frente…","story.map5-open.005":"<size=22>Você está atrasado!","story.map5-open.006":"Por que demorou tanto!?","story.map5-open.007":"Eu estou te esperando há muito, muito tempo, <rep_handlename>!","story.map5-open.008":"Não acha que relaxou um pouquinho demais desde que derrotou a Maxwell?","story.map5-open.009":"<size=20>Hehe, <wait=20>te peguei!!","story.map5-open.010":"Eu estava falando com o Lucius, <wait=40>acabei de chegar também. ","story.map5-open.011":"Enfim, <wait=40>o próximo é o Arquipélago de Palmyna!","story.map5-open.012":"Depois de ver o quanto você é poderoso de verdade em St. Lamia...","story.map5-open.013":"...tenho grandes esperanças em você desta vez!","story.map5-open.014":"Vamos dar tudo de nós！","story.map5-open.015":"*Toc* <wait=20>*Toc*","story.map5-open.016":"Com licença. ","story.map5-open.017":"Tenho novas informações do departamento de inteligência.","story.map5-open.018":"Parece que a barreira que protegia o Arquipélago de Palmyna foi rompida. ","story.map5-open.019":"...<wait=40>Sim, <wait=40>recebi o relatório há pouco tempo. ","story.map5-open.020":"Parece que eles estão ficando cada vez mais ambiciosos. ","story.map5-open.021":"Vou investigar imediatamente.","story.map5-open.022":"Não, <wait=40>continue com suas tarefas atuais. ","story.map5-open.023":"Não posso deixar meu precioso subordinado se envolver no que quer que aquele bando esteja tramando. ","story.map5-open.024":"M-<wait=20>Muito obrigado...<br>Bom, então, <wait=20>vou voltar ao trabalho. ","story.map5-open.025":"Os Quatro Deuses Caídos...","story.map5-open.026":"Dizem que eles têm o poder de destruir toda Grand Gaia. ","story.map5-open.027":"Eu gostaria de ver o quão fortes eles realmente são...","story.map6-dungeon1.001":"Calor, calor, calor!!","story.map6-dungeon1.002":"Por que tudo aqui é tão quente assim?!","story.map6-dungeon1.003":"Uma brisa fresquinha de vez em quando ia bem!","story.map6-dungeon1.004":"Olha só o quanto eu estou suando!","story.map6-dungeon1.005":"Eu já te disse uma vez, <wait=40>mas eu odeio lugares quentes!","story.map6-dungeon1.006":"Lembre disso da próxima vez que escolher onde a gente vai se encontrar, <rep_handlename>!","story.map6-dungeon1.007":"Hmm, <wait=40>mas de qualquer forma, o Lord Lucius está contando muito com você, <rep_handlename>...","story.map6-dungeon1.008":"Acho que eu também vou ter que me esforçar bem mais do que antes...","story.map6-dungeon1.009":"Q-<wait=20>Que cara é essa!?","story.map6-dungeon1.010":"C-<wait=40>Como assim eu nunca pareço me esforçar!?","story.map6-dungeon1.011":"Grr, <wait=40>você é tão malvado.","story.map6-dungeon1.012":"O único motivo de você não ser atacado com mais frequência é que eu estou do seu lado!","story.map6-dungeon1.013":"Ninguém ousaria chegar perto de mim, <wait=40>todo mundo morre de medo do meu poder incrível!","story.map6-dungeon1.014":"Com certeza, até agora tem gente má por aí de olho em você, <rep_handlename>.","story.map6-dungeon1.015":"Hehe, <wait=40>brincadeirinha!","story.map6-dungeon1.016":"Não tem como eu não perceber se alguém assim estivesse mesmo por perto!","story.map6-dungeon1.017":"Você vai encontrar um lago quando sair deste lugar quente demais...","story.map6-dungeon1.018":"Logo depois dele fica um castelo lindo, <wait=40>vamos marcar nosso próximo encontro lá!","story.map6-dungeon1.019":"Tente se manter em segurança até lá.","story.map6-dungeon1.020":"E se você se meter em apuros, sempre pode rezar para a sua linda deusa!","story.map6-dungeon2.001":"<size=18>*Clang*","story.map6-dungeon2.002":"<speed=10>He he he...<wait=40> Nunca pensei que teria de usar meus poderes desse jeito.","story.map6-dungeon2.003":"Parece que você é mesmo perigoso.","story.map6-dungeon2.004":"Seja como for, darei um fim imediato a qualquer um que atrapalhe meus planos.","story.map6-dungeon2.005":"Vou apagar você deste mundo antes que perceba.","story.map6-dungeon2.006":"Acha mesmo que vai ser tão fácil assim?","story.map6-dungeon2.007":"!?","story.map6-dungeon2.008":"Mesmo sendo um deus, <wait=40>ainda pretende se gabar desse jeito diante de um Invocador solitário?","story.map6-dungeon2.009":"Ahh...<wait=40> Vejo que sabe quem eu sou.","story.map6-dungeon2.010":"Parece que topei com mais um fator desconhecido.","story.map6-dungeon2.011":"No entanto, isso não importa. <wait=40>Aconteça o que acontecer agora, o resultado será o mesmo.","story.map6-dungeon2.012":"O que coloquei em movimento acabará trazendo o fim de toda a humanidade.","story.map6-dungeon2.013":"O quê!? <wait=40>Quer dizer que já colocou o Forte Celeste em ação?","story.map6-dungeon2.014":"...<wait=40>Afinal, quem é você?","story.map6-dungeon2.015":"Talvez eu deva simplesmente cuidar de você aqui e agora...","story.map6-dungeon2.016":"Ho ho ho.<wait=40> Devo repetir?","story.map6-dungeon2.017":"Acha mesmo que vai ser tão fácil assim?","story.map6-dungeon2.018":"Este poder...<wait=40>...","story.map6-dungeon2.019":"Entendo. <wait=40>Então você deve ser... ","story.map6-dungeon2.020":"Invocador, <wait=40>você despertou meu interesse.","story.map6-dungeon2.021":"E parece que tem uns bons deuses do seu lado. ","story.map6-dungeon2.022":"Vou observar seus passos por mais um tempo...","story.map6-dungeon2.023":"Ho ho ho.<wait=40> Parece que escapamos dessa.","story.map6-dungeon2.024":"Porém, <wait=40>a situação ainda é grave. ","story.map6-dungeon2.025":"Aquele era Zebra, <wait=20>servo de Cardes, o Malévolo, <wait=40>um dos Quatro Deuses Caídos.","story.map6-dungeon2.026":"Parece que ele de algum jeito conseguiu ressuscitar o lendário Forte Celeste do Império de Amdahl.","story.map6-dungeon2.027":"Este mundo não precisa de uma coisa dessas.","story.map6-dungeon2.028":"Trazer algo assim de volta só pode levar a mais combates.","story.map6-dungeon2.029":"Você está planejando ir para Palmyna, não está?","story.map6-dungeon2.030":"Já que vai atrás de Zebra, <wait=40>por que não derruba o Forte Celeste também?","story.map6-dungeon2.031":"Ho ho ho.","story.map6-dungeon2.032":"O que foi?<wait=40> Não há com o que se preocupar.","story.map6-dungeon2.033":"Você tem a mocinha com você, não tem?","story.map6-dungeon2.034":"Enquanto tiver a proteção da deusa, <wait=40>vai ficar tudo bem.","story.map6-dungeon2.035":"Só peço que dê ouvidos ao que ela diz!","story.map6-dungeon2.036":"Hmph<wait=40>...","story.map6-dungeon2.037":"Na verdade,<wait=40> no caso de vocês dois, já não está claro quem está salvando quem.","story.map6-dungeon2.038":"Ho ho ho.","story.map6-dungeon2.039":"Preciso ir.<wait=40> Mande lembranças à mocinha.","story.map6-dungeon3.001":"Ei, <wait=40><rep_handlename>!","story.map6-dungeon3.002":"Eu estava te esperando.","story.map6-dungeon3.003":"Hã? <wait=40>O que aconteceu?<wait=40> Por que essa cara tão séria?","story.map6-dungeon3.004":"O que você disse!?<wait=40> O Zebra ressuscitou o Forte Celeste!?","story.map6-dungeon3.005":"Como ele pôde...","story.map6-dungeon3.006":"Mas peraí, <wait=40>o que é um Forte Celeste? É importante?","story.map6-dungeon3.007":"Q-<wait=20>Que cara é essa!? <wait=40>Tem coisas que nem as deusas sabem!","story.map6-dungeon3.008":"Ho ho ho.","story.map6-dungeon3.009":"Certamente, armas humanas assim seriam consideradas banais para uma deusa.","story.map6-dungeon3.010":"Ah, <wait=40>Elder Grah.","story.map6-dungeon3.011":"Hã? <wait=40>Não vai tentar me assustar desta vez?","story.map6-dungeon3.012":"Ah, <wait=40>perdão por isso.","story.map6-dungeon3.013":"Parece que traí as expectativas da mocinha.","story.map6-dungeon3.014":"Pois bem, <wait=40>permita-me recomeçar do início.","story.map6-dungeon3.015":"Não precisa!","story.map6-dungeon3.016":"Ho ho ho.","story.map6-dungeon3.017":"A propósito, <wait=40>tenho algo a contar. Se importariam de ouvir o que tenho a dizer?","story.map6-dungeon3.018":"Esta é a história do lendário \\"Forte Celeste\\" do Império de Amdahl.","story.map6-dungeon3.019":"É disso que <rep_handlename> estava falando, <wait=40>a coisa que o Zebra ressuscitou, né?","story.map6-dungeon3.020":"Sim, <wait=40>exatamente.","story.map6-dungeon3.021":"Os humanos também tentaram ressuscitá-lo uma vez, no passado.","story.map6-dungeon3.022":"Não se sabe quem o construiu, quando foi construído, nem mesmo como...","story.map6-dungeon3.023":"Parece que tudo o que restou no Império de Amdahl foram instruções de uso e uma explicação de suas capacidades.","story.map6-dungeon3.024":"Por muito tempo, a família imperial o considerou proibido... ","story.map6-dungeon3.025":"...mas então um imperador decidiu ir contra isso.","story.map6-dungeon3.026":"Mantido selado pelo Império de Amdahl, geração após geração...","story.map6-dungeon3.027":"...o último imperador do Império de Amdahl, Myzelion IV, quebrou o selo...","story.map6-dungeon3.028":"...e usou o poder do Forte Celeste para atacar as nações vizinhas, tentando tomar o controle delas. ","story.map6-dungeon3.029":"Em meio a tudo isso, <wait=20>o rei de Palmyna soube dos planos do imperador.","story.map6-dungeon3.030":"Ele implorou a Myzelion IV, mas o imperador foi teimoso e se recusou a ceder. ","story.map6-dungeon3.031":"No fim, <wait=20>o rei de Palmyna usou seu poderio para subjugar Amdahl...","story.map6-dungeon3.032":"...esmagando-os antes que tivessem a chance de ressuscitar o Forte Celeste. ","story.map6-dungeon3.033":"Hum, <wait=40>então basicamente...","story.map6-dungeon3.034":"O Forte Celeste é tão perigoso que vale destruir uma nação inteira para impedir que ele seja ressuscitado?","story.map6-dungeon3.035":"Sim, <wait=40>é exatamente isso.","story.map6-dungeon3.036":"Não pode ser!?<wait=40> E foi isso que o Zebra trouxe de volta!?","story.map6-dungeon3.037":"Exatamente.","story.map6-dungeon3.038":"Então estamos em apuros!!","story.map6-dungeon3.039":"Mesmo assim, <wait=40>isso não tem nada a ver com o nosso objetivo!","story.map6-dungeon3.040":"<rep_handlename>!<wait=40> Vamos continuar atrás do Cardes!","story.map6-dungeon3.041":"E você, Elder Grah, <wait=40>pode ir lá e destruir o Forte Celeste!","story.map6-dungeon3.042":"Hã!?<wait=40> Mocinha, com certeza isso seria impossível.","story.map6-dungeon3.043":"Não deveria ser você a encarar esse desafio?","story.map6-dungeon3.044":"Ehhh, <wait=40>mas eu ia me encrencar se a gente saísse do nosso caminho...","story.map6-dungeon3.045":"Não se preocupe!","story.map6-dungeon3.046":"O Forte Celeste fica no caminho para Palmyna, <wait=40>é só seguir em frente!","story.map6-dungeon3.047":"Então, poderia cuidar disso para mim?<wait=40> Considere o pedido de um velho perto do fim da vida.","story.map6-dungeon3.048":"Ei, <wait=40><rep_handlename>!","story.map6-dungeon3.049":"Poderia me ajudar nisso?","story.map6-dungeon3.050":"Tá bom, <wait=40>acho que não tenho escolha.","story.map6-dungeon3.051":"Se você vai fazer tanto drama, a gente pode tentar...","story.map6-dungeon3.052":"...mas você ainda vai ajudar a gente, né, Elder Grah?","story.map6-dungeon3.053":"Ho ho ho,<wait=40> tem certeza de que quer que eu vá junto?","story.map6-dungeon3.054":"Hehe, <wait=40>claro!","story.map6-dungeon3.055":"Além disso, a única que pode pedir alguma coisa para <rep_handlename> sou eu!","story.map6-dungeon3.056":"Ahh, <wait=40>entendo.","story.map6-dungeon3.057":"Ho ho ho. <wait=40>Peço desculpas por qualquer descortesia da minha parte.","story.map6-dungeon3.058":"Farei o meu melhor, velho como sou.","story.map6-dungeon3.059":"Até logo, <rep_handlename>!<wait=40> Espero te ver no Forte Celeste!","story.map6-dungeon3.060":"Hmm, <wait=40>acho que o Elder Grah é bem mais forte do que deixa transparecer. <wait=20>O que você acha?","story.map6-dungeon3.061":"Ah, <wait=40>mas isso não tem nada a ver com a gente!","story.map6-dungeon3.062":"Muito bem!<wait=40> Vamos rumo ao Forte Celeste!","story.map6-dungeon4.001":"......<wait=40>Seus métodos são indiretos como sempre.","story.map6-dungeon4.002":"Este é o território de Cardes.<wait=40> Eu me movo como bem entender.","story.map6-dungeon4.003":"Heh, <wait=40>por mim, tudo bem. <wait=40>Gostaria de ver do que você é realmente capaz, Zebra.","story.map6-dungeon4.004":"Que azar o daquele Invocador e sua comitiva...","story.map6-dungeon4.005":"Mal sabem eles que o deus em sua mira já sepultou dezenas de milhares de humanos.","story.map6-dungeon4.006":"...<wait=40>...<wait=40>Esta presença.","story.map6-dungeon4.007":"Parece que eles chegaram.","story.map6-dungeon4.008":"Hmph...","story.map6-dungeon4.009":"Parece que você também não tem sorte.","story.map6-dungeon4.010":"Vou defender a sua honra<wait=40> e garantir que eles saiam daqui.","story.map6-dungeon4.011":"Vamos, <rep_handlename>!<wait=40> Anda logo!","story.map6-dungeon4.012":"Hã? <wait=40>Para onde foi?","story.map6-dungeon4.013":"Não tem dúvida de que aquela presença sinistra vinha daqui...","story.map6-dungeon4.014":"<rep_handlename>!<wait=40> É tudo culpa sua por ter vindo se arrastando o caminho todo.","story.map6-dungeon4.015":"Enfim, não parece estranho aqui?<wait=40> Já não sinto mais ninguém...","story.map6-dungeon4.016":"Tenho certeza de que senti a presença de um deus antes...","story.map6-dungeon4.017":"Será que foi só impressão minha?","story.map6-dungeon4.018":"Hmm, <wait=40>bom, de qualquer forma, a gente tem que seguir rumo ao Forte Celeste!","story.map6-dungeon4.019":"Vamos para a Ravina de Gadillian!","story.map6-dungeon5.001":"<size=18>Ei!<wait=40> <rep_handlename>!","story.map6-dungeon5.002":"Ufa, ufa, ufa.<wait=40> Finalmente te achei...","story.map6-dungeon5.003":"Seria!<wait=40> Aqui!","story.map6-dungeon5.004":"Ufa, ufa, ufa, ufa.<wait=40> Quem diria que você chegaria tão longe...","story.map6-dungeon5.005":"Seu tonto!<wait=40> Da próxima vez, fique num lugar mais fácil de achar!","story.map6-dungeon5.006":"Isso com certeza é impossível...","story.map6-dungeon5.007":"Ufa. <wait=40>Mas, sinceramente, procuramos você por toda parte.","story.map6-dungeon5.008":"Achamos que você ainda estaria em algum lugar perto do Castelo Avenia...","story.map6-dungeon5.009":"...mas parece que você também chegou a Encervis.","story.map6-dungeon5.010":"Você é um estorvo.","story.map6-dungeon5.011":"Por que os Caçadores de Demônios têm que procurar um idiota como você?","story.map6-dungeon5.012":"Nós, do Salão dos Invocadores, devíamos cuidar dos assuntos do Salão dos Invocadores.","story.map6-dungeon5.013":"Pedirem de repente para darmos apoio a <rep_handlename>... no que eles estão pensando?","story.map6-dungeon5.014":"Chega disso.","story.map6-dungeon5.015":"Não podemos fazer nada quanto à situação em que acabamos.","story.map6-dungeon5.016":"Deter o Forte Celeste tem prioridade sobre lidar com o Graham. <wait=20>Até você sabe disso, não é, Seria?","story.map6-dungeon5.017":"Eu sei, eu sei!","story.map6-dungeon5.018":"Só odeio que <rep_handlename> esteja envolvido nesse plano!","story.map6-dungeon5.019":"Haha, <wait=40>essa é a Seria de sempre.","story.map6-dungeon5.020":"Mas vou repetir: <wait=40>viemos aqui para deter o Zebra. ","story.map6-dungeon5.021":"Não podemos deixar que ele use o Forte Celeste para atacar Elgaia.","story.map6-dungeon5.022":"Sei que tem sido uma luta difícil até aqui, <wait=40>mas daqui em diante vamos ter que nos esforçar um pouco mais!","story.map6-dungeon5.023":"...O que foi?","story.map6-dungeon5.024":"Hã? <wait=40>Você diz que não ficou sabendo disso? <wait=50>Está falando sério??","story.map6-dungeon5.025":"*Suspiro* <wait=40>Que vergonha...","story.map6-dungeon5.026":"Devo estar parecendo uma boba, toda empolgada sozinha!","story.map6-dungeon5.027":"Parece que alguém no Salão dos Invocadores pisou feio na bola!","story.map6-dungeon5.028":"Que lamentável. <wait=40>Era para estarmos em estado de alerta máximo.","story.map6-dungeon5.029":"Imaginei que você teria recebido as mesmas informações que nós...","story.map6-dungeon5.030":"Talvez ele só tenha recebido informações erradas?","story.map6-dungeon5.031":"Isso não é nada típico do Salão dos Invocadores.","story.map6-dungeon5.032":"Você deve ter razão...","story.map6-dungeon5.033":"Enfim, <wait=40>parece que eu mesma vou ter que te contar.","story.map6-dungeon5.034":"Você está perseguindo o Zebra, aquele que ressuscitou o Forte Celeste, <wait=40>estou certa?","story.map6-dungeon5.035":"Muito bem, <wait=40>pelo menos isso você sabe.","story.map6-dungeon5.036":"Quanto ao Forte Celeste, <wait=40>é mesmo uma coisa maligna. ","story.map6-dungeon5.037":"Se ele ficar totalmente operacional...","story.map6-dungeon5.038":"...<wait=40>o Zebra poderia usá-lo para atravessar o Portal de Lucius e atacar Elgaia.","story.map6-dungeon5.039":"Por isso, até os superiores do Salão dos Invocadores reconheceram que estamos em estado de emergência...","story.map6-dungeon5.040":"E pediram ajuda a todo e qualquer Invocador perto do Forte Celeste...","story.map6-dungeon5.041":"Isso inclui você, <rep_handlename>.","story.map6-dungeon5.042":"Embora nós, Caçadores de Demônios, pudéssemos dar conta de tudo isso sozinhos...","story.map6-dungeon5.043":"...desde que você derrotou Maxwell, o Karl insiste que eu também reconheça as suas habilidades...","story.map6-dungeon5.044":"Desta vez vamos te ajudar, <wait=40>então é bom ficar agradecido!","story.map6-dungeon5.045":"Ha ha ha.","story.map6-dungeon5.046":"Dito isso, <wait=40>basta você continuar atrás do Forte Celeste como vinha fazendo. ","story.map6-dungeon5.047":"Vamos ajudar no seu avanço cuidando de qualquer obstáculo que aparecer. ","story.map6-dungeon5.048":"Sinceramente, <wait=40>a gente está saindo no prejuízo aqui.","story.map6-dungeon5.049":"É bom você retribuir o favor depois!","story.map6-dungeon5.050":"Segundo informações do Salão dos Invocadores de Akras...","story.map6-dungeon5.051":"...parece que podemos chegar ao Forte Celeste depois de atravessar a Terra dos Mortos logo adiante. ","story.map6-dungeon5.052":"Vamos abrir o caminho para você.","story.map6-dungeon5.053":"Você só continue avançando, de olho no Forte Celeste!","story.map6-dungeon5.054":"Vamos lá, Seria!","story.map6-dungeon5.055":"Ei, <wait=40>Karl, <wait=20>me espera!","story.map6-dungeon5.056":"<rep_handlename>!","story.map6-dungeon5.057":"Trate de fazer aquela deusa ajudar também! <wait=40>Entendeu?","story.map6-dungeon5.058":"Sério, <wait=40>por que eu ainda me preocupo com um pirralho como você...","story.map6-dungeon6.001":"Ah! <wait=40>Aí está você!","story.map6-dungeon6.002":"<rep_handlename>!<wait=40> Aqui!","story.map6-dungeon6.003":"Este lugar me dá arrepios...","story.map6-dungeon6.004":"Por que os lugares que os Quatro Deuses Caídos governam são tão assustadores...","story.map6-dungeon6.005":"Você precisa trazer luz para estas regiões, <rep_handlename>!","story.map6-dungeon6.006":"Ah, <wait=40>hoje eu tenho uma informação especial para você!","story.map6-dungeon6.007":"Deixa eu te contar como vamos chegar ao Forte Celeste. ","story.map6-dungeon6.008":"Preste bastante atenção enquanto sua linda deusinha explica!","story.map6-dungeon6.009":"Primeiro, <wait=40>o nome verdadeiro do Forte Celeste é Solaris. ","story.map6-dungeon6.010":"Não consegui descobrir há quanto tempo ele está por aqui...","story.map6-dungeon6.011":"...mas parece que dá para encontrá-lo flutuando no céu logo depois da Terra dos Mortos.","story.map6-dungeon6.012":"Haha, <wait=40>eu sabia que você ia ficar surpreso. ","story.map6-dungeon6.013":"Você deve estar pensando: \\"Como vamos subir até o céu?\\", acertei?","story.map6-dungeon6.014":"Deixa isso com a deusa!","story.map6-dungeon6.015":"Quando você passar daqui e chegar perto do Forte Celeste...","story.map6-dungeon6.016":"Eu te mando lá para cima com meus poderes especiais!","story.map6-dungeon6.017":"Hehe, <wait=40>o que você faria sem mim?","story.map6-dungeon6.018":"Pode me agradecer o quanto quiser!","story.map6-dungeon6.019":"Mas não vá se descuidar!","story.map6-dungeon6.020":"Parece que mais adiante tem uma garota superassustadora que simplesmente adora um bom massacre...","story.map6-dungeon6.021":"Vou na frente para o Forte Celeste, <rep_handlename>, <wait=40>então não demore muito!","story.map6-dungeon6.022":"E-<wait=40>E não pense que eu vou na frente só porque estou com medo, entendeu!?","story.map6-dungeon7.001":"Chegamos!","story.map6-dungeon7.002":"Parece que eu te coloquei bem no meio do Forte Celeste!","story.map6-dungeon7.003":"Eu sou incrível, não sou?","story.map6-dungeon7.004":"Ai... <wait=40>Onde estamos, afinal?","story.map6-dungeon7.005":"Estou <wait=40>tonta...","story.map6-dungeon7.006":"A gente estava agora mesmo enfrentando demônios na Terra dos Mortos, não estava?","story.map6-dungeon7.007":"Ah! <wait=40>Karl!","story.map6-dungeon7.008":"E a sua amiguinha Seria!","story.map6-dungeon7.009":"Como assim, \\"amiguinha\\"!?","story.map6-dungeon7.010":"Ora, se não é <rep_handlename>!","story.map6-dungeon7.011":"Mas se você está aqui, <wait=40>isso quer dizer que...","story.map6-dungeon7.012":"Estamos dentro do Forte Celeste!","story.map6-dungeon7.013":"...<wait=40>Ao que parece.","story.map6-dungeon7.014":"<size=18>Você é burra ou o quê!?","story.map6-dungeon7.015":"É totalmente culpa sua a gente estar aqui em cima, não é!?","story.map6-dungeon7.016":"Não vê que todos ainda estão lutando lá embaixo?","story.map6-dungeon7.017":"Você devia parar um pouco para entender a situação antes de agir, deusa!","story.map6-dungeon7.018":"D-<wait=40>Do que você está falando? <wait=40>Eu não fiz nada de errado...","story.map6-dungeon7.019":"Você deve se achar muito para dizer uma coisa dessas!","story.map6-dungeon7.020":"Podemos deixar isso para lá? Temos problemas bem mais importantes, não temos?","story.map6-dungeon7.021":"Além disso, agora vai ser mais fácil darmos apoio a <rep_handlename>.","story.map6-dungeon7.022":"E, além do mais, <wait=40>não é como se a ausência de nós dois fosse fazer diferença para quem ainda luta lá embaixo.","story.map6-dungeon7.023":"Você deve ter razão, mas...","story.map6-dungeon7.024":"De qualquer forma, <wait=40>você continua uma deusa incrível como sempre.","story.map6-dungeon7.025":"Você deixou as coisas um pouquinho mais fáceis, mesmo na situação perigosa em que estamos. ","story.map6-dungeon7.026":"Se alguém podia se dedicar e conseguir isso, <wait=40>eu sabia que tinha de ser você.","story.map6-dungeon7.027":"Você entendeu tudo errado, Karl!<wait=40> Você confia demais!","story.map6-dungeon7.028":"Haha...","story.map6-dungeon7.029":"<size=18>!?<wait=40> Quem está aí!?","story.map6-dungeon7.030":"<speed=10>Ah...","story.map6-dungeon7.031":"<speed=10>Parece que até vocês, humanos, conseguem sentir minha presença.","story.map6-dungeon7.032":"Zebra!!","story.map6-dungeon7.033":"É o Zebra, o deus louco... <wait=40>Cuidado, ele é tão perigoso quanto parece...","story.map6-dungeon7.034":"Você vai pagar pelo que fez em Edila!","story.map6-dungeon7.035":"É bom estar preparado!","story.map6-dungeon7.036":"Não tenho uso para vocês, vermes patéticos.","story.map6-dungeon7.037":"Quem eu quero <wait=40>é Tilith, a discípula de Lucius.","story.map6-dungeon7.038":"<size=18>Aí está você!","story.map6-dungeon7.039":"<size=18>*Pof*","story.map6-dungeon7.040":"Kyaahh!!","story.map6-dungeon7.041":"Você parece exausta.<wait=40> Era de se esperar, depois de usar tanto poder para trazê-los até aqui.","story.map6-dungeon7.042":"Você se esforçou bastante por esses vermes patéticos.","story.map6-dungeon7.043":"Se é uma batalha entre deuses que você quer, tenho certeza de que Lucius iria te impedir...","story.map6-dungeon7.044":"...mas se está pensando em nos atacar agora, não vou pegar leve com você!","story.map6-dungeon7.045":"<size=18>Todos vocês, para trás!","story.map6-dungeon7.046":"Que poder é este...<wait=40> Ugh...<wait=40>Não consigo me mexer...","story.map6-dungeon7.047":"Gyah...<wait=40> Como você ainda tem tanto poder depois de tudo aquilo...<wait=40> Será que...","story.map6-dungeon7.048":"Ufa... ufa... ","story.map6-dungeon7.049":"Posso estar um pouco fraca agora...<wait=40> mas não tem como eu perder para você...","story.map6-dungeon7.050":"<size=18>Não pense que pode brincar comigo! <wait=40>Você não passa do cãozinho do Lucius!!","story.map6-dungeon7.051":"<size=18>Kyaaahh!!","story.map6-dungeon7.052":"<size=20>Tilith!!","story.map6-dungeon7.053":"Nngh... <wait=40>Ela resistiu mais do que eu esperava...","story.map6-dungeon7.054":"Mas isso já não importa. <wait=40>Removi com sucesso o que estava no meu caminho. ","story.map6-dungeon7.055":"Não resta nenhum deus para defendê-los.","story.map6-dungeon7.056":"Vocês servirão de bom treino para os meus subordinados. ","story.map6-dungeon7.057":"Acha que vamos simplesmente deixar você escapar?","story.map6-dungeon7.058":"Suas intenções não me importam.","story.map6-dungeon7.059":"Vermes patéticos como vocês não conseguem dar sequer um passo na minha presença.","story.map6-dungeon7.060":"Estou usando este Forte Celeste com o único propósito de libertar o Lord Cardes de suas amarras.","story.map6-dungeon7.061":"Se estão mesmo determinados a me enfrentar, <wait=40>vão me encontrar esperando nas profundezas. ","story.map6-dungeon7.062":"Vou incutir em todos vocês o temor aos deuses!","story.map6-dungeon7.063":"<size=18>Espere aí!!","story.map6-dungeon7.064":"Droga! <wait=40>Ele fugiu!","story.map6-dungeon7.065":"<size=18>Karl!!","story.map6-dungeon7.066":"<size=18>Mas o quê!?<wait=40> De onde saíram todos esses monstros!?","story.map6-dungeon7.067":"N-<wait=40>Nngh...","story.map6-dungeon7.068":"D-<wait=40>Desculpa...<wait=40> <rep_handlename>...","story.map6-dungeon7.069":"Pare de falar!<wait=40> Você precisa poupar suas forças!","story.map6-dungeon7.070":"Karl, <wait=40>você sabe o que temos que fazer!","story.map6-dungeon7.071":"Sim! <wait=40><rep_handlename>!","story.map6-dungeon7.072":"Vá atrás do Zebra. <wait=20>A Seria e eu cuidamos das coisas aqui!","story.map6-dungeon7.073":"Não faço ideia de como ele pretende usar este forte...","story.map6-dungeon7.074":"...mas se ele conseguir libertar o Cardes, estaremos em apuros!","story.map6-dungeon7.075":"Não fique aí parado, <wait=40>ande logo!","story.map6-dungeon7.076":"Acha que monstros como estes são um desafio para nós?","story.map6-dungeon7.077":"Como ousa duvidar do líder dos Caçadores de Demônios!","story.map6-dungeon7.078":"Se tem tempo para preocupações inúteis, <wait=40>pare de enrolar e vá atrás dele!","story.map6-dungeon7.079":"Além do mais, <wait=40>logo você, mais que ninguém, sabe que essa deusa ainda tem garra, não sabe?","story.map6-dungeon7.080":"Isso mesmo, Seria.","story.map6-dungeon7.081":"Estes monstros não são ameaça para nós.","story.map6-dungeon7.082":"E não tema pela deusa, ela agora está sob a nossa proteção.","story.map6-dungeon7.083":"Então vá agora <wait=40>e derrote aquele vil Zebra!","story.map6-dungeon7.084":"Contamos com você, <rep_handlename>!","story.map6-dungeon7.085":"Mostre que tipo de Invocador você realmente é!","story.map6-dungeon7.086":"Seria!!","story.map6-dungeon7.087":"Certo!","story.map6-dungeon7.088":"<speed=20><size=20>Lá vamos nós!!","story.map6-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_clear.002":"Você conseguiu, <rep_handlename>!","story.map6-dungeon_ex_clear.003":"Você derrotou a criatura antes mesmo de os nossos oficiais de logística chegarem.","story.map6-dungeon_ex_clear.004":"Eu sabia que você conseguiria, senhor!","story.map6-dungeon_ex_clear.005":"Ah, <wait=20>mas parece que eles ainda vão até essas ruínas.","story.map6-dungeon_ex_clear.006":"Parece que essas ruínas originalmente abrigavam algo enorme.","story.map6-dungeon_ex_clear.007":"Tem cara de estaleiro ou algo assim, mas acho que essa era a única opção.","story.map6-dungeon_ex_clear.008":"Hmm? <wait=40>Notou alguma coisa desde que entrou, senhor?","story.map6-dungeon_ex_clear.009":"A propósito, parece que há registros indicando que Valmodora também apareceu durante a batalha com os deuses.","story.map6-dungeon_ex_clear.010":"Parece que, mesmo naquela época, ele habitava ruínas em algum lugar.","story.map6-dungeon_ex_clear.011":"Porém, também dizem que ele foi exterminado por um certo guerreiro.","story.map6-dungeon_ex_clear.012":"Tenho certeza de que você também vai entrar para a história pelo que acabou de fazer.","story.map6-dungeon_ex_clear.013":"Mas, mesmo assim, <wait=20>tente não ser tão imprudente no futuro!","story.map6-dungeon_ex_clear.014":"Mas, de qualquer forma, você vai acabar indo não importa o que eu diga, né?","story.map6-dungeon_ex_clear.015":"Eu me preocupo muito com você, sabia?","story.map6-dungeon_ex_clear.016":"......","story.map6-dungeon_ex_clear.017":"Hehe, <wait=20>fazia tempo que eu não via essa sua cara de preocupado.","story.map6-dungeon_ex_clear.018":"Enfim, por favor, continue sua investigação em outras áreas!","story.map6-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_open.002":"Está me ouvindo, <wait=40>senhor?","story.map6-dungeon_ex_open.003":"<size=20><rep_handlename>!</size>","story.map6-dungeon_ex_open.004":"Está me ouvindo?","story.map6-dungeon_ex_open.005":"Lin Merylham, do Suporte Logístico...","story.map6-dungeon_ex_open.006":"...do Departamento de Investigação do Escritório de Pesquisa de Grand Gaia, ao seu dispor.","story.map6-dungeon_ex_open.007":"Estou entrando em contato hoje com novas informações.","story.map6-dungeon_ex_open.008":"O Salão dos Invocadores fez uma descoberta assustadora nas ruínas antigas de Encervis.","story.map6-dungeon_ex_open.009":"Parece que uma criatura incrivelmente perigosa fez delas o seu lar.","story.map6-dungeon_ex_open.010":"Por enquanto, <wait=20>as coisas parecem calmas.","story.map6-dungeon_ex_open.011":"Porém, ela parece estar acumulando força das ruínas ao redor para expandir seu território.","story.map6-dungeon_ex_open.012":"Vamos enviar nossos oficiais de logística para lá mais uma vez, então, até lá, por favor, mantenha distância!","story.map6-dungeon_ex_open.013":"......","story.map6-dungeon_ex_open.014":"O-<wait=20>O que foi, senhor? <wait=40>Você já está lá?","story.map6-dungeon_ex_open.015":"Hmph, <wait=40>senhor, você é imprudente demais!","story.map6-dungeon_ex_open.016":"Mas, de qualquer forma, você vai acabar indo não importa o que eu diga, né?","story.map6-dungeon_ex_open.017":"Entendido!","story.map6-dungeon_ex_open.018":"Não vou tentar te impedir!","story.map6-dungeon_ex_open.019":"O monstro que te espera lá dentro é conhecido como Valmodora.","story.map6-dungeon_ex_open.020":"Parece ser um monstro bem grande, então, por favor, tome cuidado redobrado.","story.map6-dungeon_ex_open.021":"Eu sempre me preocupo tanto com você, <wait=20>sabia...","story.map6-ending.001":"<speed=10>S-<wait=40>Seu tolo...","story.map6-ending.002":"<speed=10>T-<wait=40>Típico de um humano...","story.map6-ending.003":"Gyah!<wait=40> <speed=10>Como discípulo...<wait=40> do Lord Cardes...","story.map6-ending.004":"<speed=10>E-<wait=40>Eu n-não posso ser..<wait=40> derrotado...<wait=40> tão facilmente...","story.map6-ending.005":"<speed=10>Nngh...<wait=40> Não tenho escolha...","story.map6-ending.006":"<speed=10>Vou derrubar o Forte Celeste, <wait=40>e vou levar todos vocês comigo!!","story.map6-ending.007":"<size=18>*Clang*","story.map6-ending.008":"<size=18>S-<wait=40>Seeeeeu!!","story.map6-ending.009":"Até um deus deve saber a hora de parar.","story.map6-ending.010":"Não saber disso faz de você pouco mais que um demônio de segunda categoria, eu diria.","story.map6-ending.011":"Deveria tirar um tempo para refletir sobre isso. ","story.map6-ending.012":"<size=18>Gwaaaahhh!!","story.map6-ending.013":"Hmm!?","story.map6-ending.014":"Por que essa cara de surpresa?","story.map6-ending.015":"Não importa, <wait=40>apresse-se e chame a mocinha.","story.map6-ending.016":"Sem o Zebra, <wait=40>é provável que o Forte Celeste volte a ser lacrado.","story.map6-ending.017":"Hmm!? <wait=40>Esta luz...","story.map6-ending.018":"<speed=10>Será que... <wait=40>vem do Lago Aldela?","story.map6-ending.019":"<size=18><rep_handlename>!!","story.map6-ending.020":"Aiiii...<wait=40> Para onde fomos arremessados desta vez?","story.map6-ending.021":"<rep_handlename>!!","story.map6-ending.022":"...<wait=40>...<wait=40>Você conseguiu!","story.map6-ending.023":"Você é mesmo incrível!","story.map6-ending.024":"Nngh, <wait=40>machuquei o traseiro...","story.map6-ending.025":"Ei, você!<wait=40> Que tal pousar com um pouco mais de cuidado da próxima vez!","story.map6-ending.026":"Ho ho ho.","story.map6-ending.027":"Não deve ser problema com um traseiro grande como o seu, não acha, Seria?","story.map6-ending.028":"Gr-<wait=40>Grahde...<wait=40> Elder Grah!<wait=40> O que você está fazendo aqui!?","story.map6-ending.029":"Elder Grah?<wait=40> Que nome é esse?","story.map6-ending.030":"Espera aí, <wait=40>você não é o Grahdens?","story.map6-ending.031":"O que um Invocador Ancião como você está fazendo num lugar desses?","story.map6-ending.032":"Como ousa, <wait=40>seu tolo!","story.map6-ending.033":"E pensar que, <wait=40>finalmente, eu tinha feito a Tilith me ver só como um velhinho bondoso...","story.map6-ending.034":"E agora você aparece e estraga tudo!","story.map6-ending.035":"Hã?<wait=40> Como assim, \\"velhinho bondoso\\"?","story.map6-ending.036":"Como um dos chefes do Salão dos Invocadores,<wait=40> você não devia estar trabalhando lá!?","story.map6-ending.037":"Hmm, <wait=40>não entendi direito o que está acontecendo, <wait=40>mas parece que o Elder Grah era bem importante esse tempo todo.","story.map6-ending.038":"Ele não é só o velhinho esquisito que a gente conheceu...","story.map6-ending.039":"Ei, <wait=40>agora que você sabe quem é o Lord Grahdens, devia tratá-lo com um pouco mais de respeito!","story.map6-ending.040":"Mas isso não tem nada a ver comigo...","story.map6-ending.041":"E além disso, não sei como vocês veem as coisas aqui no mundo dos humanos...","story.map6-ending.042":"...mas, se fosse para escolher, você não diria que eu, como deusa, sou mais importante?","story.map6-ending.043":"Você é quem devia me tratar com mais respeito, Seria!","story.map6-ending.044":"Se é assim que você pensa, por que não tenta agir mais como uma deusa?","story.map6-ending.045":"Aonde você quer chegar com isso!?","story.map6-ending.046":"Acalmem-se, <wait=40>vão mesmo brigar logo depois da vitória de <rep_handlename> sobre o Zebra?","story.map6-ending.047":"Ho ho ho.","story.map6-ending.048":"Seria, <wait=40>é exatamente como a Tilith diz.","story.map6-ending.049":"Comparada aos deuses, <wait=40>minha existência é bem insignificante. ","story.map6-ending.050":"Tilith, <wait=40>eu gostaria que você continuasse me chamando simplesmente de Elder Grah.","story.map6-ending.051":"Eu já pretendia fazer isso de qualquer jeito.","story.map6-ending.052":"Agora eu sei quem você é de verdade, Elder Grah.<wait=40> Você é diferente daquela outra esquisita que eu conheço!","story.map6-ending.053":"De quem você está falando!?","story.map6-ending.054":"Hmm, quem será...","story.map6-ending.055":"Sério, <wait=40>vocês duas nunca vão mudar?","story.map6-ending.056":"Enfim, <wait=40>Grahdens...","story.map6-ending.057":"Voltando ao que eu queria saber antes, <wait=40>por que você está aqui?","story.map6-ending.058":"Karl...","story.map6-ending.059":"Você também é um Invocador, <wait=40>por que não me mostra um pouco mais de respeito?","story.map6-ending.060":"Ora, chega disso. <wait=40>Não vou deixar você mudar de assunto de novo.","story.map6-ending.061":"Eu te conheço há muito tempo e já estou acostumado com o seu jeito.","story.map6-ending.062":"Ho ho ho.<wait=40> Brutalmente sincero como sempre, pelo visto.","story.map6-ending.063":"Karl, <wait=40>permita-me explicar os detalhes depois.","story.map6-ending.064":"Primeiro, preciso conversar com <rep_handlename> sobre uma coisa.","story.map6-ending.065":"<rep_handlename>, <wait=40>por derrotar o Zebra como pedi...","story.map6-ending.066":"Expresso minha gratidão como Invocador Ancião do Departamento de Defesa do Salão dos Invocadores de Akras.","story.map6-ending.067":"Hehe, <wait=40>esperava algo menos de um grande amigo meu?","story.map6-ending.068":"Eu sabia que você conseguiria, meu <rep_handlename>!","story.map6-ending.069":"Ei, <wait=20>pare de chamá-lo de seu!","story.map6-ending.070":"E-<wait=40>Enfim, já que <rep_handlename> atendeu ao pedido do Lord Grahdens...","story.map6-ending.071":"Acho que posso justificar te elogiar como colega Invocadora.","story.map6-ending.072":"Que franqueza a sua!","story.map6-ending.073":"D-<wait=40>Do que você está falando!?","story.map6-ending.074":"Ho ho ho.<wait=40> Parece que todos estão bem gratos pelo que você fez.","story.map6-ending.075":"Porém, <wait=40>por mais forte que fosse, <wait=40>não se esqueça de que o Zebra era um mero discípulo de Cardes.","story.map6-ending.076":"O poder do Zebra não é nada comparado ao do deus caído que você persegue agora. ","story.map6-ending.077":"Com certeza, <wait=40>batalhas de ferocidade sem igual esperam por você em Palmyna.","story.map6-ending.078":"Agora, mais do que nunca, <wait=40>você deve avançar com cautela.","story.map6-ending.079":"Não se preocupe com ele. <wait=40>Ele está sob a minha proteção.","story.map6-ending.080":"Como assim, \\"minha proteção\\"? <wait=40>Você estava à beira da morte agorinha mesmo, não lembra?","story.map6-ending.081":"Seria!","story.map6-ending.082":"O-<wait=40>O quê!?","story.map6-ending.083":"Obrigada...<wait=40> por me proteger mais cedo.","story.map6-ending.084":"O-<wait=20>O q-<wait=10>que deu em v-<wait=10>você de repente?","story.map6-ending.085":"N-<wait=40>Não é como se eu estivesse querendo agradecimento nem nada...","story.map6-ending.086":"E-<wait=40>Eu só estava... <wait=20>*Resmungo* <size=14>*Resmungo* <size=12>*Resmungo*","story.map6-ending.087":"Haha, <wait=40>ficou tímida, foi?","story.map6-ending.088":"Ho ho ho.","story.map6-ending.089":"<rep_handlename>!","story.map6-ending.090":"Finalmente estamos indo para Palmyna, a terra onde Cardes está selado!","story.map6-ending.091":"Eu acredito em você...","story.map6-ending.092":"<rep_handlename>, <wait=40>você é o Invocador que vai salvar o mundo!","story.map6-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você, <rep_handlename>,<wait=39> que desvendou Amdahl...","story.map6-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use meu poder ao iniciar sua jornada nesta nova terra...","story.map6-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para trazer nova esperança a este mundo tão repleto de tristeza…","story.map6-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você deve ter fé no seu poder <wait=20>e continuar seguindo em frente…","story.map6-open.005":"Ah, <wait=40>você acordou!","story.map6-open.006":"Olha! <wait=40>Estamos em Encervis.","story.map6-open.007":"Com suas águas profundas e vulcões altos, <wait=40>este lugar é conhecido pelos ambientes extremos.","story.map6-open.008":"Há muito tempo, <wait=40>uma batalha entre humanos aconteceu aqui...","story.map6-open.009":"...<wait=40>...","story.map6-open.010":"Mas não é muito interessante, então vamos esquecer isso!","story.map6-open.011":"Além disso, <wait=40>tem muita outra coisa que você vai precisar aprender!","story.map6-open.012":"E isso nem tem muito a ver com a gente mesmo.","story.map6-open.013":"Aqui no meio do Arquipélago de Palmyna, ainda estamos bem longe da própria Palmyna...","story.map6-open.014":"Mas não vá se descuidar, <wait=20>e mantenha sempre o foco!","story.map6-open.015":"Espero grandes coisas de você aqui também!","story.map6-open.016":"Muito bem, <wait=20>vamos dar o nosso melhor e nos esforçar para derrotar o Cardes!!","story.map7-dungeon1.001":"<rep_handlename>!","story.map7-dungeon1.002":"Estamos encrencados!<wait=40> Muito encrencados!!","story.map7-dungeon1.003":"Kyahh!","story.map7-dungeon1.004":"<size=18>*Tum*","story.map7-dungeon1.005":"Aiiii, que dor...","story.map7-dungeon1.006":"Ei!<wait=40> <rep_handlename>! <wait=40>Não fique aí parado!","story.map7-dungeon1.007":"Hã? <wait=40>Você achou que eu ia estar te esperando no Castelo de Obselion?","story.map7-dungeon1.008":"Não dá tempo de se preocupar com esses detalhes agora!","story.map7-dungeon1.009":"Estamos encrencados de verdade!","story.map7-dungeon1.010":"O selo que prende Cardes começou a se desfazer!!","story.map7-dungeon1.011":"Não sei por que ele começou a se desfazer de repente...","story.map7-dungeon1.012":"...mas ele com certeza está se preparando pra escapar!","story.map7-dungeon1.013":"Mas acho que ninguém de fora teve nada a ver com isso.","story.map7-dungeon1.014":"Puxa!","story.map7-dungeon1.015":"Depois do jeito que você lidou com o Zebra, achei que derrotá-lo ia ser moleza.","story.map7-dungeon1.016":"Hunf, <wait=40>parece que as coisas vão ficar agitadas de novo...","story.map7-dungeon1.017":"Ainda tenho tanta coisa pra fazer pro Lord Lucius...","story.map7-dungeon1.018":"E agora ainda tenho que lidar com o que quer que Cardes esteja tramando...","story.map7-dungeon1.019":"Por que eu nunca tenho folga?!","story.map7-dungeon1.020":"Ah, <wait=40>quase esqueci!","story.map7-dungeon1.021":"Ainda não achei um caminho para o Mundo Espiritual!","story.map7-dungeon1.022":"Mas prometo que vou descobrir até você chegar ao Castelo de Obselion, <rep_handlename>.","story.map7-dungeon1.023":"Boa sorte, <wait=40>e desta vez a gente se encontra no Castelo de Obselion, sem falta!","story.map7-dungeon2.001":"Ho ho ho. <wait=40>Ora, se não é <rep_handlename>?","story.map7-dungeon2.002":"A caminho da terra onde Cardes está selado, não é?","story.map7-dungeon2.003":"Hum? <wait=40>O que houve?<wait=40> Você parece inquieto.","story.map7-dungeon2.004":"Se está procurando Tilith, não a vi por aqui.","story.map7-dungeon2.005":"Que cara aflita é essa? <wait=40>Não precisa se preocupar com ela, sabia?","story.map7-dungeon2.006":"Ela está além das preocupações de meros Invocadores como nós.","story.map7-dungeon2.007":"Se bem que o jeito adorável com que ela olha pra você também me deixaria nervoso.","story.map7-dungeon2.008":"Ho ho ho.","story.map7-dungeon2.009":"Hunf. <wait=40>Parece que faz tempo que não ficamos só nós dois.","story.map7-dungeon2.010":"Já que temos um tempinho, <wait=40>que tal eu lhe contar uma pequena história?","story.map7-dungeon2.011":"Uma história sobre uma batalha terrível entre os humanos e os deuses.","story.map7-dungeon2.012":"Há muito tempo, <wait=40>o Castelo de Obselion era o lar da Família Real de Palmyna.","story.map7-dungeon2.013":"Originalmente era um castelo pitoresco, <wait=40>cercado de verde.","story.map7-dungeon2.014":"Porém, foi isto que aconteceu com ele depois da batalha com os deuses.","story.map7-dungeon2.015":"Você conhece os Quatro Heróis de Palmyna?","story.map7-dungeon2.016":"Diz a lenda que quatro guerreiros lutaram contra Cardes para salvar esta terra.","story.map7-dungeon2.017":"Dizem até que Edea, a Princesa de Palmyna, estava entre eles.","story.map7-dungeon2.018":"Se a lenda for verdadeira, foram esses Quatro Heróis que selaram Cardes.","story.map7-dungeon2.019":"Porém, dizem que, em troca de conseguirem selar Cardes...","story.map7-dungeon2.020":"...os Quatro Heróis tiveram que sacrificar a própria vida.","story.map7-dungeon2.021":"Fico imaginando o que eles pensavam no fim.","story.map7-dungeon2.022":"Será que estavam felizes por acreditar que selar Cardes salvaria Palmyna?","story.map7-dungeon2.023":"Foi assim que conseguiram encarar a morte sem medo?","story.map7-dungeon2.024":"Por mais valentes que tenham sido ao arriscar a vida para proteger este lugar...","story.map7-dungeon2.025":"...quando começaram a lutar, ele já estava perdido.","story.map7-dungeon2.026":"Uma história realmente triste...","story.map7-dungeon2.027":"<rep_handlename>, <wait=40>você entende o que estou tentando dizer?","story.map7-dungeon2.028":"Ho ho ho. <wait=40>Não se preocupe.","story.map7-dungeon2.029":"Com certeza, <wait=40>um dia você se verá numa situação igualmente inimaginável.","story.map7-dungeon2.030":"Até lá, <wait=40>observe com atenção o mundo à sua volta enquanto ele muda.","story.map7-dungeon2.031":"O que você descobrir servirá de combustível no seu caminho adiante.","story.map7-dungeon2.032":"Ho ho ho.<wait=40> Desculpe o sermão comprido.","story.map7-dungeon2.033":"Quando encontrar Tilith de novo, por favor, passe esta mensagem a ela.","story.map7-dungeon2.034":"O selo de Cardes está quase rompido.","story.map7-dungeon2.035":"Até mais, e se cuide.","story.map7-dungeon3.001":"<size=18>*Corte*","story.map7-dungeon3.002":"Ufa. <wait=40>Parece que acabamos com os monstros desta área.","story.map7-dungeon3.003":"Mas tenho que admitir, <wait=40>eles são bem mais fortes do que eu esperava.","story.map7-dungeon3.004":"Hum?","story.map7-dungeon3.005":"Ei! <wait=40><rep_handlename>!","story.map7-dungeon3.006":"Bem-vindo a Palmyna!","story.map7-dungeon3.007":"Não estamos longe de onde Cardes está selado. <wait=40>Vamos dar tudo de nós neste último esforço!","story.map7-dungeon3.008":"Ei! <wait=40>Seria!<wait=40> <rep_handlename> chegou também!","story.map7-dungeon3.009":"Não precisa me avisar toda vez. <wait=40>Além disso, eu só estava ignorando <rep_handlename>.","story.map7-dungeon3.010":"Haha. <wait=40>A mesma de sempre, né, Seria?","story.map7-dungeon3.011":"Enfim, <wait=40>cadê aquela deusa que vive te seguindo?","story.map7-dungeon3.012":"...Hum, então ela está procurando um caminho para o Mundo Espiritual.","story.map7-dungeon3.013":"Parece que não temos escolha a não ser ir até lá se quisermos enfrentar Cardes...","story.map7-dungeon3.014":"O que foi?<wait=40> Você está meio pálida.","story.map7-dungeon3.015":"N-<wait=40>Não é nada!","story.map7-dungeon3.016":"Só estou um pouco irritada!","story.map7-dungeon3.017":"Quer dizer, <wait=40>você não vê o que está acontecendo, Karl!?","story.map7-dungeon3.018":"Nosso objetivo sempre foi derrotar Graham!","story.map7-dungeon3.019":"Por que temos que perder tempo ajudando <rep_handlename>!?","story.map7-dungeon3.020":"Ora, <wait=40>derrotar os Quatro Deuses Caídos com certeza tem prioridade sobre Graham.","story.map7-dungeon3.021":"Eu sei, eu sei!","story.map7-dungeon3.022":"Mas você sabe como eu me sinto, né, Karl?","story.map7-dungeon3.023":"Mais do que tudo, eu quero acabar com Graham!","story.map7-dungeon3.024":"Sim, <wait=40>eu entendo como você se sente. <wait=50>Me perdoe, <wait=40>Seria...","story.map7-dungeon3.025":"Eu não quis colocar a culpa em você nem nada, Karl...","story.map7-dungeon3.026":"Grrr!!<wait=40> É tudo culpa sua!","story.map7-dungeon3.027":"Por que você não enfrenta Cardes sozinho de uma vez!","story.map7-dungeon3.028":"Um pouco absurdo,<wait=40> não acha?","story.map7-dungeon3.029":"Eu já disse que sei!","story.map7-dungeon3.030":"Karl, <wait=40>tá ficando difícil demais discutir com você ultimamente!","story.map7-dungeon3.031":"Não, <wait=40>é que você anda dizendo coisas tão ridículas ultimamente...","story.map7-dungeon3.032":"Não faço ideia do que você está falando!","story.map7-dungeon3.033":"<rep_handlename>! <wait=40>Ande logo e encontre aquela deusa...","story.map7-dungeon3.034":"...e descubra como a gente vai chegar ao Mundo Espiritual!","story.map7-dungeon3.035":"E-<wait=20>Ei!<wait=40> Me espera!","story.map7-dungeon3.036":"<rep_handlename>! Nós vamos abrir caminho à frente.","story.map7-dungeon3.037":"Só trate de estar pronto para enfrentar Cardes!","story.map7-dungeon4.001":"...<rep_handlename>.","story.map7-dungeon4.002":"Que bom te ver... <wait=40>Parece que você está bem...","story.map7-dungeon4.003":"Arf...<wait=40> arf...","story.map7-dungeon4.004":"E-<wait=40>Eu estou bem...","story.map7-dungeon4.005":"Nngh...<wait=40> Parece que eu vacilei um pouco...","story.map7-dungeon4.006":"Enquanto eu tentava descobrir como chegar ao Mundo Espiritual, <wait=40>aconteceu uma coisa inesperada...","story.map7-dungeon4.007":"Desculpe por te deixar preocupado.","story.map7-dungeon4.008":"Eu vou ficar bem, <wait=20>só preciso de um descansinho.","story.map7-dungeon4.009":"Mas, mais importante, <wait=40>tenho uma coisa pra te contar...","story.map7-dungeon4.010":"<rep_handlename>...","story.map7-dungeon4.011":"O selo de Cardes...<wait=40> não estava só rachando...","story.map7-dungeon4.012":"Cardes... <wait=40>está destruindo o selo... <wait=40>por dentro...","story.map7-dungeon4.013":"Ele está enfraquecido por ter ficado selado por tanto tempo...","story.map7-dungeon4.014":"Mas os poderes dele como deus ainda são tremendos...","story.map7-dungeon4.015":"Eles já começaram a transbordar do Mundo Espiritual, <wait=40>destruindo tudo pelo caminho...","story.map7-dungeon4.016":"Tentei reparar o selo, mas falhei...","story.map7-dungeon4.017":"Arf...<wait=40> arf...","story.map7-dungeon4.018":"M-<wait=40>Mas... <wait=40>ainda temos uma chance.","story.map7-dungeon4.019":"O caminho para o Mundo Espiritual agora está aberto.","story.map7-dungeon4.020":"Vá para o Campo de Batalha de Noera. <wait=40>A entrada do Mundo Espiritual fica logo depois de lá...","story.map7-dungeon4.021":"Pode ir na frente, <wait=40>e não se preocupe comigo!","story.map7-dungeon4.022":"E aproveite pra pedir ajuda ao Karl, à Seria e ao Elder Grah.","story.map7-dungeon4.023":"Vou descansar antes de me juntar a vocês...","story.map7-dungeon4.024":"Não se preocupe comigo...","story.map7-dungeon4.025":"Eu sou uma deusa linda e invencível!","story.map7-dungeon4.026":"É só que, <wait=40>estou um pouquinho cansada agora...","story.map7-dungeon4.027":"Mas não se preocupe... <wait=50>A gente se vê na linha de frente...","story.map7-dungeon5.001":"Ora, se não é <rep_handlename>.","story.map7-dungeon5.002":"Que expressão séria é essa no seu rosto?","story.map7-dungeon5.003":"O que você disse!?<wait=40> O que aconteceu com Tilith!?","story.map7-dungeon5.004":"Hunf. <wait=40>A situação parece mais urgente do que eu podia imaginar.","story.map7-dungeon5.005":"Sinto muito, mas tenho algo a resolver por aqui, <wait=40>então não posso ajudá-lo.","story.map7-dungeon5.006":"Já pedi a Karl e Seria que o auxiliem.","story.map7-dungeon5.007":"Vocês devem trabalhar juntos para derrotar Cardes.","story.map7-dungeon5.008":"......<wait=50><rep_handlename>.","story.map7-dungeon5.009":"Tenho algo a lhe dizer antes que você enfrente o Deus Caído.","story.map7-dungeon5.010":"Um dos Quatro Heróis de Palmyna trabalhava aqui, no Seminário de Arlind.","story.map7-dungeon5.011":"O nome dele era Lorand, e ele era professor.","story.map7-dungeon5.012":"Embora já tivesse se aposentado da vida de soldado...","story.map7-dungeon5.013":"...Edea, a Princesa de Palmyna, <wait=40>convenceu-o a lutar contra os deuses invasores.","story.map7-dungeon5.014":"Terminou exatamente como eu lhe contei antes.","story.map7-dungeon5.015":"Os Quatro Heróis sacrificaram a vida para selar Cardes.","story.map7-dungeon5.016":"Porém, <wait=40>há muitas outras histórias de pessoas que lutaram como os Quatro Heróis.","story.map7-dungeon5.017":"Há muito tempo, <wait=40>muitos humanos lutaram contra os deuses aqui.","story.map7-dungeon5.018":"A maioria deles acabou perdendo a vida.","story.map7-dungeon5.019":"Segundo a lenda, <wait=40>Lucius permitiu que alguns sobreviventes fugissem para Elgaia.","story.map7-dungeon5.020":"Todos os que ficaram em Grand Gaia pereceram.","story.map7-dungeon5.021":"<rep_handlename>.<wait=50> Por que você acha que os deuses destruíram os humanos?","story.map7-dungeon5.022":"Há inúmeras teorias, <wait=40>mas ainda não se encontrou uma resposta.","story.map7-dungeon5.023":"Mas, depois de muito tempo, <wait=40>Lucius abriu de novo o caminho para Grand Gaia.","story.map7-dungeon5.024":"Ele também deve precisar da força dos humanos para derrotar os Quatro Deuses Caídos.","story.map7-dungeon5.025":"Dito isso, por que exatamente os Quatro Deuses Caídos estão se enfurecendo assim?","story.map7-dungeon5.026":"E por que o Sagrado Imperador Karna Masta, senhor dos deuses, não reagiu a esta situação?","story.map7-dungeon5.027":"Há coisas demais que nós, humanos, simplesmente nunca vamos entender.","story.map7-dungeon5.028":"Mas Tilith, como discípula de Lucius, com certeza deve entender, não acha?","story.map7-dungeon5.029":"Tem certeza de que ela não sabe? <wait=40>Talvez ela só esteja escondendo certas informações de você.","story.map7-dungeon5.030":"Ou talvez, <wait=40>ela simplesmente não esteja pensando em nada.","story.map7-dungeon5.031":"Ho ho ho.","story.map7-dungeon5.032":"Tilith é uma moça tão boa e bonita que eu espero que seja só isso.","story.map7-dungeon5.033":"Enfim, <wait=40><rep_handlename>.","story.map7-dungeon5.034":"Desculpe divagar assim, <wait=40>mas tenho certeza de que você entende aonde quero chegar.","story.map7-dungeon5.035":"Não se deixe levar por tudo o que está acontecendo, <wait=40>aja segundo seus próprios pensamentos e vontade.","story.map7-dungeon5.036":"Seu papel nisso tudo já se tornou mais do que um único Invocador deveria ser capaz de suportar.","story.map7-dungeon5.037":"Agora você deve seguir seu caminho.","story.map7-dungeon5.038":"Depois do Campo de Batalha de Noera, logo adiante, fica a entrada do Mundo Espiritual.","story.map7-dungeon5.039":"E não se esqueça, <wait=20>Tilith e os deuses não são os únicos que contam com você.","story.map7-dungeon6.001":"E aí, <rep_handlename>!<wait=40> Você já chegou.","story.map7-dungeon6.002":"Olha!<wait=40> A entrada do Mundo Espiritual está bem na nossa frente.","story.map7-dungeon6.003":"Ei, <wait=40>aquela deusa te contou como a gente entra no Mundo Espiritual, né?","story.map7-dungeon6.004":"E cadê ela? <wait=40>Como ela pode estar por aí de bobeira num momento crítico como este!?","story.map7-dungeon6.005":"Hã......<wait=50> Ah, entendi......","story.map7-dungeon6.006":"M-<wait=40>Mas não é nada pra se preocupar, né?<wait=40> Afinal, ela é uma deusa, não é!?","story.map7-dungeon6.007":"Aposto que mais cedo ou mais tarde ela aparece com aquela cara convencida!","story.map7-dungeon6.008":"Então tire essa cara de coitado e faça o seu trabalho!","story.map7-dungeon6.009":"Ela fez o que fez justamente porque acreditava que você conseguiria derrotar Cardes!","story.map7-dungeon6.010":"Agora você tem que dar tudo de si! <wait=40>Não pode deixar tudo o que ela fez ser em vão!","story.map7-dungeon6.011":"Ela tem razão.","story.map7-dungeon6.012":"Sei que você está preocupado, <rep_handlename>, <wait=40>mas antes de tudo temos que derrotar Cardes.","story.map7-dungeon6.013":"Se a entrada do Mundo Espiritual está mesmo aberta...","story.map7-dungeon6.014":"...então nada nos impede de ajudar você também.","story.map7-dungeon6.015":"Pelo bem da deusa, <wait=40>vamos fazer tudo o que pudermos para ajudar!","story.map7-dungeon6.016":"E-<wait=40>Eu só vou seguir as ordens do Salão dos Invocadores!","story.map7-dungeon6.017":"O que eu faço não tem nada a ver com aquela deusa boba!","story.map7-dungeon6.018":"De qualquer forma, <wait=40>seria bom ela ficar nos devendo uma, pra variar.","story.map7-dungeon6.019":"Acho que desta vez vou me esforçar um pouco mais que o normal.","story.map7-dungeon6.020":"Heh, <wait=40>tenho certeza de que até ela ficaria tranquila vendo você tão motivada, Seria.","story.map7-dungeon6.021":"D-<wait=40>Do que você está falando!?","story.map7-dungeon6.022":"Só estou dizendo que parece que podemos contar com você, Seria. <wait=40>Não é, <rep_handlename>?","story.map7-dungeon6.023":"Não dê corda pra ele!","story.map7-dungeon6.024":"Muito bem, <wait=40>vamos abrir caminho até o Mundo Espiritual!","story.map7-dungeon6.025":"<rep_handlename>!<wait=40> Seria!<wait=40> Vamos!","story.map7-dungeon7.001":"Então este é o Mundo Espiritual Palmyna...<wait=40> Bem sinistro, devo dizer.","story.map7-dungeon7.002":"Que bom que é bem mais espaçoso do que eu imaginava.","story.map7-dungeon7.003":"Hã?<wait=40> Ser mais espaçoso não vai dificultar encontrar Cardes?","story.map7-dungeon7.004":"B-<wait=20>Bom, quer dizer...<wait=40> Não foi isso que eu quis dizer...","story.map7-dungeon7.005":"Só pensei que seria difícil lutar contra Cardes num espaço apertado.","story.map7-dungeon7.006":"É, <wait=40>nisso você tem razão.","story.map7-dungeon7.007":"Com tanto espaço assim, <wait=40>nossas opções para enfrentar Cardes são ilimitadas.","story.map7-dungeon7.008":"É, <wait=40>parece que sim.","story.map7-dungeon7.009":"<size=16>*Estrondo*","story.map7-dungeon7.010":"O-<wait=20>O que foi isso!<wait=20> Por que está tudo tremendo?","story.map7-dungeon7.011":"Droga! <wait=40>Parece que as coisas não são tão tranquilas quanto pareciam!","story.map7-dungeon7.012":"Eu esperava ter mais tempo para procurar Cardes...","story.map7-dungeon7.013":"<rep_handlename>!<wait=40> Seria!","story.map7-dungeon7.014":"Vamos nos separar e procurar Cardes!","story.map7-dungeon7.015":"Você acha mesmo que essa é uma boa ideia numa hora dessas!?","story.map7-dungeon7.016":"Nosso tempo está acabando.","story.map7-dungeon7.017":"Se não derrotarmos Cardes antes que ele se liberte...","story.map7-dungeon7.018":"...é bem provável que a gente desapareça junto com o Mundo Espiritual.","story.map7-dungeon7.019":"......<wait=40>Entendido.","story.map7-dungeon7.020":"Se ouvirem o choque de espadas, <wait=40>com certeza é ali que a luta começou.","story.map7-dungeon7.021":"Fiquem de ouvidos atentos e de olho em tudo à sua volta!","story.map7-dungeon7.022":"<rep_handlename>!","story.map7-dungeon7.023":"Você ainda é novato, <wait=40>então se vir Cardes, é melhor sentar e esperar por nós!","story.map7-dungeon7.024":"Ela tem razão. <wait=40>Aconteça o que acontecer, nenhum de nós deve enfrentá-lo sozinho!","story.map7-dungeon7.025":"Quero que todos nós sobrevivamos e voltemos juntos para Elgaia!","story.map7-ending.001":"Arf...<wait=40> arf...<wait=40> Chegamos tarde!","story.map7-ending.002":"<size=20>*Estrondo*","story.map7-ending.003":"<anchor=center><speed=10>Seria...<wait=40> Segure minha mão......","story.map7-ending.004":"Olá, pessoal! <wait=40>Desculpem o atraso!!","story.map7-ending.005":"<rep_handlename>! <wait=40>Eu sabia que você conseguiria!","story.map7-ending.006":"V-<wait=20>Você! <wait=40>O que está fazendo aqui!?","story.map7-ending.007":"Achei que você estivesse gravemente ferida...","story.map7-ending.008":"Tive um pressentimento de que <rep_handlename> estava em apuros, <wait=40>então deixei a recuperação de lado e vim ajudar.","story.map7-ending.009":"Mas ainda estou com um pouquinho de dor.","story.map7-ending.010":"Que tolice fazer uma coisa dessas por causa de um palpite!","story.map7-ending.011":"Que bom que cheguei a tempo de ajudar você também, <wait=40>Seria.","story.map7-ending.012":"......","story.map7-ending.013":"O-<wait=40>Obrigada por isso...","story.map7-ending.014":"Não precisa agradecer! <wait=40>Estou feliz que todos estejam bem!","story.map7-ending.015":"É, <wait=40>obrigado por nos salvar!","story.map7-ending.016":"Teria sido uma pena sermos derrotados num lugar destes, <wait=40> depois de termos acabado com Cardes.","story.map7-ending.017":"Obrigado, <wait=40>deusa.","story.map7-ending.018":"Esse é o Karl de que eu me lembro! <wait=40>Pode me agradecer mais também, Seria!","story.map7-ending.019":"N-<wait=40>Não abuse!","story.map7-ending.020":"Quer dizer, <wait=40>se você é uma deusa, por que sempre chega no último minuto, toda santa vez!","story.map7-ending.021":"O-<wait=40>O que deu em você!","story.map7-ending.022":"E tem mais, por que você não nos disse como sair do Mundo Espiritual!?","story.map7-ending.023":"A-<wait=40>Ai, <wait=20>devo ter...","story.map7-ending.024":"Vamos deixar as coisas como estão.","story.map7-ending.025":"E, por mais que não pareça, a Seria é mesmo grata pelo que você fez por ela.","story.map7-ending.026":"É, <wait=40>eu sei.","story.map7-ending.027":"Dá pra ver pelo jeito que ela está corando!","story.map7-ending.028":"Eu também gosto muito da Seria!","story.map7-ending.029":"Chega! <wait=40>Vocês estão me dando enjoo!!","story.map7-ending.030":"<size=12>Você é mesmo um idiota...","story.map7-ending.031":"Karl! <wait=40>Eu vou embora!","story.map7-ending.032":"Já fizemos o que o Salão dos Invocadores nos pediu!","story.map7-ending.033":"Agora é hora de ir atrás de Graham!","story.map7-ending.034":"E-<wait=20>Espera!","story.map7-ending.035":"<rep_handlename>!","story.map7-ending.036":"Nunca tive tanto orgulho de chamar você de amigo!","story.map7-ending.037":"Quando as coisas se acalmarem, <wait=20>vamos viver uma aventura juntos em Grand Gaia!","story.map7-ending.038":"Não fique se achando só porque derrotou Cardes!","story.map7-ending.039":"Sua sorte uma hora vai acabar, sabia?","story.map7-ending.040":"Da próxima vez que nos encontrarmos, vou te mostrar o verdadeiro poder da Invocadora no comando dos Caçadores de Demônios.","story.map7-ending.041":"Mas até lá, <wait=20>trate de continuar inteiro!","story.map7-ending.042":"Eles se foram.","story.map7-ending.043":"Espero que a gente possa lutar junto de novo algum dia!","story.map7-ending.044":"<rep_handlename>! <wait=40>Muito obrigada por derrotar Cardes!","story.map7-ending.045":"Admito que eu não podia contar muito com você quando nos conhecemos, <wait=40>mas você já derrotou dois dos Quatro Deuses Caídos.","story.map7-ending.046":"Vocês, humanos, são mesmo interessantes!","story.map7-ending.047":"Desde que conheci o Karl, a Seria<wait=40> e você...","story.map7-ending.048":"...passei a gostar de vocês, humanos, mais do que nunca!","story.map7-ending.049":"Mal posso esperar por mais aventuras com você, <wait=40>meu querido <rep_handlename>.","story.map7-ending.050":"......<wait=40>Parece que o grande Cardes foi derrotado.","story.map7-ending.051":"Os únicos Deuses Caídos restantes são Zevalhua, o Supremo, <wait=40>e o Deus Fera Afla Dilith.","story.map7-ending.052":"Certamente já está na hora de eles entrarem na disputa também.","story.map7-ending.053":"Precisamos apressar nossos preparativos.","story.map7-ending.054":"<rep_handlename>...","story.map7-ending.055":"Estou ansioso para ver que caminho você tomará nesta próxima batalha...","story.map7-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você, <rep_handlename>,<wait=39> que desbloqueou Encervis...","story.map7-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use meu poder ao avançar por Palmyna, <wait=40>terra do Deus Caído selado...","story.map7-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para trazer nova esperança a este mundo tão impregnado de tristeza...","story.map7-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você deve ter fé em seu poder, <wait=20>e seguir sempre em frente...","story.map7-open.005":"<rep_handlename>!<wait=40> Então você finalmente chegou a Palmyna!","story.map7-open.006":"Falta pouco até o Mundo Espiritual onde Cardes está preso!","story.map7-open.007":"Como você conseguiu derrotar o Zebra, tenho certeza de que vai chegar lá rapidinho, <rep_handlename>.","story.map7-open.008":"Mesmo assim, <wait=40>não vá se descuidar!","story.map7-open.009":"Há muito tempo existia aqui um reino chamado Palmyna, que lutou bravamente contra os deuses.","story.map7-open.010":"Os vestígios daquela guerra ainda podem ser vistos hoje...","story.map7-open.011":"...junto com todos os espíritos e monstros que ainda vagam por aí.","story.map7-open.012":"Muito bem, <wait=40>deixa eu achar um caminho pra gente até o Mundo Espiritual.","story.map7-open.013":"Vá com calma, <rep_handlename>.","story.map7-open.014":"Vou estar te esperando logo adiante, no Castelo de Obselion!","story.map8-dungeon1.001":"Droga! <wait=40>Ainda está tão longe.","story.map8-dungeon1.002":"Mas enfim, <wait=20>não adianta reclamar agora.","story.map8-dungeon1.003":"Hã? <wait=40>Ei, você!","story.map8-dungeon1.004":"Tsc, <wait=20>se não é o nosso querido <rep_handlename>.","story.map8-dungeon1.005":"Por que você está aqui?","story.map8-dungeon1.006":"Não me diga!?","story.map8-dungeon1.007":"Você veio levar o crédito pelo meu trabalho duro, não foi!?","story.map8-dungeon1.008":"Enfim, <wait=20>que história é essa que eu ouvi sobre Cordelica?","story.map8-dungeon1.009":"Ouvi um boato de que você derrubou sozinho um dos Quatro Deuses Caídos?","story.map8-dungeon1.010":"Hunf, <wait=40>ou talvez, <wait=20>o Karl e a Seria tiveram que vir te salvar, hein?","story.map8-dungeon1.011":"Tanto faz, <wait=20>não que faça alguma diferença.","story.map8-dungeon1.012":"Cala a boca! <wait=40>Eu não pedi explicação nenhuma!","story.map8-dungeon1.013":"Se você tiver meio cérebro nessa cabeça, vai ouvir o que eu tenho a dizer!","story.map8-dungeon1.014":"En<wait=20>fi<wait=20>m.","story.map8-dungeon1.015":"É melhor não ficar no meu caminho! Só isso!","story.map8-dungeon1.016":"Estou no meio de uma missão importantíssima a serviço do Salão dos Invocadores.","story.map8-dungeon1.017":"Mas não é nada que uma elite como eu não dê conta.","story.map8-dungeon1.018":"Se você entendeu, é melhor ir dar uma volta em outro lugar!","story.map8-dungeon1.019":"E eu prometo: se eu te pegar zanzando por Cordelica, acabo com você rapidinho.","story.map8-dungeon1.020":"Entendeu?","story.map8-dungeon2.001":"Ufa, <wait=40>este lugar é mais perigoso do que eu pensava.","story.map8-dungeon2.002":"Desse jeito, ainda tenho um longo caminho até chegar à torre.","story.map8-dungeon2.003":"Ora, <wait=40>se não é <rep_handlename>.","story.map8-dungeon2.004":"O que você está fazendo aqui?","story.map8-dungeon2.005":"Hehe, <wait=40>acho que nem preciso perguntar.","story.map8-dungeon2.006":"O Salão dos Invocadores deve estar levando isso muito a sério para mandar você até aqui.","story.map8-dungeon2.007":"Mas, mesmo assim, <wait=20>não pretendo ceder.","story.map8-dungeon2.008":"A Guarda Imperial vai tomar o poder escondido em Lizeria.","story.map8-dungeon2.009":"Hehe, <wait=40>não precisa fazer essa cara.","story.map8-dungeon2.010":"Eu vi do que você é capaz de verdade lá em Cordelica.","story.map8-dungeon2.011":"Por que não larga aquele bando de Akras e se junta a nós?","story.map8-dungeon2.012":"Para construir a verdadeira paz, é preciso se libertar do controle dos anciões!","story.map8-dungeon2.013":"Que papo é esse, <wait=40>cão do Império!","story.map8-dungeon2.014":"Nada do que você disser a <rep_handlename> vai adiantar.","story.map8-dungeon2.015":"Essa voz vulgar...","story.map8-dungeon2.016":"Quanto tempo...","story.map8-dungeon2.017":"Senhorita Guarda Imperial.","story.map8-dungeon2.018":"Que surpresa. <wait=40>Como foi que você chegou aqui?","story.map8-dungeon2.019":"Não foi nada de mais, sério.","story.map8-dungeon2.020":"Acontece que eu sou o Invocador especialmente escolhido pelo Salão dos Invocadores para vir aqui fazer umas pesquisas.","story.map8-dungeon2.021":"Aquele Invocador com cara de bobo ali é só um turista atrás de emoção barata.","story.map8-dungeon2.022":"<rep_handlename> não faz ideia do que está acontecendo aqui.","story.map8-dungeon2.023":"Quer dizer, você não estava compartilhando nenhuma informação importante com esse idiota, estava?","story.map8-dungeon2.024":"Ngh...","story.map8-dungeon2.025":"Enfim, <wait=20>os verdadeiros tolos aqui são aquele pessoal do Salão dos Invocadores.","story.map8-dungeon2.026":"Como puderam mandar um Invocador de segunda categoria como você para um lugar como este?","story.map8-dungeon2.027":"Isso só prova que eles não fazem ideia de quanto esta área é valiosa.","story.map8-dungeon2.028":"E, se for mesmo assim, <wait=20>não devo ter problema nenhum para obter o poder escondido aqui.","story.map8-dungeon2.029":"Ei! <wait=40>Olha a boca!","story.map8-dungeon2.030":"Você não teria a menor chance contra mim se eu lutasse com tudo!","story.map8-dungeon2.031":"Hehe, <wait=40>que cara você está fazendo.","story.map8-dungeon2.032":"Mas, sério, <wait=20>não precisa bancar o durão.","story.map8-dungeon2.033":"Até porque eu não tenho tempo para brincar com você.","story.map8-dungeon2.034":"Vai fugir?","story.map8-dungeon2.035":"Não, <wait=40>só prefiro evitar confrontos inúteis enquanto cumpro meu objetivo.","story.map8-dungeon2.036":"<rep_handlename>, <wait=40>pense no que acabamos de conversar.","story.map8-dungeon2.037":"Tenho certeza de que seria mais vantajoso para você do que ter aliados tolos como ele.","story.map8-dungeon2.038":"<size=22>Do que você está falando!</size>","story.map8-dungeon2.039":"Heh, <wait=40>no fim ela fugiu mesmo.","story.map8-dungeon2.040":"Ei! <wait=40><rep_handlename>!","story.map8-dungeon2.041":"Por que eu sempre te encontro em lugares assim?","story.map8-dungeon2.042":"Está me dizendo que não pretende ouvir o que eu digo?","story.map8-dungeon2.043":"Ou talvez, <wait=20>você pretenda aceitar a oferta dela e trair o Salão dos Invocadores?","story.map8-dungeon2.044":"Pra mim tanto faz o que você fizer, na verdade.","story.map8-dungeon2.045":"Se ignorar meu aviso de novo, <wait=20>da próxima vez que eu te vir...","story.map8-dungeon2.046":"...não vou ter escolha a não ser te reduzir a pó.","story.map8-dungeon2.047":"Heh, <wait=40>como você é um estorvo!","story.map8-dungeon2.048":"Mas não se preocupe, <wait=40>não estou tentando te ameaçar nem nada.","story.map8-dungeon2.049":"Só queria que você soubesse que eu não deixo ninguém ficar no meu caminho!","story.map8-dungeon2.050":"Entendeu?","story.map8-dungeon3.001":"Ei, <wait=40><rep_handlename>.","story.map8-dungeon3.002":"Você parece de bom humor.","story.map8-dungeon3.003":"Espera!","story.map8-dungeon3.004":"Se você ignorou meu aviso e veio até aqui, só pode significar que pretende trair o Salão dos Invocadores, acertei?","story.map8-dungeon3.005":"Que tipo de condições aquela mulher te ofereceu?","story.map8-dungeon3.006":"Hã? <wait=40>Você diz que não é um traidor?","story.map8-dungeon3.007":"<size=22>Há há há!</size>","story.map8-dungeon3.008":"Para alguém tão tolo, você fez uma escolha interessante.","story.map8-dungeon3.009":"O que só pode significar uma coisa...","story.map8-dungeon3.010":"Você veio com a intenção de me causar problemas, não foi?","story.map8-dungeon3.011":"Há há há! <wait=40>Você é uma figura!","story.map8-dungeon3.012":"<size=22>É melhor não se achar demais!</size>","story.map8-dungeon3.013":"Quer que eu te mostre exatamente o quanto você é inferior a mim?","story.map8-dungeon3.014":"Que idiota.","story.map8-dungeon3.015":"Eu simplesmente não te suporto.","story.map8-dungeon3.016":"Ah, e por falar nisso, ouvi dizer que você também é amigo daquele pateta do Karl.","story.map8-dungeon3.017":"Parece que não tenho escolha a não ser te dar uma lição e mostrar o quanto eu sou incrível de verdade.","story.map8-dungeon3.018":"Que tal? <wait=20>Vou te esperar logo depois deste lago congelado.","story.map8-dungeon3.019":"Vou te ensinar pessoalmente, então é bom você ficar ansioso!","story.map8-dungeon4.001":"N-<wait=20>Não pode ser! <wait=40>Isso é impossível.","story.map8-dungeon4.002":"Cardes também foi derrotado!?","story.map8-dungeon4.003":"N-<wait=20>Não, <wait=40>não duvido do senhor...","story.map8-dungeon4.004":"Entendido. <wait=40>Vou cuidar disso com o máximo de cuidado possível.","story.map8-dungeon4.005":"Sim. <wait=40>Não precisa se preocupar com isso.","story.map8-dungeon4.006":"Farei o meu melhor para não decepcioná-lo.","story.map8-dungeon4.007":"Ufa... <wait=40>As coisas estão se desenrolando bem mais rápido do que eu esperava.","story.map8-dungeon4.008":"Hã, <wait=20>será que é...","story.map8-dungeon4.009":"Hehe, <wait=40>então nos encontramos de novo.","story.map8-dungeon4.010":"Então suponho que você derrotou o Lugina?","story.map8-dungeon4.011":"Derrotar um Invocador tão fraco com certeza não foi problema para você, que já derrotou dois dos Quatro Deuses Caídos, não é?","story.map8-dungeon4.012":"Hehe, <wait=20>não me olhe desse jeito.","story.map8-dungeon4.013":"Eu entendo o quanto você é mais poderoso do que ele de verdade.","story.map8-dungeon4.014":"Então, <wait=20>deixe-me perguntar mais uma vez.","story.map8-dungeon4.015":"Não quer deixar o Salão dos Invocadores de Akras para trás e vir trabalhar conosco?","story.map8-dungeon4.016":"Da última vez não tivemos tempo de conversar, já que fomos interrompidos de forma tão grosseira.","story.map8-dungeon4.017":"Mas estou falando sério.","story.map8-dungeon4.018":"Hehe, <wait=20>é claro que um convite tão repentino deixaria você sem saber o que pensar.","story.map8-dungeon4.019":"Só deixe eu te contar uma coisa. <wait=40>O sistema de governo de Elgaia está falido.","story.map8-dungeon4.020":"E somos os únicos que podem consertá-lo.","story.map8-dungeon4.021":"Você também consegue ver o que está acontecendo, certo?","story.map8-dungeon4.022":"Em vez de uma república, o mundo está sendo governado por uma organização de Invocadores.","story.map8-dungeon4.023":"Há muito tempo, <wait=20>houve alguns que escaparam do trágico confronto com os deuses.","story.map8-dungeon4.024":"Eles lideraram o povo e formaram o Império Randall.","story.map8-dungeon4.025":"Então, <wait=20>muito tempo depois da formação do império...","story.map8-dungeon4.026":"...vários grupos se formaram em oposição à classe privilegiada do Império Randall.","story.map8-dungeon4.027":"Eles formaram a Federação de Elgaia.","story.map8-dungeon4.028":"Mais recentemente, foi Elgaia que começou a mudar primeiro.","story.map8-dungeon4.029":"Durante essa mudança surgiram os Invocadores, <wait=20>assim como alguém que desejava unir todos eles.","story.map8-dungeon4.030":"Eles formaram o Salão dos Invocadores de Akras.","story.map8-dungeon4.031":"Os Invocadores Ancestrais que fundaram o Salão dos Invocadores de Akras...","story.map8-dungeon4.032":"...também conhecidos como \\"Invocadores Originais\\", por terem sido os primeiros a atravessar o portão...","story.map8-dungeon4.033":"...usando os incríveis poderes de invocação que haviam adquirido...","story.map8-dungeon4.034":"...formaram uma das maiores organizações de toda Elgaia.","story.map8-dungeon4.035":"Com o imenso poder dos Invocadores, essa organização aos poucos assumiu também o controle econômico.","story.map8-dungeon4.036":"Antes que alguém percebesse, a república havia se tornado uma mera casca do que já foi.","story.map8-dungeon4.037":"Agora, tanto o Império Randall quanto a Federação de Elgaia não passam de estruturas vazias.","story.map8-dungeon4.038":"Hehe, <wait=40>pela sua cara, vejo que você já entendeu isso.","story.map8-dungeon4.039":"No entanto, <wait=40>você não parece ter problema algum com isso.","story.map8-dungeon4.040":"Claro, <wait=20>quem controla o quê não tem nada a ver com as pessoas comuns.","story.map8-dungeon4.041":"Mas não se deve encarar o mundo com tanta leveza.","story.map8-dungeon4.042":"Eu me pergunto se você continuaria ao lado do Salão dos Invocadores se conhecesse o lado sombrio dele.","story.map8-dungeon4.043":"Se você prometer se aliar a nós a partir de agora, eu te conto tudo.","story.map8-dungeon4.044":"Hehe, <wait=20>mas não precisa ter pressa.","story.map8-dungeon4.045":"Porque, aconteça o que acontecer, assim que eu puser as mãos no poder escondido aqui...","story.map8-dungeon4.046":"...você não terá escolha a não ser nos seguir em nosso caminho justo.","story.map8-dungeon4.047":"......","story.map8-dungeon4.048":"Bem, então, <wait=40>já vou indo.","story.map8-dungeon4.049":"Espero falar com você de novo, sem a interrupção daquele tolo vulgar.","story.map8-dungeon5.001":"<rep_handlename>.","story.map8-dungeon5.002":"Ei, <wait=40>o que deu em você de repente?","story.map8-dungeon5.003":"Será que você acha que foi mais forte que eu naquela última luta?","story.map8-dungeon5.004":"Parece que você não percebeu o quanto eu peguei leve com você.","story.map8-dungeon5.005":"Parece que você precisa de um lembrete.","story.map8-dungeon5.006":"Hã? <wait=40>Se eu sei do lado sombrio do Salão dos Invocadores?","story.map8-dungeon5.007":"Seu idiota, <wait=20>que história maluca você deixou aquela mulher enfiar na sua cabeça?","story.map8-dungeon5.008":"Eu te disse para não dar ouvidos àquela mulher!","story.map8-dungeon5.009":"Além disso, o que o Salão dos Invocadores faz não tem nada a ver com a gente.","story.map8-dungeon5.010":"No fundo, o que importa mesmo é quem é o mais poderoso de Elgaia.","story.map8-dungeon5.011":"Será a Federação de Elgaia e suas massas empolgadas?","story.map8-dungeon5.012":"Ou o Império Randall e seu exército antiquado?","story.map8-dungeon5.013":"Ou talvez nenhum dos dois.","story.map8-dungeon5.014":"Mas eu acho que o Salão dos Invocadores de Akras é o mais forte.","story.map8-dungeon5.015":"A elite do Salão dos Invocadores é a elite de Elgaia.","story.map8-dungeon5.016":"É simples assim.","story.map8-dungeon5.017":"E é por isso que eu preciso dar o meu melhor pelo Salão dos Invocadores.","story.map8-dungeon5.018":"Mas você ficar no meu caminho enquanto eu já estou dando duro está começando a me irritar de verdade.","story.map8-dungeon5.019":"É por isso que hoje eu não vou pegar leve com você.","story.map8-dungeon5.020":"Vou te esperar mais à frente.","story.map8-dungeon5.021":"<size=20>Vou te mostrar exatamente a diferença entre nós!</size>","story.map8-dungeon5.022":"<size=20>É melhor você se preparar!</size>","story.map8-dungeon6.001":"<rep_handlename>. <wait=40>Então você veio.","story.map8-dungeon6.002":"Olhe. <wait=40>Não é incrível?","story.map8-dungeon6.003":"Há muito tempo, aqui ficava a República de La Veda, onde as pessoas rezavam ao Deus da Luz.","story.map8-dungeon6.004":"No entanto, <wait=20>essas mesmas pessoas foram destruídas pelo próprio deus a quem rezavam.","story.map8-dungeon6.005":"Que cena terrível.","story.map8-dungeon6.006":"Existem vários registros da batalha contra os deuses.","story.map8-dungeon6.007":"O primeiro e mais importante é a lenda dos Seis Heróis.","story.map8-dungeon6.008":"No entanto, <wait=20>ainda há muito que se desconhece.","story.map8-dungeon6.009":"Em especial, <wait=20>pouco se sabe sobre o que aconteceu em Grand Gaia...","story.map8-dungeon6.010":"...depois que Lucius salvou o povo.","story.map8-dungeon6.011":"O que exatamente Lucius estava fazendo...","story.map8-dungeon6.012":"...enquanto os Quatro Deuses Caídos cometiam tanta crueldade.","story.map8-dungeon6.013":"E por que o grande líder dos deuses, Carna Masta, ainda não agiu?","story.map8-dungeon6.014":"Hehe, <wait=20>pensar nisso faz a gente se preocupar com o quanto estamos seguros de verdade.","story.map8-dungeon6.015":"Eu...","story.map8-dungeon6.016":"Não, <wait=20>nós vivemos com medo da situação atual.","story.map8-dungeon6.017":"Em tempos tão incertos como estes...","story.map8-dungeon6.018":"...quem sabe quando os deuses podem decidir destruir mais uma vez e mirar em Elgaia?","story.map8-dungeon6.019":"É por isso que precisamos pôr as mãos no grande poder que repousa aqui.","story.map8-dungeon6.020":"O poder que dizem repousar na terra onde, há muito tempo, as pessoas adoravam o Deus da Luz.","story.map8-dungeon6.021":"Hehe, <wait=40>lá está você com essa cara preocupada de novo.","story.map8-dungeon6.022":"Não há pressa. <wait=40>Por favor, leve o tempo que precisar para entender tudo isso.","story.map8-dungeon6.023":"Mas, <wait=20>também gostaria que você pensasse no futuro.","story.map8-dungeon6.024":"Qual é o caminho justo para criar um mundo onde as pessoas possam viver em paz?","story.map8-dungeon6.025":"Bem, então, <wait=20>preciso ir.","story.map8-dungeon6.026":"Ah, <wait=20>e mais uma coisa...","story.map8-dungeon6.027":"Há pouco vi o Lugina indo em direção a uma ponte negra logo à frente, com uma cara bem ameaçadora.","story.map8-dungeon6.028":"Tome cuidado, está bem?","story.map8-dungeon6.029":"Hehehe.","story.map8-dungeon7-2.001":"I-<wait=40>Impossível...","story.map8-dungeon7-2.002":"Como eu pude perder para...","story.map8-dungeon7-2.003":"Ngh...","story.map8-dungeon7-2.004":"<size=18>Isso não pode ser verdade...</size>","story.map8-dungeon7-2.005":"<size=24>Eu me recuso a aceitar!</size>","story.map8-dungeon7-2.006":"Não tem como eu perder para você!","story.map8-dungeon7-2.007":"Impossível...","story.map8-dungeon7-2.008":"<size=20>Não! <wait=40>Não! <wait=40>Não!","story.map8-dungeon7-2.009":"<size=18>Como eu pude perder...</size>","story.map8-dungeon7-2.010":"Hunf, <wait=40>o que você está olhando?","story.map8-dungeon7-2.011":"Sai logo daqui!","story.map8-dungeon7-2.012":"<size=20>Maldito seja!!</size>","story.map8-dungeon7-2.013":"Droga...","story.map8-dungeon7.001":"Cansei de esperar, <rep_handlename>.","story.map8-dungeon7.002":"Eu tinha certeza de que você passaria por aqui.","story.map8-dungeon7.003":"Parece que o que aquela mulher e eu estamos procurando fica na torre logo à frente.","story.map8-dungeon7.004":"<size=20>Argh!</size>","story.map8-dungeon7.005":"Lá vem essa cara irritante de novo!","story.map8-dungeon7.006":"Apesar dessa cara de desinteresse, você não é diferente dela, com essa curiosidade atrapalhando o meu caminho.","story.map8-dungeon7.007":"Sem saber de nada como você está, pretende mesmo ir atrás do meu troféu?","story.map8-dungeon7.008":"Você está começando a me tirar do sério.","story.map8-dungeon7.009":"Esta missão é a minha chance de mostrar àqueles velhotes o meu verdadeiro poder.","story.map8-dungeon7.010":"Não posso deixar um novato como você ficar no meu caminho!","story.map8-dungeon7.011":"Não vou deixar essa conquista ir para mais ninguém!","story.map8-dungeon7.012":"Vou esmagar qualquer um que ficar no meu caminho!","story.map8-dungeon7.013":"Ngh, <wait=20>que cara é essa! Nada de ficar com medo agora!","story.map8-dungeon7.014":"Tanto faz.","story.map8-dungeon7.015":"Este é o meu último aviso.","story.map8-dungeon7.016":"Da próxima vez que eu cruzar com você...","story.map8-dungeon7.017":"<size=22>Vai ser o seu fim!</size>","story.map8-dungeon7.018":"<size=22>Entendeu?</size>","story.map8-dungeon8.001":"Ngh...","story.map8-dungeon8.002":"Isso é inesperado, <wait=20>não achei que seria tão difícil.","story.map8-dungeon8.003":"Mas, mesmo assim, <wait=20>esses ferimentos insignificantes não vão me fazer desistir!","story.map8-dungeon8.004":"Eu preciso encontrar o portão para Eriole, custe o que custar.","story.map8-dungeon8.005":"Ei! <wait=40><rep_handlename>!","story.map8-dungeon8.006":"Não acredito que você me alcançou.","story.map8-dungeon8.007":"Se você está aqui, deve significar que conseguiu derrotar o Lugina, certo?","story.map8-dungeon8.008":"Ele pode ser meio grosseiro, <wait=20>mas, como líder dos Caçadores de Demônios, é mais do que formidável.","story.map8-dungeon8.009":"Você deve ter mesmo muito poder para conseguir derrotá-lo.","story.map8-dungeon8.010":"Ngh...","story.map8-dungeon8.011":"Hehe, <wait=20>esses ferimentos não são nada, não precisa se preocupar.","story.map8-dungeon8.012":"Só tive um pequeno contratempo.","story.map8-dungeon8.013":"Agora, mais do que nunca, meu objetivo é obter o poder oculto que aguarda aqui.","story.map8-dungeon8.014":"Nem mesmo você eu deixaria ficar no meu caminho.","story.map8-dungeon8.015":"Haha, <wait=40>que expressão assustadora.","story.map8-dungeon8.016":"Mas, mesmo assim, <wait=20>estou falando sério.","story.map8-dungeon8.017":"Acredito que o poder que repousa aqui pode restaurar o mundo ao que ele deveria ser.","story.map8-dungeon8.018":"Você sabe o que está esperando por nós aqui?","story.map8-dungeon8.019":"É uma torre que dizem existir desde antes mesmo da fundação de La Veda.","story.map8-dungeon8.020":"Talvez La Veda tenha sido construída justamente para vigiar a torre.","story.map8-dungeon8.021":"Em outras palavras, <wait=40>o que nos aguarda aqui é importantíssimo.","story.map8-dungeon8.022":"Provavelmente também há inúmeras armadilhas colocadas para protegê-lo.","story.map8-dungeon8.023":"Entende o que quero dizer?","story.map8-dungeon8.024":"Se entende, <wait=40>então é melhor não avançar mais.","story.map8-dungeon8.025":"Você não quer acabar lutando contra mim, quer?","story.map8-dungeon8.026":"Hehehe.","story.map8-dungeon8.027":"Espero que você siga meu conselho e volte.","story.map8-dungeon8.028":"Bem, então, <wait=40>já vou.","story.map8-dungeon8.029":"Conversaremos de novo quando eu tiver cumprido meu objetivo.","story.map8-dungeon8.030":"Não pense que desisti de tentar trazer você para o nosso lado.","story.map8-dungeon8.031":"Hehehe.","story.map8-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_clear.002":"Senhor! <wait=40>Você está bem?","story.map8-dungeon_ex_clear.003":"*Suspiro* <wait=20>Que alívio.","story.map8-dungeon_ex_clear.004":"Oficiais do Salão dos Invocadores investigaram mais a fundo o lago subterrâneo depois que você saiu.","story.map8-dungeon_ex_clear.005":"Parece que o deus Lagzal estava repousando lá.","story.map8-dungeon_ex_clear.006":"Ele também apareceu em Grand Gaia durante a grande batalha entre os deuses e os humanos.","story.map8-dungeon_ex_clear.007":"Segundo nossos registros, ele foi originalmente derrotado por um único herói.","story.map8-dungeon_ex_clear.008":"No entanto, parece que ele não foi completamente destruído e, em vez disso, recuou para cá.","story.map8-dungeon_ex_clear.009":"Meu coração quase parou quando encontramos essa informação.","story.map8-dungeon_ex_clear.010":"Quer dizer, ele tirou a vida de tanta gente em batalha!","story.map8-dungeon_ex_clear.011":"Fiquei tão preocupada quando descobri que você ia enfrentá-lo...","story.map8-dungeon_ex_clear.012":"......","story.map8-dungeon_ex_clear.013":"Agora é tarde demais para pedir desculpas!","story.map8-dungeon_ex_clear.014":"......","story.map8-dungeon_ex_clear.015":"*Suspiro* <wait=40>Mas você é um Invocador, afinal.","story.map8-dungeon_ex_clear.016":"De agora em diante, você vai investigar lugares cada vez mais perigosos.","story.map8-dungeon_ex_clear.017":"Se eu quero mesmo apoiar você, não devo tentar te impedir.","story.map8-dungeon_ex_clear.018":"Entendido!","story.map8-dungeon_ex_clear.019":"Eu acredito em você, senhor!","story.map8-dungeon_ex_clear.020":"E pode sempre contar comigo, senhor!","story.map8-dungeon_ex_clear.021":"Hehehe.","story.map8-dungeon_ex_clear.022":"Muito bem, entrarei em contato se chegar mais alguma informação!","story.map8-dungeon_ex_clear.023":"Por favor, cuide-se até lá!","story.map8-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bzz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_open.002":"Senhor, <wait=40>está me ouvindo?","story.map8-dungeon_ex_open.003":"Ótimo, <wait=20>desta vez consegui falar com você direto.","story.map8-dungeon_ex_open.004":"Lin Merylham, do Suporte Logístico...","story.map8-dungeon_ex_open.005":"...do Departamento de Investigação do Escritório de Pesquisa de Grand Gaia, ao seu dispor.","story.map8-dungeon_ex_open.006":"<rep_handlename>, como membro do Exército de Invocadores do Salão dos Invocadores de Akras...","story.map8-dungeon_ex_open.007":"...hoje pedimos que você investigue o Lago Subterrâneo de Golzo!","story.map8-dungeon_ex_open.008":"Há alguns dias, o Salão dos Invocadores sentiu o desaparecimento de uma grande força em Lizeria.","story.map8-dungeon_ex_open.009":"Logo depois, sentimos uma força ainda maior aqui neste lago subterrâneo.","story.map8-dungeon_ex_open.010":"Gostaríamos que você investigasse o que exatamente está acontecendo aqui.","story.map8-dungeon_ex_open.011":"Pessoalmente, tenho um mau pressentimento sobre isso, então tudo bem se você preferir recusar...","story.map8-dungeon_ex_open.012":"...mas o seu tom de voz diz o contrário.","story.map8-dungeon_ex_open.013":"Com ambição de sobra, como sempre!","story.map8-dungeon_ex_open.014":"Entendido!","story.map8-dungeon_ex_open.015":"Por mais preocupada que eu esteja, vou torcer por você como sempre!","story.map8-dungeon_ex_open.016":"Então, por favor, <wait=40>volte para mim sem nenhum arranhão!","story.map8-dungeon_ex_open.017":"Entendido?","story.map8-dungeon_ex_open.018":"Hunf...","story.map8-ending.001":"Derrubar um sistema de defesa como aquele...","story.map8-ending.002":"Acho que esse é o poder que se espera de quem derrotou um Deus Caído.","story.map8-ending.003":"Mas, mesmo assim, <wait=20>não tem como eu abrir mão do que está selado além do portão à frente!","story.map8-ending.004":"Olha só pra você, <rep_handlename>.","story.map8-ending.005":"Você nem está tão ferido assim e mesmo assim não consegue se mexer?","story.map8-ending.006":"Tsc, <wait=40>me irrita demais pensar que eu tive tanto trabalho para lidar com você.","story.map8-ending.007":"Hã? <wait=40>Como assim, correr na frente?","story.map8-ending.008":"Heh, <wait=20>ninguém te contou nada, não é?","story.map8-ending.009":"Venha comigo.","story.map8-ending.010":"Vamos ver em que tipo de encrenca interessante aquela mulher se meteu.","story.map8-ending.011":"E-<wait=20>Espera. <wait=20>Como pode não haver nada?","story.map8-ending.012":"Isso quer dizer que fomos enganados?","story.map8-ending.013":"Como pudemos ter sido...","story.map8-ending.014":"O que alguém ganharia nos enganando desse jeito?","story.map8-ending.015":"Ei, <rep_handlename>! <wait=40>Olha!","story.map8-ending.016":"É exatamente como eu disse.","story.map8-ending.017":"A senhorita Guarda Imperial parece estar meio encrencada.","story.map8-ending.018":"Lugina...","story.map8-ending.019":"Heh he he. <wait=40>Para com essa cara assustadora.","story.map8-ending.020":"Esse poder que você está procurando não está em nenhum lugar por aqui.","story.map8-ending.021":"Está nas ruínas do portão.","story.map8-ending.022":"Eu sei porque fui enviado pelos Invocadores Ancestrais para investigá-lo.","story.map8-ending.023":"Mas confesso que gostei de ouvir o seu falatório enfático.","story.map8-ending.024":"Seu imbecil vulgar.","story.map8-ending.025":"<size=20>Muá há há há!</size>","story.map8-ending.026":"Pode me encarar o quanto quiser, o portão não vai abrir.","story.map8-ending.027":"Ngh...","story.map8-ending.028":"<rep_handlename>.","story.map8-ending.029":"Como você aguenta ficar perto de um homem tão vulgar por tanto tempo?","story.map8-ending.030":"Você entende o que quero dizer, certo?","story.map8-ending.031":"Esse homem é um lixo completo!","story.map8-ending.032":"Vou ficar esperando o dia em que você aceitará meu convite.","story.map8-ending.033":"Ooh, <wait=20>que inveja! <wait=40>Eu também queria ser convidado, sabia?","story.map8-ending.034":"Se bem que seria uma pena desperdiçar meu tempo com a sua causa inútil.","story.map8-ending.035":"Ngh.","story.map8-ending.036":"Lembre-se disso.","story.map8-ending.037":"Um dia vou fazer você se arrepender de tudo o que fez.","story.map8-ending.038":"Heh, <wait=20>finalmente ela foi embora.","story.map8-ending.039":"Ei, <rep_handlename>.","story.map8-ending.040":"Por que você está com essa cara tão calma de repente?","story.map8-ending.041":"Não acha que eu te perdoei, acha?","story.map8-ending.042":"Vou ficar ainda mais poderoso do que antes.","story.map8-ending.043":"E quando isso acontecer, vou te usar o máximo que puder.","story.map8-ending.044":"Não se esqueça disso!","story.map8-ending.045":"Heh.","story.map8-ending.046":"Ah, <wait=20>e mais uma coisa...","story.map8-ending.047":"Parece que você realmente não fazia ideia do que estávamos buscando desta vez.","story.map8-ending.048":"No começo, achei que você só estava tentando me enganar para me passar a perna.","story.map8-ending.049":"Mas, no fim, parece que você era tão tolo quanto parecia!","story.map8-ending.050":"<size=20>Muá há há há!</size>","story.map8-ending.051":"A próxima conquista vai ser minha.","story.map8-ending.052":"E é bom você ser grato por tudo o que eu, o Invocador mais incrivelmente poderoso do mundo, fiz por você!","story.map8-ending.053":"Entendo, <wait=20>então o portão desapareceu.","story.map8-ending.054":"Tudo bem. <wait=20>Não precisa se desculpar.","story.map8-ending.055":"Você fez o seu melhor com uma tarefa difícil.","story.map8-ending.056":"Sim, <wait=20>cuide-se e volte em segurança.","story.map8-ending.057":"Hehehe.","story.map8-ending.058":"Parece que tudo foi exatamente como você disse.","story.map8-ending.059":"Parece que o contrato está concluído.","story.map8-ending.060":"Está na hora de nós também entrarmos em ação.","story.map8-ending.061":"Sim, <wait=40>meu mestre também aguarda a sua mobilização.","story.map8-ending.062":"Hehehe.","story.map8-ending.063":"<size=20>Vamos devolver o mundo à sua verdadeira forma!</size>","story.map8-ending.064":"<size=20>Vamos vê-lo mudar e evoluir diante dos nossos olhos!</size>","story.map8-ending.065":"<size=20>Espere e verá!</size>","story.map8-ending.066":"<size=20>Em breve, um novo herói vai nascer!</size>","story.map8-open.001":"Randall,<wait=40> capital do Império Randall.","story.map8-open.002":"Os aposentos particulares dos guarda-costas da família imperial, <wait=40>a Guarda Imperial.","story.map8-open.003":"*Toc* <wait=20>*toc*","story.map8-open.004":"Entre.","story.map8-open.005":"Com licença.","story.map8-open.006":"Ora, <wait=40> que expressão agradável. <wait=20>Imagino que tenha boas notícias para mim?","story.map8-open.007":"Sim, <wait=20>e peço desculpas pela demora.","story.map8-open.008":"Nossa investigação nos levou a crer que o portão que procuramos está em Lizeria.","story.map8-open.009":"...Lizeria.","story.map8-open.010":"Se bem me lembro, La Veda teria existido lá um dia.","story.map8-open.011":"Entendo. <wait=20>Parece que não mentiram para nós, afinal.","story.map8-open.012":"Exatamente.","story.map8-open.013":"Embora eu duvide que todas as informações que recebemos sejam precisas, acho que pelo menos esta era.","story.map8-open.014":"......","story.map8-open.015":"Gostaria de ir até lá para confirmar isso pessoalmente.","story.map8-open.016":"Tenho sua permissão para isso?","story.map8-open.017":"Pelo que sei, o Exército de Invocadores começou uma nova investigação naquela área.","story.map8-open.018":"Entendido. <wait=40>Farei o possível para terminar o mais rápido que puder.","story.map8-open.019":"É uma empreitada bem perigosa, sabia?","story.map8-open.020":"Estou disposta a me sacrificar pela verdadeira paz.","story.map8-open.021":"Conto com você.","story.map8-open.022":"Não precisa dizer essas coisas.","story.map8-open.023":"Vou garantir que tudo seja resolvido!","story.map8-open.024":"Boa sorte.","story.map8-open.025":"Quem está aí!?","story.map8-open.026":"Parece que você tem algo a dizer.","story.map8-open.027":"Estava ouvindo? <wait=40>Por que não aparece?","story.map8-open.028":"......","story.map8-open.029":"Entendo. <wait=40>Nem precisa dizer.","story.map8-open.030":"Não há tempo a perder. <wait=20>Precisamos restaurar o mundo à sua forma correta.","story.map8-open.031":"Será que aquele pessoal do Exército de Invocadores um dia vai entender...","story.map8-open.032":"...como este mundo realmente deveria ser.","story.map9-dungeon1.001":"Ei, <wait=20><rep_handlename>!","story.map9-dungeon1.002":"Então você também veio para Ryvern, <wait=20>a entrada da região de Agni. ","story.map9-dungeon1.003":"Imagino que esteja atrás do Zevalhua, <wait=20>o próximo dos Deuses Caídos. ","story.map9-dungeon1.004":"Claro que vamos te ajudar de novo desta vez, então não deve haver problema nenhum!","story.map9-dungeon1.005":"Karl! <wait=40>Nós temos nossos próprios objetivos, lembra!?","story.map9-dungeon1.006":"Não tenho a menor vontade de ajudar <rep_handlename>, <wait=20>ainda mais considerando que o Salão dos Invocadores nem pediu isso para nós.","story.map9-dungeon1.007":"Haha, <wait=20>você é sempre a mesma, hein, Seria.","story.map9-dungeon1.008":"<rep_handlename> já derrotou dois dos Quatro Deuses Caídos. ","story.map9-dungeon1.009":"Você não acha que devia pelo menos reconhecer isso?","story.map9-dungeon1.010":"Hum, <wait=20>eu reconheço o poder que isso exigiu.","story.map9-dungeon1.011":"Mas olha só essa cara de convencido!","story.map9-dungeon1.012":"Só estou dando um aviso justo, <wait=20>só isso!","story.map9-dungeon1.013":"<rep_handlename>! <wait=20>Você devia ser grato a mim!","story.map9-dungeon1.014":"Ah! <wait=20>Aí está você!","story.map9-dungeon1.015":"<rep_handlename>! <wait=20>Por que você demorou tanto?","story.map9-dungeon1.016":"Ah, <wait=20>Karl e Seria!","story.map9-dungeon1.017":"E aí, <wait=20>Deusa.","story.map9-dungeon1.018":"Ela apareceu, afinal...","story.map9-dungeon1.019":"Ei, vocês dois!","story.map9-dungeon1.020":"Vocês dois vão ajudar <rep_handlename> desta vez também, né?","story.map9-dungeon1.021":"Nós estamos atrás do Graham!","story.map9-dungeon1.022":"Não se preocupe com isso agora.","story.map9-dungeon1.023":"Ele vai acabar escapando de qualquer jeito, <wait=20>então por que vocês não ajudam desde o começo desta vez?","story.map9-dungeon1.024":"Que coisa maldosa de se dizer.","story.map9-dungeon1.025":"Ora, sua!","story.map9-dungeon1.026":"É tão divertido sair em aventuras assim com todos vocês.","story.map9-dungeon1.027":"Sinto que, não importa o quão difícil seja a luta, de algum jeito vamos conseguir superá-la, não acham?","story.map9-dungeon1.028":"Haha, <wait=20>se a Deusa diz, acho que não temos escolha.","story.map9-dungeon1.029":"Né, <wait=20>Seria?","story.map9-dungeon1.030":"Você é tão mole, Karl...","story.map9-dungeon1.031":"Enfim, <wait=20>tenho certeza de que o Lord Grahdens vai nos pedir isso de qualquer jeito, então acho que podemos ajudar. ","story.map9-dungeon1.032":"No fundo você é um doce, Seria!","story.map9-dungeon1.033":"O-<wait=20>O que deu em você!","story.map9-dungeon1.034":"Só estou ajudando porque não temos outra escolha.","story.map9-dungeon1.035":"Ha ha ha. <wait=20>Parece que chegamos a uma decisão.","story.map9-dungeon1.036":"Dito isso, estamos todos juntos nessa, <rep_handlename>!","story.map9-dungeon1.037":"Vamos dar o nosso melhor e dar uma surra nesse Zevalhua!","story.map9-dungeon1.038":"Ótimo! <wait=40>Deem o seu melhor, pessoal!","story.map9-dungeon1.039":"*Suspiro* <wait=20>Ainda não sei se isso é uma boa ideia...","story.map9-dungeon1.040":"Hmm. <wait=40>Que patético...","story.map9-dungeon2.001":"Ei, <rep_handlename>. <wait=40>Você chegou um pouco atrasado. ","story.map9-dungeon2.002":"A Deusa estava aqui agorinha mesmo.","story.map9-dungeon2.003":"Depois disso, ela começou algum tipo de briga com a Seria, <wait=20>e as duas saíram correndo na frente. ","story.map9-dungeon2.004":"Ha ha ha. <wait=40>Aquelas duas <wait=40>ficaram bem próximas, não acha?","story.map9-dungeon2.005":"Vamos nos ajudar para não perdermos para elas!","story.map9-dungeon2.006":"Que seres verdadeiramente patéticos vocês, humanos, são.","story.map9-dungeon2.007":"Quem está aí?","story.map9-dungeon2.008":"Não há necessidade de ter medo.","story.map9-dungeon2.009":"Meu nome é Mare.","story.map9-dungeon2.010":"Sou discípula de Zevalhua, o Supremo.","story.map9-dungeon2.011":"Discípula do Zevalhua?","story.map9-dungeon2.012":"Então você veio aqui para nos matar? ","story.map9-dungeon2.013":"Que desrespeito falar mal do Lord Zevalhua desse jeito...","story.map9-dungeon2.014":"É só mais um sinal da sua ignorância. Que triste...","story.map9-dungeon2.015":"Ainda assim, não me entendam mal.","story.map9-dungeon2.016":"Acabar com vocês dois não é algo pelo qual eu precisaria apostar meu nome.","story.map9-dungeon2.017":"Meu objetivo não é você, Invocador, <wait=40>mas o de cabelo azul. <wait=40>É atrás de você que eu estou.","story.map9-dungeon2.018":"Eu sou o seu alvo?","story.map9-dungeon2.019":"O que você quer de mim?","story.map9-dungeon2.020":"Pensei em fazer o papel de um deus e revelar a verdade a você. ","story.map9-dungeon2.021":"A verdade?","story.map9-dungeon2.022":"Você se deixou enganar por aquele tolo do Grahdens e agora sua vida está em desordem.","story.map9-dungeon2.023":"Ora, sua... <wait=60>O que exatamente você está tramando?","story.map9-dungeon2.024":"Você não precisa ficar desconfiado. ","story.map9-dungeon2.025":"Foram os seus anciãos que o entregaram aos cuidados de outra pessoa logo depois de encontrá-lo.","story.map9-dungeon2.026":"Você teve uma criação triste, sem nunca conhecer o calor de um pai ou de uma mãe.","story.map9-dungeon2.027":"Por isso, a você, que foi acolhido por aqueles velhos irresponsáveis...","story.map9-dungeon2.028":"...eu, uma deusa da compaixão, contarei a verdade.","story.map9-dungeon2.029":"Pare de brincadeira!","story.map9-dungeon2.030":"O que você poderia saber sobre o Ancião Grahdens!","story.map9-dungeon2.031":"Como um dos Invocadores Anciãos, ele estava sempre tão ocupado...","story.map9-dungeon2.032":"...Mas ele sempre se importou comigo!","story.map9-dungeon2.033":"Ele não é nada parecido com a pessoa que você está descrevendo, sua discípula de um Deus Caído!","story.map9-dungeon2.034":"Você é tão esperto com as palavras quanto o Grahdens. ","story.map9-dungeon2.035":"Parece que fizeram uma bela lavagem cerebral em você. ","story.map9-dungeon2.036":"Cale a boca! <wait=40>Não vou deixar você dizer mais nenhuma palavra contra ele!","story.map9-dungeon2.037":"Você é um idiota tolo e sem noção.","story.map9-dungeon2.038":"Eu lhe mostrarei o caminho.","story.map9-dungeon2.039":"Estarei esperando por você nas Ruínas de Azura, logo adiante. ","story.map9-dungeon2.040":"Venha sozinho se quiser saber a verdade.","story.map9-dungeon2.041":"<rep_handlename>, <wait=40>eu devo tudo ao Ancião Grahdens.","story.map9-dungeon2.042":"Ele pode ser meio estranho, mas é uma pessoa confiável e eu me importo muito com ele!","story.map9-dungeon2.043":"Não posso perdoar o que ela disse sobre ele. ","story.map9-dungeon2.044":"Desculpa, mas você vai ter que seguir em frente sem mim.","story.map9-dungeon2.045":"Vou para as Ruínas de Azura enfrentá-la.","story.map9-dungeon2.046":"Deixo o Zevalhua com você!","story.map9-dungeon2.047":"Eu te imploro, <rep_handlename>, <wait=20>por favor!","story.map9-dungeon3.001":"<rep_handlename>!","story.map9-dungeon3.002":"Você viu o Karl?","story.map9-dungeon3.003":"Ele me disse para ir na frente quando estávamos em Khelne, <wait=20>então eu fui, mas...","story.map9-dungeon3.004":"Ele parecia calmo, <wait=20>mas acho que na verdade estava muito abalado. ","story.map9-dungeon3.005":"Na verdade, eu nunca o tinha visto tão abalado antes.","story.map9-dungeon3.006":"Hã? <wait=40>Uma discípula do Zevalhua apareceu falando dele e do Lord Grahdens?","story.map9-dungeon3.007":"Entendo.","story.map9-dungeon3.008":"O Lord Grahdens é uma pessoa muito importante para o Karl.","story.map9-dungeon3.009":"Vocês são amigos desde crianças, né? <wait=40>Você conhece a história toda, não conhece?","story.map9-dungeon3.010":"Mesmo assim, <wait=40>o Karl realmente não gosta de falar de si mesmo, né...","story.map9-dungeon3.011":"Se ele simplesmente nos contasse o que está acontecendo, <wait=20>talvez pudéssemos ajudar.","story.map9-dungeon3.012":"Enfim, <wait=20>vamos nos apressar e chegar às Ruínas de Azura!","story.map9-dungeon3.013":"Tenho certeza de que o Karl está bem, mas não consigo deixar de me preocupar.","story.map9-dungeon3.014":"Você é bem atenciosa <wait=40>para um verme como você.","story.map9-dungeon3.015":"Ele já é nosso.","story.map9-dungeon3.016":"Ele não vai mais voltar para vocês. ","story.map9-dungeon3.017":"Então você é a Mare!","story.map9-dungeon3.018":"Humanos tolos. <wait=40>Vocês têm medo de ver a verdade?","story.map9-dungeon3.019":"Se for o caso, então venham também.","story.map9-dungeon3.020":"Vocês deviam vê-lo agora que ele aceitou a verdade.","story.map9-dungeon3.021":"Já chega!","story.map9-dungeon3.022":"Tilith!","story.map9-dungeon3.023":"Hehe, <wait=20>é a primeira vez que você me chama pelo nome.","story.map9-dungeon3.024":"S-<wait=20>Sua boba! <wait=40>Não é hora para isso!","story.map9-dungeon3.025":"Você tem razão. <wait=20>Temos que fazer alguma coisa a respeito da Mare.","story.map9-dungeon3.026":"Que assunto uma deusa de baixo nível como você tem comigo?","story.map9-dungeon3.027":"Que maldade!","story.map9-dungeon3.028":"Eu sou a maravilhosa discípula do Lord Lucius, sabia?!","story.map9-dungeon3.029":"Mais uma coisa, Seria. <wait=20>Não se deixe enganar.","story.map9-dungeon3.030":"A Mare é boa em confundir o coração dos outros. ","story.map9-dungeon3.031":"Há muito pouca verdade no que ela diz.","story.map9-dungeon3.032":"E você é capaz de decidir o que é verdade ou não?","story.map9-dungeon3.033":"Você, <wait=20>que segue cegamente cada palavra do Lucius, <wait=20>emprestando seus poderes aos humanos e coisas do tipo.","story.map9-dungeon3.034":"Está tentando dizer que o Lord Lucius está errado?","story.map9-dungeon3.035":"Não importa. <wait=40>Não há o que fazer quando se lida com divindades tão tolas. ","story.map9-dungeon3.036":"Estou falando de você, sabia?","story.map9-dungeon3.037":"Se quer saber a verdade, basta acreditar no que eu digo.","story.map9-dungeon3.038":"E, ao fazer isso, você poderá ver aquele homem mais uma vez. ","story.map9-dungeon3.039":"Espera um pouco!","story.map9-dungeon3.040":"Credo! <wait=40>Ela é tão desagradável quanto eu tinha ouvido falar!","story.map9-dungeon3.041":"Seria! <wait=20>Tenho certeza de que o Karl está bem!","story.map9-dungeon3.042":"Então não faça nada precipitado!","story.map9-dungeon3.043":"Eu sei. <wait=40>Já estou bem.","story.map9-dungeon3.044":"Mas, mesmo assim, estou preocupada com o Karl.","story.map9-dungeon3.045":"Sei que pode ser uma armadilha...","story.map9-dungeon3.046":"...mas o Karl com certeza está a caminho de lá agora.","story.map9-dungeon3.047":"<rep_handlename>, quero que você faça o máximo de barulho que puder por aqui.","story.map9-dungeon3.048":"Vou precisar de uma distração se quiser chegar logo até o Karl. ","story.map9-dungeon3.049":"É, <wait=20>você parece mesmo estar bem!","story.map9-dungeon3.050":"Até esse jeito de quem está tentando tratar <rep_handlename> com crueldade combina com você!","story.map9-dungeon3.051":"Eu não estou fingindo nada!","story.map9-dungeon3.052":"*Suspiro* <wait=40>Enfim, chega disso.","story.map9-dungeon3.053":"Tilith, <wait=20>proteja <rep_handlename> por mim.","story.map9-dungeon3.054":"Quem sabe o que aquela discípula, a Mare, pode tentar.","story.map9-dungeon3.055":"Não consigo imaginá-la deixando em paz alguém que já derrotou dois dos Quatro Deuses Caídos.","story.map9-dungeon3.056":"Entendido. <wait=40>Porém, <wait=20>por favor, não faça nada imprudente.","story.map9-dungeon3.057":"Não se preocupe comigo.","story.map9-dungeon3.058":"Não sou tão fraca a ponto de uma deusa tola como você precisar se preocupar comigo.","story.map9-dungeon3.059":"Sem nenhuma modéstia, como sempre, hein, Seria!","story.map9-dungeon3.060":"Hehe, <wait=40>enfim, já vou indo.","story.map9-dungeon3.061":"<rep_handlename>, <wait=40>você também se cuide, tá?","story.map9-dungeon4.001":"<rep_handlename>...","story.map9-dungeon4.002":"Desculpa...","story.map9-dungeon4.003":"A Mare...<wait=20> Ela nos enganou...","story.map9-dungeon4.004":"Seria! <wait=40>Você está bem?","story.map9-dungeon4.005":"Eu estou...<wait=40>bem...","story.map9-dungeon4.006":"Mas...<wait=20>o Karl...","story.map9-dungeon4.007":"Não se force!","story.map9-dungeon4.008":"A Mare...<wait=20>e o Karl estavam...<wait=20>em pé de igualdade...","story.map9-dungeon4.009":"Pensei em tentar ajudar...","story.map9-dungeon4.010":"Porém, <wait=40>parece que era...<wait=20>exatamente isso que ela queria...","story.map9-dungeon4.011":"No momento em que me concentrei nela...","story.map9-dungeon4.012":"Ela chamou os capangas que estavam escondidos. <wait=20>Todos vieram para cima de mim de uma vez...","story.map9-dungeon4.013":"Então, bem quando eu tentava desviar dos ataques deles...<wait=20>a Mare me atacou pelas costas...","story.map9-dungeon4.014":"O Karl...<wait=20>ele me protegeu <wait=20>do ataque dela...","story.map9-dungeon4.015":"Depois, <wait=20>enquanto eu tentava proteger o Karl depois que ele caiu, <wait=20>isto aconteceu...","story.map9-dungeon4.016":"Seria...","story.map9-dungeon4.017":"Ela me disse...","story.map9-dungeon4.018":"\\"Vou deixar você como uma mensagem para <rep_handlename>...","story.map9-dungeon4.019":"...É o único motivo pelo qual estou deixando você viver.\\"","story.map9-dungeon4.020":"Fui tão tola!","story.map9-dungeon4.021":"Não só caí na armadilha dela, como agora isto. <wait=20>Como vou viver com tamanha vergonha. ","story.map9-dungeon4.022":"Mesmo assim, fico feliz em ouvir isso.","story.map9-dungeon4.023":"Feliz em ouvir o quê!","story.map9-dungeon4.024":"Você está viva, não está? <wait=20>Só estou feliz que você ainda esteja aqui.","story.map9-dungeon4.025":"Tilith...","story.map9-dungeon4.026":"E, se o Karl foi capturado, <wait=20>quer dizer que ele também ainda está vivo!","story.map9-dungeon4.027":"Com certeza o meu <rep_handlename> consegue salvá-lo!","story.map9-dungeon4.028":"Não gosto do jeito que você chama <rep_handlename> de seu, <wait=20>nem de como você confia tão cegamente...","story.map9-dungeon4.029":"Mas...<wait=20>você tem razão...","story.map9-dungeon4.030":"Parece que o Karl está sendo mantido em um lugar chamado Torre Branca. ","story.map9-dungeon4.031":"A Mare disse que vai esperar por você lá.","story.map9-dungeon4.032":"Isto sem dúvida é uma armadilha.","story.map9-dungeon4.033":"Mas, mesmo assim, eu te imploro que tente.","story.map9-dungeon4.034":"<size=20><rep_handlename>, <wait=40>salve o Karl!</size>","story.map9-dungeon4.035":"Hum, <wait=20>que história é essa de só acenar com a cabeça e bancar o descolado?","story.map9-dungeon4.036":"Você iria salvá-lo mesmo que eu não dissesse nada, né?","story.map9-dungeon4.037":"Ngh...","story.map9-dungeon4.038":"Seria! <wait=20>Não se force!","story.map9-dungeon4.039":"<rep_handlename>! <wait=40>Deixe a Seria comigo!","story.map9-dungeon4.040":"Vou levá-la em segurança de volta para Elgaia. ","story.map9-dungeon4.041":"Então, por favor, <rep_handlename>, <wait=20>vá resgatar o Karl.","story.map9-dungeon4.042":"A Seria e eu <wait=20>acreditamos em você, <rep_handlename>.","story.map9-dungeon4.043":"Eu não necessariamente acredito em você...","story.map9-dungeon4.044":"Seria, <wait=20>tudo bem.","story.map9-dungeon4.045":"O meu <rep_handlename> é o mais forte que existe!","story.map9-dungeon4.046":"Quem você está chamando de seu?","story.map9-dungeon4.047":"Ah, <wait=40>tanto faz...","story.map9-dungeon4.048":"<rep_handlename>...","story.map9-dungeon4.049":"Por favor...<wait=40>traga o Karl de volta para mim...","story.map9-dungeon5.001":"<rep_handlename>. <wait=40>Eu estava esperando por você.","story.map9-dungeon5.002":"Achei que você passaria por aqui a caminho da Torre Branca.","story.map9-dungeon5.003":"A Torre Branca fica do outro lado das Montanhas de Ryvern, <wait=20>logo depois da saída da caverna. ","story.map9-dungeon5.004":"Duvido que seja fácil passar, mesmo com as suas habilidades.","story.map9-dungeon5.005":"Porém, <wait=20>não tema. ","story.map9-dungeon5.006":"Eu vou salvar aquele jovem Karl.","story.map9-dungeon5.007":"Afinal, ele é meu amado filho. ","story.map9-dungeon5.008":"Ho ho ho. <wait=40>Por que essa cara de desconfiança?","story.map9-dungeon5.009":"Não faço ideia do que aquela discípula, a Mare, disse.","story.map9-dungeon5.010":"Mas fui eu quem pegou aquele bebê abandonado e o criou como se fosse meu.","story.map9-dungeon5.011":"Dito isso, <wait=20>é verdade que, com o tempo, eu o deixei aos cuidados de um conhecido de confiança. ","story.map9-dungeon5.012":"A vida de um Invocador Ancião é agitada demais.","story.map9-dungeon5.013":"Mas você conhece o resto da história, não conhece?","story.map9-dungeon5.014":"Sou grato a você por sempre ter brincado com o Karl quando vocês eram crianças. ","story.map9-dungeon5.015":"Ho ho ho.","story.map9-dungeon5.016":"Porém, não importava o quão ocupado eu ficasse...","story.map9-dungeon5.017":"...eu jamais simplesmente o deixaria com outra pessoa e pronto.","story.map9-dungeon5.018":"De vez em quando, eu escapava sem ninguém perceber para ver como ele estava. ","story.map9-dungeon5.019":"Eu teria me metido em muitos problemas se alguém soubesse que eu, um Invocador Ancião, tinha um filho.","story.map9-dungeon5.020":"Porém, <wait=20>mesmo tendo que agir às escondidas, ainda assim fui aceito em troca.","story.map9-dungeon5.021":"Ho ho ho. <wait=40>Que nostalgia.","story.map9-dungeon5.022":"Bem, então <wait=20>acho que devo seguir meu caminho.","story.map9-dungeon5.023":"Trazer de volta um filho perdido é responsabilidade dos pais.","story.map9-dungeon5.024":"Além disso, <wait=20>preciso punir quem ousou enganar meu querido filho.","story.map9-dungeon5.025":"Ho ho ho. <wait=20>Não se preocupe.","story.map9-dungeon5.026":"Posso ter envelhecido, <wait=20>mas provavelmente ainda sou muitas vezes mais forte que qualquer um de vocês.","story.map9-dungeon5.027":"Além disso, <wait=20>mesmo que algo aconteça comigo...","story.map9-dungeon5.028":"...pedi aos outros Invocadores Anciãos que cuidassem de todos vocês. ","story.map9-dungeon5.029":"Ho ho ho. <wait=40>Será que estou sendo cauteloso demais?","story.map9-dungeon5.030":"Não tema, e siga rumo ao Zevalhua.","story.map9-dungeon5.031":"Tenho certeza de que o Karl também não quer te atrasar.","story.map9-dungeon5.032":"Mas, mesmo assim, você ainda pretende ir para a Torre Branca, não é?","story.map9-dungeon5.033":"O Karl tem amigos muito bons. ","story.map9-dungeon5.034":"Bem, então <wait=20>vou salvar o Karl e depois esperar por você na Torre Branca. ","story.map9-dungeon5.035":"Ho ho ho.","story.map9-dungeon6.001":"Parece que agora só resta um. ","story.map9-dungeon6.002":"Parece que vocês, humanos, são mesmo seres tolos. ","story.map9-dungeon6.003":"Vou destruir você assim como fiz com o resto daqueles guerreiros tolos.","story.map9-dungeon6.004":"<size=20>Eu não vou deixar isso acontecer!</size>","story.map9-dungeon6.005":"Eu vou proteger <rep_handlename>!","story.map9-dungeon6.006":"É você...","story.map9-dungeon6.007":"Você voltou muito mais cedo do que eu imaginava.","story.map9-dungeon6.008":"Eu chamaria você de tola, <wait=20>mas o que mais eu poderia esperar de uma discípula do Lucius.","story.map9-dungeon6.009":"Enfim...","story.map9-dungeon6.010":"Invocador, <wait=40>estarei esperando por você na Torre Branca.","story.map9-dungeon6.011":"Seu amigo também estará comigo.","story.map9-dungeon6.012":"<rep_handlename>, você está bem?","story.map9-dungeon6.013":"Se você está preocupado com a Seria, não precisa ficar.","story.map9-dungeon6.014":"Eu a levei em segurança de volta para Elgaia, e agora ela está descansando tranquila no Salão dos Invocadores. ","story.map9-dungeon6.015":"Então, <wait=20>vamos salvar o Karl juntos!","story.map9-dungeon6.016":"Você e eu conseguimos, <wait=20>não importa quantas armadilhas a Mare prepare!","story.map9-dungeon6.017":"Não existe inimigo que não possamos vencer enquanto estivermos juntos!","story.map9-dungeon6.018":"Karl! Aguente só mais um pouquinho!","story.map9-dungeon7.001":"Apesar de ser tão iluminado, este lugar me dá arrepios.","story.map9-dungeon7.002":"Será outra armadilha da Mare?","story.map9-dungeon7.003":"Não preciso desperdiçar nenhuma das minhas preciosas armadilhas com vocês.","story.map9-dungeon7.004":"É a voz da Mare!","story.map9-dungeon7.005":"Preparei um oponente para vocês.","story.map9-dungeon7.006":"Granvalm, guardião desta torre. <wait=40>Destrua estes intrusos!","story.map9-dungeon7.007":"<size=20>Kyaaaahh! <wait=40>Olha aquele dragão!</size>","story.map9-dungeon7.008":"Ele deve ser o adversário perfeito para uma dupla de tolos como vocês.","story.map9-dungeon7.009":"Espera!","story.map9-dungeon7.010":"Agora eu fiquei brava de verdade! <wait=40><rep_handlename>, para trás!","story.map9-dungeon7.011":"Ha ha ha...","story.map9-dungeon7.012":"Eles fugiram...","story.map9-dungeon7.013":"Porém, <wait=20>parecia que aquele dragão estava voltando correndo para proteger alguma coisa...","story.map9-dungeon7.014":"Talvez ele quisesse garantir que o Karl não escapasse.","story.map9-dungeon7.015":"<rep_handlename>!","story.map9-dungeon7.016":"Com certeza é isso!","story.map9-dungeon7.017":"Vá atrás daquele dragão, eu vou ficar bem!","story.map9-dungeon7.018":"Só preciso descansar aqui um pouquinho!","story.map9-dungeon7.019":"Temos que fazer valer a confiança que a Seria tem em nós.","story.map9-dungeon7.020":"Isso não vai ser problema nenhum para o meu <rep_handlename>!","story.map9-dungeon7.021":"Cumpra sua promessa à Seria e resgate o Karl!","story.map9-ending.001":"Invocador. <wait=40>Parece que você ainda está de pé.","story.map9-ending.002":"Relaxe. <wait=40>Vou garantir que o seu fim seja rápido e indolor.","story.map9-ending.003":"Depois de você, não restará ninguém para ameaçar o Lord Zevalhua. ","story.map9-ending.004":"Por que essa cara de surpresa?","story.map9-ending.005":"Eu estava mirando em você desde o começo.","story.map9-ending.006":"Você, o Invocador escolhido pelo Lucius.","story.map9-ending.007":"Agora que eliminei todos aqueles que um dia o protegeram...","story.map9-ending.008":"...não resta ninguém para salvá-lo.","story.map9-ending.009":"Até o velho foi derrotado lutando para salvar alguém que nem sequer estava aqui.","story.map9-ending.010":"Além disso, <wait=20>o poder daquela deusa tola que depositou a fé em você também se esgotou.","story.map9-ending.011":"Não importa quantos discípulos o Lucius envie.","story.map9-ending.012":"Certamente eles entendem que, fracos como são, o dragão branco simplesmente os deixará imóveis.","story.map9-ending.013":"Ele ficou tolo depois de passar tanto tempo no meio de vocês, humanos.","story.map9-ending.014":"Vocês, vermes humanos, são realmente lamentáveis.","story.map9-ending.015":"Vocês se empolgam fácil e depois agem por conta própria.","story.map9-ending.016":"Mesmo sabendo que é uma armadilha, dizem que é para salvar os amigos enquanto arrastam outros para a encrenca junto. ","story.map9-ending.017":"Agir sozinho quando se é responsável por tanta coisa só leva ao fracasso. ","story.map9-ending.018":"Além disso, <wait=20>quem tem grandes objetivos e se concentra nos pequenos acaba perdendo tudo.","story.map9-ending.019":"Que jeito tolo de viver.","story.map9-ending.020":"Certamente você não é diferente.","story.map9-ending.021":"Invocador...","story.map9-ending.022":"Hum, <wait=40>fiquei entediada.","story.map9-ending.023":"Falei achando que você poderia oferecer alguma resistência, mas parece que já chegou ao seu limite.","story.map9-ending.024":"Tudo bem. <wait=40>Parece que vou ter que acabar com você aqui mesmo!","story.map9-ending.025":"<size=20>Pare aí mesmo!</size>","story.map9-ending.026":"......","story.map9-ending.027":"......","story.map9-ending.028":"Parece que você ainda tem alguns aliados.","story.map9-ending.029":"Mas isso não importa.","story.map9-ending.030":"O homem que você procura está sendo mantido na capital de Agni. ","story.map9-ending.031":"É melhor ir atrás dele se quiser salvá-lo.","story.map9-ending.032":"E você não tem tempo para esperar seus amigos se recuperarem.","story.map9-ending.033":"Se esperar, será tarde demais para salvá-lo.","story.map9-ending.034":"......","story.map9-ending.035":"Ei, <rep_handlename>, <wait=20>não fique aí parado!","story.map9-ending.036":"Podemos conversar depois. <wait=40>Por enquanto, devíamos seguir rumo à capital de Agni.","story.map9-ending.037":"Tenho uma coisa para te contar quando chegarmos lá.","story.map9-ending.038":"Você devia ser grato a mim!","story.map9-ending.039":"<size=20>Ah ha ha ha!</size>","story.map9-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Eu sou Lucius...<br><wait=40>Deus deste Portal...","story.map9-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>A crise trazida pelos Quatro Deuses Caídos<wait=40> ainda persiste...","story.map9-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use meu poder <wait=40>e desbrave novas terras...","story.map9-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Para trazer nova esperança a este mundo sem ordem...","story.map9-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Você precisa ter fé no seu poder <wait=20>e continuar avançando...","story.map9-open.006":"<rep_handlename>! <wait=40>Desculpa a demora!","story.map9-open.007":"Mas, como eu estou sempre esperando por você, <rep_handlename>...","story.map9-open.008":"...pensei que desta vez seria você quem ia esperar!","story.map9-open.009":"O quê? <wait=20>Você diz que nem esperou tanto assim?","story.map9-open.010":"Isso não é justo!","story.map9-open.011":"Eu esperava que você pelo menos suasse um pouco esperando por mim!","story.map9-open.012":"Mas tanto faz! <wait=40>O importante é derrotarmos logo o próximo Deus Caído!","story.map9-open.013":"Só resta metade dos Quatro Deuses Caídos!","story.map9-open.014":"E o próximo que você vai desafiar é...","story.map9-open.015":"...o grande imperador Zevalhua, que controla a região de Agni. ","story.map9-open.016":"Dizem que ele não se dá bem com Afla Dilith, outro dos Deuses Caídos...","story.map9-open.017":"...mas com certeza ele já percebeu a nossa chegada.","story.map9-open.018":"Ele provavelmente vai tentar armar armadilhas para nós!","story.map9-open.019":"Mas não é como se você fosse cair nelas, né, <rep_handlename>?","story.map9-open.020":"Muito bem, então <wait=20>vou seguir rumo a Mirvana, onde o Zevalhua está esperando!","story.map9-open.021":"Randall,<wait=40> capital do Império de Randall.","story.map9-open.022":"Castelo de Randall, dentro dos aposentos privativos dos guarda-costas da família real, <wait=40>a Guarda Imperial.","story.map9-open.023":"*Toc* <wait=20>*toc*","story.map9-open.024":"Com licença.","story.map9-open.025":"......","story.map9-open.026":"Os preparativos para partir rumo à região de Agni estão concluídos. ","story.map9-open.027":"É mesmo.","story.map9-open.028":"Bem, então vamos seguir caminho também. ","story.map9-open.029":"Para Grand Gaia, a terra controlada pelos deuses. ","storylog.category.10000.description":"Viajando por Grand Gaia, cooperando com amigos e com uma deusa poderosa, um Invocador enfrenta demônios em batalhas ferozes.","storylog.category.10000.name":"Memórias de Grand Gaia","storylog.category.10100.description":"Guiado por Tilith, serva do deus Lucius, o Invocador começa uma grande aventura. Os Quatro Deuses Caídos precisam ser derrotados, a começar por Maxwell.","storylog.category.10100.name":"Mistral","storylog.category.10101.description":"Uma ilha outrora habitada por gigantes parece ser a próxima parada do Invocador. Porém, Paris, da Guarda Imperial, também segue rumo a Cordelica...","storylog.category.10101.name":"Cordelica","storylog.category.10102.description":"O Invocador chega à terra que Cardes, o Malévolo, quer destruir. Uma nova batalha começa onde um dia estiveram os lendários 4 Heróis de Palmyna.","storylog.category.10102.name":"Palmyna","storylog.category.10103.description":"Paris chega à ilha da antiga República de La Veda em busca de um portão de que falam os boatos, mas o Salão dos Invocadores já começou a investigar.","storylog.category.10103.name":"Lizeria","storylog.category.10104.description":"Zevalhua, o Supremo, precisa ser derrotado antes que destrua tudo. Dizem que ele está em conflito com Afla Dilith, um dos Quatro Deuses Caídos.","storylog.category.10104.name":"Região de Agni","storylog.category.11001.description":"Enquanto Karl persegue o demônio Graham, o Invocador decide desafiar o discípulo de Maxwell, Abaddon. Mas será que Abaddon pode mesmo ser derrotado?","storylog.category.11001.name":"Morgan","storylog.category.11002.description":"A terra sob a jurisdição da Criadora Maxwell é o novo destino. O objetivo é seguir com Tilith até a fortaleza de Maxwell, o Palácio de St. Lamia.","storylog.category.11002.name":"St. Lamia","storylog.category.11010.description":"O Invocador pousa onde o grande Império de Amdahl um dia prosperou. Tilith espera que esta jornada termine com a derrota de Cardes, o Malévolo.","storylog.category.11010.name":"Amdahl","storylog.category.11011.description":"Segundo Tilith, esta terra já testemunhou uma guerra civil humana. Batalhas intensas começam a eclodir em meio às terras selvagens.","storylog.category.11011.name":"Encervis","storylog.category.11040.description":"Zevalhua, o Supremo, se tornou o novo alvo. Tilith comenta que teme que haja uma trama em andamento.","storylog.category.11040.name":"Ryvern","storylog.category.11041.description":"A terra onde um dia se ergueu um império agora recebe a visita do Invocador. Grahdens confiou a você e a Lugina o resgate de Karl, mas...","storylog.category.11041.name":"Agni","storylog.category.11042.description":"Depois de finalmente chegar à fortaleza de Zevalhua, é hora de este antigo campo de batalha dar lugar a uma nova luta para resgatar Grahdens, que foi capturado.","storylog.category.11042.name":"Mirvana","storylog.category.20000.description":"O Invocador é chamado para desbravar uma terra misteriosa recém-descoberta. Porém, os inimigos à espera são muito mais fortes do que se imaginava...","storylog.category.20000.name":"Uma Nova Região","storylog.scenario.10001.description":"Tilith explica a situação de Grand Gaia na Caverna das Chamas. O Invocador precisa embarcar numa longa jornada para derrotar os Quatro Deuses Caídos...","storylog.scenario.10001.title":"Início da Jornada","storylog.scenario.10002.description":"No Campo Nevado de Egor, Tilith fala da importância dos Elementos das Unidades. Trovão vence Água etc... Algo bom de considerar nas próximas lutas.","storylog.scenario.10002.title":"Compatibilidade de Unidades","storylog.scenario.10003.description":"O Invocador chega à Floresta das Feras, onde inimigos caçam animais selvagens para comer. Aqui também é explicado com cuidado o uso das Esferas.","storylog.scenario.10003.title":"Equipamento Importa","storylog.scenario.10004.description":"A umidade dos Pântanos de Magutagal deixa Tilith de mau humor, mas ela explica os Sparks criados por vários ataques sincronizados.","storylog.scenario.10004.title":"Técnica de Batalha","storylog.scenario.10005.description":"Tilith fica impressionada por o Invocador ter chegado em segurança aos Restos de Mirza. Como recompensa, ela explica as vantagens das Habilidades de Líder.","storylog.scenario.10005.title":"Liderança","storylog.scenario.10006.description":"Dizem que um espadachim misterioso ronda o Ninho de Monstros. Tilith jura que não está com medo, mas parece bem assustada...","storylog.scenario.10006.title":"Não Estou com Medo!","storylog.scenario.10007.description":"Agora na Torre de Mistral, a libertação de toda a região está a um passo. Porém, a Criadora Maxwell construiu um oponente bem aterrorizante...","storylog.scenario.10007.title":"Mistral Libertada","storylog.scenario.10008.description":"O Invocador derrota o Juggernaut e recebe os elogios de Tilith. Lucius agora abrirá o caminho rumo à terra desconhecida de Morgan.","storylog.scenario.10008.title":"Rumo a Novas Terras","storylog.scenario.10009.description":"Procurando Tilith, nosso Invocador entra no Deserto de Kagan. Um encontro casual com Karl revela que ele está atrás do demônio Graham.","storylog.scenario.10009.title":"Reencontro com Karl","storylog.scenario.10010.description":"Na Praia da Brisa, Tilith ouve falar de uma espadachim linda, porém indiferente. Mas ela tem certeza de que é muito mais bonita que essa tal beldade.","storylog.scenario.10010.title":"Bela Espadachim","storylog.scenario.10011.description":"Karl se fere ao perseguir Graham. Dizem que a Floresta Noturna é território de um dos subordinados de Graham, que vem atacando muitos Invocadores.","storylog.scenario.10011.title":"O Subordinado de Graham","storylog.scenario.10012.description":"Karl consegue expulsar Graham da Floresta Noturna. Sem ter para onde fugir, é hora de resolver tudo nos Ermos de Asekutt.","storylog.scenario.10012.title":"A Perseguição de Karl","storylog.scenario.10013.description":"Seria, membro dos Caçadores de Demônios, aparece no Santuário de Lystia. Segundo ela, Graham é um dos lacaios mais estimados de Abaddon.","storylog.scenario.10013.title":"Abaddon & Graham","storylog.scenario.10014.description":"Seria fica hostil com o Invocador. Karl quer seguir até a Catedral Destruída como um trio, mas Seria não está facilitando...","storylog.scenario.10014.title":"Recusa","storylog.scenario.10015.description":"Ao enfim chegar à fortaleza de Abaddon na Torre de Morgan, Karl e Seria repelem os inimigos para ajudar o Invocador a avançar.","storylog.scenario.10015.title":"Pelos Meus Companheiros","storylog.scenario.10016.description":"Abaddon foi derrotado. Depois de reencontrar Karl e se despedir de novo, Tilith e o Invocador seguem para St. Lamia em busca de Maxwell.","storylog.scenario.10016.title":"Rumo à Base Inimiga","storylog.scenario.10017.description":"No Vulcão Eldent, Tilith avisa que negligenciar os próprios deveres é inaceitável. Ela diz que nunca fez corpo mole no trabalho, mas...","storylog.scenario.10017.title":"Nada de Corpo Mole!","storylog.scenario.10018.description":"Tilith tenta contar a história do Monte Sagrado Craylia, mas não parece muito bem. Pelo jeito, ela pegou um resfriado...","storylog.scenario.10018.title":"Mau Presságio","storylog.scenario.10019.description":"Na Floresta de Sangue, Tilith se esforça para fingir que seu estado não está piorando. Mas está na cara que isso está cobrando seu preço...","storylog.scenario.10019.title":"Blefe","storylog.scenario.10020.description":"No Monte Wistorea, Tilith enfim confessa seu mal-estar. A maldição de Maxwell a afeta ainda mais conforme ela se aproxima do Palácio de St. Lamia.","storylog.scenario.10020.title":"A Maldição","storylog.scenario.10021.description":"No Santuário Recluso, Tilith finalmente desmaia. Deixando-a aos cuidados de Seria, o Invocador segue sozinho ao Palácio de St. Lamia para acabar com a maldição.","storylog.scenario.10021.title":"Uma Promessa","storylog.scenario.10022.description":"Depois de ser resgatado por Karl, o Invocador vai atrás de Maxwell no Palácio de St. Lamia. Será que Tilith pode mesmo ser salva dessa terrível maldição?!","storylog.scenario.10022.title":"Algo a Proteger","storylog.scenario.10023.description":"Com a maldição quebrada, Tilith volta ao normal, mas de algum jeito acaba numa discussão dramática com Seria...","storylog.scenario.10023.title":"A Queda da Criadora","storylog.scenario.10100.description":"Ao saber que o Salão dos Invocadores de Akras abriu a região sul de Mistral, Eriole envia Paris a Cordelica...","storylog.scenario.10100.title":"O Plano Começa","storylog.scenario.10101.description":"Um encontro com o Caçador de Demônios Lugina acontece nas Cavernas de Greskya. Sem respeito algum pelo Exército Regular, ele exige que o Invocador vá embora.","storylog.scenario.10101.title":"Caçador de Demônios Lugina","storylog.scenario.10102.description":"Nas Cataratas de Ignia, Lugina explica como o Império Randall e o Salão dos Invocadores de Akras influenciam a vida em Elgaia.","storylog.scenario.10102.title":"Assuntos de Elgaia","storylog.scenario.10103.description":"Na Floresta de Lomass, Lugina explica como funciona o Exército de Invocadores. E, como elite, exige que o Invocador respeite sua autoridade.","storylog.scenario.10103.title":"O Exército de Invocadores","storylog.scenario.10104.description":"Paris aparece na Fortaleza de Valtan. Ela pede a cooperação do Invocador no levantamento de Cordelica, mas...","storylog.scenario.10104.title":"O Pedido de Paris","storylog.scenario.10105.description":"A caminho da Torre da Luz, Paris comenta que o Invocador é amigo de Karl, mas Lugina não acredita. Ele não parece gostar muito de Karl.","storylog.scenario.10105.title":"Que Esnobe!","storylog.scenario.10106.description":"Na Mina de Cordelica, Paris explica que uma raça de gigantes habitava a ilha há muito tempo. Parece que o deus dos gigantes também despertou.","storylog.scenario.10106.title":"Um Deus Gigante","storylog.scenario.10107.description":"Enquanto Lugina parte em missão para derrotar o deus gigante Grantos nas Ruínas do Gigante, Paris pede ao Invocador que mostre o que é poder de verdade.","storylog.scenario.10107.title":"Lugina Entusiasmado","storylog.scenario.10108.description":"Ao saber que o Invocador derrotou Grantos, Eriole ri e proclama que o mundo está seguindo na direção certa...","storylog.scenario.10108.title":"Os Motivos de Eriole","storylog.scenario.10200.description":"Lucius guia o Invocador até o Arquipélago de Palmyna, enquanto um certo homem em Randall é informado de que a barreira sobre essas ilhas sumiu.","storylog.scenario.10200.title":"Supervisor dos Cavaleiros","storylog.scenario.10201.description":"O próximo alvo é Cardes, o Malévolo, outro dos Quatro Deuses Caídos. Na Vila de Julep, você ouve que metade do poder dele ainda está selada.","storylog.scenario.10201.title":"Cardes, o Malévolo","storylog.scenario.10202.description":"Tilith diz não estar com medo a bordo do Navio Fantasma Legnia. Mesmo assim, ela dá algumas informações sobre Palmyna, onde Cardes está selado...","storylog.scenario.10202.title":"Caminho para Palmyna","storylog.scenario.10203.description":"O Invocador é atacado de repente por um homem estranho nas Planícies de Elios. Mas a presença desse homem misterioso some tão rápido quanto surgiu.","storylog.scenario.10203.title":"Um Homem Misterioso","storylog.scenario.10204.description":"Um encontro com Seria e Karl nas Minas de Saji revela que eles ainda estão atrás de Graham. Karl alerta o Invocador sobre alguém chamado Zebra.","storylog.scenario.10204.title":"O Nome Dele é Zebra","storylog.scenario.10205.description":"Tilith e seu Invocador encontram o \\"Elder Grah\\" no Templo de Lamellia. O velho diz estar investigando o folclore ligado aos Quatro Deuses Caídos.","storylog.scenario.10205.title":"Um Ancião Misterioso","storylog.scenario.10206.description":"Karl e Seria encurralam Graham na Cidade Fantasma Edila, mas são lançados longe por uma força poderosa e desconhecida, e Graham escapa.","storylog.scenario.10206.title":"Força Desconhecida","storylog.scenario.10207.description":"Aparecendo no Castelo de Amdahl, Elder Grah fala do espírito vingativo do último imperador de Amdahl, que aparentemente ainda ronda o castelo.","storylog.scenario.10207.title":"O Último Imperador de Amdahl","storylog.scenario.10208.description":"Elder Grah fica impressionado com a capacidade do Invocador de vencer o espírito maligno. Seria chega correndo, e parece que ela conhece o ancião de algum jeito.","storylog.scenario.10208.title":"Seria & Elder Grah","storylog.scenario.10209.description":"Guiado por Lucius, o Invocador chega a Encervis. Segundo Tilith, uma guerra civil humana devastou esta terra há muito tempo.","storylog.scenario.10209.title":"Ruínas do Passado","storylog.scenario.10210.description":"Ao chegar à Cratera de Elsta, Tilith conta ao Invocador o quanto se esforçou até agora. Mas, de algum jeito, essa história parece duvidosa...","storylog.scenario.10210.title":"Tilith Esforçada","storylog.scenario.10211.description":"Zebra ataca de repente no Lago Aldela, mas a ajuda de Elder Grah evita danos graves. Esse inimigo poderoso parece morar numa fortaleza flutuante.","storylog.scenario.10211.title":"O Forte Celeste Restaurado","storylog.scenario.10212.description":"Elder Grah conta a história de Amdahl enquanto pensa no Castelo Avenia. Ele pede ao Invocador que destrua o forte celeste, mas Tilith não se importa...","storylog.scenario.10212.title":"A História de Amdahl","storylog.scenario.10213.description":"Zebra e a Figura Sombria são vistos na Ravina de Gadillian falando sobre como lidar com o Invocador. Qual seria a relação entre eles...?","storylog.scenario.10213.title":"Zebra & uma Figura Sombria","storylog.scenario.10214.description":"Seria e Karl procuram o Invocador no Mausoléu de Alman. Os dois dizem que querem usar seu poder para ajudar a derrubar o forte celeste.","storylog.scenario.10214.title":"Apoio Reconfortante","storylog.scenario.10215.description":"Na Terra dos Mortos, Tilith revela que o nome oficial do forte celeste é Solaris. Ela pretende usar seus poderes para ajudar a se infiltrar nele.","storylog.scenario.10215.title":"Invadindo o Forte","storylog.scenario.10216.description":"Graças aos poderes de Tilith, a infiltração no Forte Celeste Solaris é um sucesso. Zebra vê nisso uma brecha para atacar a deusa exausta.","storylog.scenario.10216.title":"Zebra vs. Tilith","storylog.scenario.10217.description":"Zebra enfim foi derrotado. Porém, ele destrói Solaris tentando levar o Invocador junto. Quem poderá impedir essa tragédia...?","storylog.scenario.10217.title":"Zebra & Grahdens","storylog.scenario.10218.description":"O Invocador chega a Palmyna guiado por Lucius. Os vestígios de um reino que lutou contra os deuses ainda são bem visíveis aqui.","storylog.scenario.10218.title":"O Campo de Batalha","storylog.scenario.10219.description":"Embora estivesse no Castelo de Obselion, Tilith corre até as Ruínas de Dejour para avisar que o selo de Cardes começou a enfraquecer.","storylog.scenario.10219.title":"O Selo se Desfaz","storylog.scenario.10220.description":"Grahdens fica a sós com o Invocador no Castelo de Obselion. Ele conta a história dos 4 Heróis de Palmyna, que selaram Cardes, o Malévolo.","storylog.scenario.10220.title":"4 Heróis de Palmyna","storylog.scenario.10221.description":"Na Trilha Esmeralda, Seria e Karl descobrem que precisam viajar ao mundo espiritual para derrotar Cardes. Mas Seria está agindo de um jeito estranho...","storylog.scenario.10221.title":"Seria Excêntrica","storylog.scenario.10222.description":"Ao passar pelas Ruínas de Grandelt, Tilith revela que o corpo de Cardes está se desintegrando aos poucos e que seus poderes divinos estão descontrolados.","storylog.scenario.10222.title":"A Fúria dos Deuses","storylog.scenario.10223.description":"No Seminário de Arlind, Grahdens expressa suas dúvidas sobre o passado e os movimentos recentes dos deuses. Seus pensamentos parecem influenciar o Invocador.","storylog.scenario.10223.title":"As Dúvidas de Grahdens","storylog.scenario.10224.description":"Karl e Seria acompanham o Invocador até os portões do submundo no Campo de Batalha de Noera. Os dois estão preocupados com Tilith.","storylog.scenario.10224.title":"A Entrada do Hades","storylog.scenario.10225.description":"O Invocador e os outros se separam para encontrar Cardes no Mundo Espiritual Palmyna. Será possível derrotá-lo antes que ele destrua tudo?","storylog.scenario.10225.title":"Batalha contra Cardes","storylog.scenario.10226.description":"Quando todos tentam fugir do submundo em ruínas, Seria se fere. Nessa situação desesperadora, Tilith aparece para salvar o dia.","storylog.scenario.10226.title":"A Deusa Renascida","storylog.scenario.10300.description":"Depois de ouvir o relatório de Paris, Eriole a envia para Lizeria. O que ele poderia estar procurando?","storylog.scenario.10300.title":"A Busca","storylog.scenario.10301.description":"Lugina aparece nas Planícies de Erinecht e afirma ter uma missão muito mais importante que a do Invocador. Sua atitude atrevida não mudou.","storylog.scenario.10301.title":"A Missão de Lugina","storylog.scenario.10302.description":"Ao chegar às Montanhas de Golzo, revela-se que Paris busca um poder adormecido em Lizeria. E parece que Lugina está atrás da mesma coisa.","storylog.scenario.10302.title":"Uma Ambição para Dois","storylog.scenario.10303.description":"No Lago Congelado de Lodan, Lugina supõe erroneamente que Paris traiu o Invocador. Tudo é esclarecido, mas Lugina insiste em treinar...","storylog.scenario.10303.title":"O Treinamento de Lugina","storylog.scenario.10304.description":"Nos Pântanos Intransponíveis, Paris fala sobre a estrutura social de Elgaia. Parece que ela desconfia do poder do Salão dos Invocadores.","storylog.scenario.10304.title":"O Lado Sombrio do Salão","storylog.scenario.10305.description":"Na Floresta Relâmpago Zaljiba, Paris menciona o lado sombrio do Salão dos Invocadores. Lugina é então questionado sobre isso e responde à sua maneira.","storylog.scenario.10305.title":"A Motivação de Lugina","storylog.scenario.10306.description":"Na Cidade Perdida La Veda, Paris compartilha suas dúvidas sobre os deuses e fala da instabilidade do mundo. Ela quer resolver as coisas com as próprias mãos.","storylog.scenario.10306.title":"A Motivação de Paris","storylog.scenario.10307.description":"No alto da Ponte Negra, Lugina diz que vai esmagar qualquer um que ficar em seu caminho e faz uma última confissão ao Invocador antes de seguir em frente.","storylog.scenario.10307.title":"Último Aviso","storylog.scenario.10308.description":"Embora perca para o Invocador, Lugina afirma que não tinha como ter falhado e continua negando a própria derrota.","storylog.scenario.10308.title":"A Derrota de Lugina","storylog.scenario.10309.description":"Na Torre da Destruição, Paris, ferida, ainda se recusa a desistir do poder adormecido da região. Ela não vai perdoar a intromissão do Invocador.","storylog.scenario.10309.title":"A Determinação de Paris","storylog.scenario.10310.description":"Um sistema de defesa capaz de destruir Invocadores. No entanto, o que quer que Paris esteja procurando, e que deveria estar por perto, não está em lugar nenhum...","storylog.scenario.10310.title":"Poder Destrutivo","storylog.scenario.10400.description":"Tilith e o Invocador partem para derrotar Zevalhua, o Supremo. Sem que eles saibam, Eriole e Paris também estão a caminho de Agni...","storylog.scenario.10400.title":"Jornada Dupla","storylog.scenario.10401.description":"No Vale de Glomore, Karl e Seria dizem que querem ajudar a derrotar Zevalhua, enquanto uma mulher misteriosa observa de longe com desdém.","storylog.scenario.10401.title":"Companheiros","storylog.scenario.10402.description":"Depois de chegar à Área Nevada Khelne, a Discípula Mare aparece de repente e pede que Karl a encontre sozinho nas Ruínas de Azura para lhe revelar um certo segredo.","storylog.scenario.10402.title":"O Passado de Karl","storylog.scenario.10403.description":"Seria se preocupa com Karl enquanto vaga pela Floresta de Stokhelna, quando Mare aparece de novo para dizer que Karl caiu direitinho nas mãos dela...","storylog.scenario.10403.title":"Discípula Mare","storylog.scenario.10404.description":"Seria cai na armadilha de Mare nas Ruínas de Azura e sai ferida. Tilith deixa o resgate de Karl nas mãos do Invocador enquanto cuida de Seria.","storylog.scenario.10404.title":"Seria na Armadilha","storylog.scenario.10405.description":"Grahdens espera o Invocador nas Montanhas de Ryvern e compartilha suas lembranças de Karl. Ele diz que vai se deixar capturar pela Mare para libertar Karl.","storylog.scenario.10405.title":"Grahdens e Karl","storylog.scenario.10406.description":"Mare aparece diante do Invocador sozinho na Caverna do Abismo. Bem quando ela se prepara para atacar, Tilith volta e a impede.","storylog.scenario.10406.title":"Tilith Furtiva","storylog.scenario.10407.description":"Mare solta Granvalm contra o Invocador na Torre Branca e foge. Porém, Tilith não vai deixá-la escapar tão fácil.","storylog.scenario.10407.title":"Granvalm, o Branco","storylog.scenario.10408.description":"Mare aparece mais uma vez depois da derrota de Granvalm e, em meio a essa situação terrível, um aliado inesperado salva a pele de todos...","storylog.scenario.10408.title":"Ajuda Inesperada","storylog.scenario.10409.description":"Lugina salva o Invocador em Ryvern para honrar o pedido de Grahdens. Ele também insiste que lhe pediram ajuda no resgate de Karl.","storylog.scenario.10409.title":"Seja Grato","storylog.scenario.10410.description":"No Império de Agni, Lugina está muito animado com a missão de resgate. Ele diz que é a chance perfeita de cumprir sua missão e zombar de Karl.","storylog.scenario.10410.title":"O Esforço de Lugina","storylog.scenario.10411.description":"Cansado de esperar Mare aparecer, Lugina deixa o Invocador na Costa de Agniria e sai sozinho em busca de Karl...","storylog.scenario.10411.title":"Em Ação de Novo","storylog.scenario.10412.description":"Mare finalmente aparece no Planalto de Granasta. Mas ela não está disposta a lutar. Em vez disso, exige que o Invocador a siga para salvar Karl.","storylog.scenario.10412.title":"Mare, a Trapaceira","storylog.scenario.10413.description":"Mare tem lembranças de uma certa pessoa que lutou na guerra contra os deuses enquanto o angustiado Invocador a persegue até o Cume do Trovão Navara.","storylog.scenario.10413.title":"Memórias de Mare","storylog.scenario.10414.description":"O Invocador avança na Tumba do Rei sem perder a esperança de resgatar Karl. Mare não consegue entender tamanha obstinação, o que a leva finalmente a atacar.","storylog.scenario.10414.title":"Forças Opostas","storylog.scenario.10415.description":"Bem quando Mare está prestes a dar o golpe final na Enseada de Lognea, Seria, que deveria estar gravemente ferida, entra em ação para salvar o Invocador.","storylog.scenario.10415.title":"Contra-ataque","storylog.scenario.10416.description":"Uma horda de inimigos aparece no Santuário Oceânico Albina, deixando Seria e o Invocador em apuros. Porém, Lugina chega com Karl libertado bem a tempo.","storylog.scenario.10416.title":"O Resgate","storylog.scenario.10417.description":"Mare é finalmente derrotada pelo Invocador, mas, de repente, Paris aparece para avisar que Grahdens foi capturado.","storylog.scenario.10417.title":"Grahdens Capturado","storylog.scenario.10418.description":"O Invocador finalmente pisa em Mirvana. Tilith explica que ali foi o palco da batalha mais sangrenta da grande guerra contra os deuses.","storylog.scenario.10418.title":"Antigo Campo de Batalha","storylog.scenario.10419.description":"Grahdens foi capturado por Zevalhua, o Supremo. Para salvá-lo, o Invocador e os outros se dividem em grupos na Caverna das Trevas.","storylog.scenario.10419.title":"Equipe de Busca Reunida","storylog.scenario.10420.description":"No Campo Nevado de Arvest, Paris se pergunta, desconfiada, por que os deuses fizeram Grahdens prisioneiro em vez de simplesmente matá-lo logo de cara...","storylog.scenario.10420.title":"Ações Suspeitas","storylog.scenario.10421.description":"Enquanto procura Grahdens no Mar de Árvores de Marleg, Paris convida o Invocador a se juntar à causa dela mais uma vez. Mas Tilith acaba interrompendo.","storylog.scenario.10421.title":"Invocador de Quem?","storylog.scenario.10422.description":"Lugina repreende Paris no Pântano da Chuva Eterna. Porém, pouco antes de as coisas piorarem, Seria entra na brincadeira e começa a discutir com Lugina.","storylog.scenario.10422.title":"Lugina e Seria","storylog.scenario.10423.description":"A localização de Grahdens é confirmada depois da chegada ao Cabo Narasta, e Paris questiona por que Lucius não derrota ele mesmo os Quatro Deuses Caídos.","storylog.scenario.10423.title":"As Dúvidas de Paris","storylog.scenario.10424.description":"Karl agradece a Tilith quando ela revela mais informações sobre Grahdens nas Ruínas de Mirvana. Já Lugina e Seria continuam com a briga de sempre.","storylog.scenario.10424.title":"Eles Nunca Mudam","storylog.scenario.10425.description":"O grupo todo finalmente chega à Torre dos Deuses. Será que eles conseguirão cumprir o objetivo de derrotar Zevalhua, o Supremo, para resgatar Grahdens?","storylog.scenario.10425.title":"Zevalhua, o Supremo","storylog.scenario.10426.description":"Grahdens aparece e revela o segredo do nascimento de Karl. Ao mesmo tempo, Eriole surge de repente e interrompe para falar com o ancião.","storylog.scenario.10426.title":"O Segredo do Nascimento","storylog.scenario.20000.description":"Lin, do Escritório de Pesquisa, pede ao Invocador que investigue as Montanhas de Egor. Dizem que um demônio de gelo está adormecido lá.","storylog.scenario.20000.title":"Demônio da Montanha","storylog.scenario.20001.description":"Lin fala do passado de Skramya. As lendas dizem que o demônio foi selado por um herói depois de tentar destruir a nação que queria manipulá-lo.","storylog.scenario.20001.title":"O Passado do Demônio","storylog.scenario.20002.description":"Lin pede ao Invocador que explore a Caverna de Ignia. Parece que um demônio despertou lá depois dos terremotos em Cordelica...","storylog.scenario.20002.title":"Grudento & Gosmento","storylog.scenario.20003.description":"O Invocador derrota o demônio gigantesco e incontrolável. Lin elogia o Invocador, mas de repente sua atitude muda completamente...","storylog.scenario.20003.title":"O que Lin Detesta","storylog.scenario.20004.description":"Lin repassa ao Invocador uma informação de que o Ninho de Valmodora abriga um demônio. Ela espera que o Invocador reúna mais detalhes.","storylog.scenario.20004.title":"Demônio Gigantesco","storylog.scenario.20005.description":"O Invocador derrota Valmodora enquanto explora o local. Parece que as ruínas abrigavam mesmo algo gigantesco.","storylog.scenario.20005.title":"Ruínas Misteriosas","storylog.scenario.20006.description":"O Invocador sente um poder tremendo emanando do fundo do Lago Subterrâneo de Golzo. Lin tem um mau pressentimento, mas pede uma investigação.","storylog.scenario.20006.title":"O Mau Pressentimento de Lin","storylog.scenario.20007.description":"Lagzal, que jazia adormecido sob a terra, era um deus que buscava destruir os humanos. Parece que Lin ficou bem preocupada com o Invocador durante a expedição.","storylog.scenario.20007.title":"Lagzal, o Deus Caído","storylog.scenario.20008.description":"Ao atravessar a Masmorra de Agni, Lin pede ao Invocador que subjugue um certo \\"ser maligno\\" trancado lá dentro.","storylog.scenario.20008.title":"Escondido na Masmorra","storylog.scenario.20009.description":"Segundo Lin, o que estava trancado lá dentro era o fantasma de um tirano temido, que foi selado pelos próprios vassalos.","storylog.scenario.20009.title":"O Fim de um Tirano"}')}]);